//! Minimal LSP server for tsc-rs.
//!
//! Implements a JSON-RPC 2.0 server that speaks the Language Server Protocol
//! over stdin/stdout. No external LSP crates are used; the protocol messages
//! are hand-rolled with `serde_json`.

use std::collections::{HashMap, HashSet};
use std::io::{self, BufRead};
use std::path::Path;
use std::time::Instant;

use serde_json::{json, Value};

use tsc_rs_ast::{
    ClassMemberKind, CompilerOptions, Diagnostic, DiagnosticCategory, ExportDeclKind, ExprKind,
    ImportClause, PropName, SourceFile, Span, StmtKind, SymbolId,
};
use tsc_rs_query::{QueryEngine, SymbolKind};
use tsc_rs_symbols::{
    SymbolTable, SYM_CLASS, SYM_EXPORT, SYM_GET_ACCESSOR, SYM_IMPORT, SYM_METHOD, SYM_PARAMETER,
    SYM_PROPERTY, SYM_SET_ACCESSOR, SYM_TYPE_PARAMETER,
};
use tsc_rs_types::TypeCheckOutput;

mod lib_stubs;
mod ref_aliases;

/// Public API for the LSP test harness — exposes internal functions without
/// going through the JSON-RPC transport layer.
pub mod harness_api {
    pub use super::{
        completions_at, completions_at_with_prefs, definition_at, extract_token_at,
        find_symbol_at_offset, hover_at, is_inside_string_or_comment, references_at,
        resolve_symbol_type, signature_help_at, ProjectState, KEYWORDS,
    };
}

fn effective_lib_source(options: &CompilerOptions) -> Option<String> {
    if options.no_lib == Some(true) {
        return None;
    }
    tsc_rs_types::load_combined_stdlib_source(options)
        .or_else(|| Some(lib_stubs::LIB_STUBS.to_string()))
}

// ---------------------------------------------------------------------------
// Logging (stderr — shows in VS Code output channel)
// ---------------------------------------------------------------------------

macro_rules! lsp_log {
    ($($arg:tt)*) => {{
        eprintln!("[tsc-rs] {}", format!($($arg)*));
    }};
}

// ---------------------------------------------------------------------------
// Transport: read/write LSP messages (Content-Length framed JSON-RPC)
// ---------------------------------------------------------------------------

/// Read a single LSP message from `reader`.
/// Returns `None` on EOF.
pub fn read_message(reader: &mut impl BufRead) -> io::Result<Option<Value>> {
    // Read headers until blank line.
    let mut content_length: Option<usize> = None;
    loop {
        let mut header = String::new();
        let n = reader.read_line(&mut header)?;
        if n == 0 {
            return Ok(None); // EOF
        }
        let header = header.trim();
        if header.is_empty() {
            break; // end of headers
        }
        if let Some(rest) = header.strip_prefix("Content-Length:") {
            content_length = rest.trim().parse().ok();
        }
        // Ignore other headers (Content-Type, etc.)
    }

    let length = content_length.ok_or_else(|| {
        io::Error::new(io::ErrorKind::InvalidData, "missing Content-Length header")
    })?;

    let mut body = vec![0u8; length];
    reader.read_exact(&mut body)?;
    let value: Value =
        serde_json::from_slice(&body).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
    Ok(Some(value))
}

/// Write a single LSP message (JSON-RPC response or notification) to `writer`.
pub fn write_message(writer: &mut impl io::Write, msg: &Value) -> io::Result<()> {
    let body =
        serde_json::to_string(msg).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
    write!(writer, "Content-Length: {}\r\n\r\n{}", body.len(), body)?;
    writer.flush()
}

// ---------------------------------------------------------------------------
// Document store
// ---------------------------------------------------------------------------

/// Tracks open documents by their URI.
#[derive(Debug, Default)]
pub struct DocumentStore {
    docs: HashMap<String, DocumentState>,
}

#[derive(Debug, Clone)]
pub struct DocumentState {
    pub uri: String,
    pub version: i64,
    pub text: String,
}

impl DocumentStore {
    pub fn open(&mut self, uri: String, version: i64, text: String) {
        self.docs
            .insert(uri.clone(), DocumentState { uri, version, text });
    }

    pub fn change_full(&mut self, uri: &str, version: i64, text: String) {
        if let Some(doc) = self.docs.get_mut(uri) {
            doc.version = version;
            doc.text = text;
        }
    }

    pub fn change_incremental(&mut self, uri: &str, version: i64, changes: &[Value]) {
        if let Some(doc) = self.docs.get_mut(uri) {
            doc.version = version;
            for change in changes {
                if let Some(range) = change.get("range") {
                    let text = change.get("text").and_then(|v| v.as_str()).unwrap_or("");
                    apply_incremental_edit(&mut doc.text, range, text);
                } else {
                    // No range means full replacement
                    if let Some(text) = change.get("text").and_then(|v| v.as_str()) {
                        doc.text = text.to_string();
                    }
                }
            }
        }
    }

    pub fn close(&mut self, uri: &str) {
        self.docs.remove(uri);
    }

    pub fn get(&self, uri: &str) -> Option<&DocumentState> {
        self.docs.get(uri)
    }

    pub fn iter(&self) -> impl Iterator<Item = (&String, &DocumentState)> {
        self.docs.iter()
    }

    pub fn len(&self) -> usize {
        self.docs.len()
    }
}

// ---------------------------------------------------------------------------
// Incremental text edit
// ---------------------------------------------------------------------------

/// Apply an incremental LSP edit to a document string.
/// `range` is a JSON value with `start` and `end` positions (each with `line`
/// and `character` fields). The range is replaced with `new_text`.
fn apply_incremental_edit(text: &mut String, range: &Value, new_text: &str) {
    let start_line = range
        .pointer("/start/line")
        .and_then(|v| v.as_u64())
        .unwrap_or(0) as u32;
    let start_char = range
        .pointer("/start/character")
        .and_then(|v| v.as_u64())
        .unwrap_or(0) as u32;
    let end_line = range
        .pointer("/end/line")
        .and_then(|v| v.as_u64())
        .unwrap_or(0) as u32;
    let end_char = range
        .pointer("/end/character")
        .and_then(|v| v.as_u64())
        .unwrap_or(0) as u32;

    let start_offset = position_to_offset(text, start_line, start_char) as usize;
    let end_offset = position_to_offset(text, end_line, end_char) as usize;

    let end_offset = end_offset.min(text.len());
    let start_offset = start_offset.min(end_offset);

    text.replace_range(start_offset..end_offset, new_text);
}

// ---------------------------------------------------------------------------
// File cache
// ---------------------------------------------------------------------------

/// Cached parse/bind/check results for a single document.
struct CachedFile {
    version: i64,
    options_hash: String,
    file_name: String,
    query_engine: QueryEngine,
    source_file: SourceFile,
    sym_table: SymbolTable,
    check_output: TypeCheckOutput,
    diagnostics: Vec<Diagnostic>,
}

/// Per-URI cache of parse/bind/check results. Returns cached data when the
/// document version has not changed, avoiding redundant work on every request.
struct FileCache {
    files: HashMap<String, CachedFile>,
}

impl FileCache {
    fn new() -> Self {
        FileCache {
            files: HashMap::new(),
        }
    }

    /// Get cached results for a URI, recomputing only if the version changed.
    /// When `project` is provided, imported files are loaded into the QueryEngine
    /// for cross-file type resolution.
    fn get_or_update(
        &mut self,
        uri: &str,
        version: i64,
        file_name: &str,
        text: &str,
        options: CompilerOptions,
        project: Option<&ProjectState>,
    ) -> &CachedFile {
        let options_hash = tsc_rs_project::hash_compiler_options(&options);
        let needs_update = match self.files.get(uri) {
            Some(cached) => cached.version != version || cached.options_hash != options_hash,
            None => true,
        };
        if needs_update {
            let sf = tsc_rs_parser::parse(file_name, text);
            let sym_table = tsc_rs_symbols::bind(&sf);

            // Create a TypeChecker with cross-file type info injected so that
            // member access on imported types (Request, Response, etc.) resolves
            // correctly instead of falling back to Type::Any.
            let mut checker = tsc_rs_types::TypeChecker::new();
            checker.set_current_file_name(file_name);
            // Enable control flow narrowing for better type refinement in the LSP.
            // This makes hover show narrowed types inside if-guards, typeof checks, etc.
            checker.enable_control_flow_narrowing();
            checker.enable_module_resolution_diagnostics();
            let lib_source = effective_lib_source(&options);
            let mut available_files = vec![file_name.to_string()];
            if project.is_none() && lib_source.is_some() {
                available_files.push("__lib__.d.ts".to_string());
            }
            if let Some(proj) = project {
                available_files.extend(proj.files.keys().cloned());
            }
            checker.register_available_files(&available_files);

            let mut lib_sf = None;
            if let Some(lib_source) = &lib_source {
                lib_sf = Some(tsc_rs_parser::parse("__lib__.d.ts", lib_source));
            }
            if let Some(lib_sf) = lib_sf.as_ref() {
                checker.inject_external_types(&[lib_sf]);
            }

            // Inject types from imported files (from project state)
            if let Some(proj) = project {
                let mut imported_sfs = Vec::new();
                for stmt in &sf.statements {
                    if let StmtKind::Import(imp) = &stmt.kind {
                        if let Some(resolved) =
                            tsc_rs_resolver::resolve_module_name(&imp.source, file_name, &options)
                        {
                            if let Some(pf) = proj.get_file(&resolved.resolved_file_name) {
                                imported_sfs.push(tsc_rs_parser::parse(
                                    &resolved.resolved_file_name,
                                    &pf.source,
                                ));
                            }
                        }
                    }
                }
                let imported_refs: Vec<&tsc_rs_ast::SourceFile> = imported_sfs.iter().collect();
                if !imported_refs.is_empty() {
                    checker.inject_external_types(&imported_refs);
                }
            }

            let mut check_out = checker.check_with_options(&sf, &sym_table, &options);
            // Reuse the previous QueryEngine for this URI if available.
            // A fresh QE on every keystroke means re-parsing all 1500
            // autodiscovered .d.ts files every time — felt as ~hundreds
            // of ms of latency in VSCode autocomplete. The QE's
            // parse_cache + persisted-sources logic lets a reused QE
            // skip parsing for any unchanged file (which is every
            // .d.ts in node_modules when the user is editing their own
            // code). We still call `add_source` to replace the user's
            // file text with the new edit, which only invalidates that
            // one entry's parse cache.
            let prev_qe = self.files.remove(uri).map(|cf| cf.query_engine);
            let mut query_engine = match prev_qe {
                Some(qe) if tsc_rs_project::hash_compiler_options(qe.options()) == options_hash => {
                    qe
                }
                _ => QueryEngine::with_options(options.clone()),
            };
            let mut all_diags = Vec::new();
            if query_engine
                .add_source(file_name.to_string(), text.to_string())
                .is_ok()
            {
                // Load imported files into the QueryEngine for cross-file resolution
                Self::load_imports_into_query_engine(
                    &mut query_engine,
                    &sf,
                    file_name,
                    &options,
                    project,
                );
                let _ = query_engine.check_all();
                // Only keep diagnostics from the current file — imported files
                // may have their own errors that shouldn't appear here.
                all_diags = query_engine
                    .raw_diagnostics()
                    .iter()
                    .filter(|d| {
                        d.file_name
                            .as_deref()
                            .map(|f| f == file_name)
                            .unwrap_or(true)
                    })
                    .cloned()
                    .collect();

                // Merge QueryEngine's expression_types into check_output.
                // The QE has cross-file type resolution (inject_external_types)
                // while the per-file check_out doesn't. QE types override any.
                let qe_types = query_engine.get_expression_types(file_name);
                let qe_count = qe_types.len();
                let override_count = std::cell::Cell::new(0u32);
                for (pos, ty_str) in qe_types {
                    let existing = check_out.expression_types.get(&pos);
                    let should_override = match existing {
                        None => true,
                        Some(e) => e == "any" && ty_str != "any",
                    };
                    if should_override {
                        check_out.expression_types.insert(pos, ty_str);
                        override_count.set(override_count.get() + 1);
                    }
                }
                if qe_count > 0 || override_count.get() > 0 {
                    lsp_log!(
                        "  QE merge: {} types from QE, {} overrides applied",
                        qe_count,
                        override_count.get()
                    );
                }
            }
            if all_diags.is_empty() {
                all_diags = sf.diagnostics.clone();
                for bd in &sym_table.diagnostics {
                    all_diags.push(Diagnostic {
                        code: 2300,
                        message: bd.message.clone(),
                        category: DiagnosticCategory::Error,
                        file_name: Some(bd.file_name.clone()),
                        span: Some(bd.span),
                        related: None,
                    });
                }
                all_diags.extend(check_out.diagnostics.clone());
            }

            self.files.insert(
                uri.to_string(),
                CachedFile {
                    version,
                    options_hash,
                    file_name: file_name.to_string(),
                    query_engine,
                    source_file: sf,
                    sym_table,
                    check_output: check_out,
                    diagnostics: all_diags,
                },
            );
        }
        self.files.get(uri).unwrap()
    }

    /// Scan the source file for import declarations and recursively load
    /// resolved files into the QueryEngine so `check_all()` can resolve
    /// cross-file types.
    ///
    /// Follows imports up to `MAX_IMPORT_DEPTH` levels deep to capture
    /// transitive type dependencies (e.g., page-loader.ts → bext-config.ts
    /// → ../../bext.config.ts).
    fn load_imports_into_query_engine(
        qe: &mut QueryEngine,
        sf: &SourceFile,
        file_name: &str,
        options: &CompilerOptions,
        project: Option<&ProjectState>,
    ) {
        const MAX_IMPORT_DEPTH: u8 = 3;
        // Max files to load to prevent runaway resolution in huge projects
        const MAX_IMPORT_FILES: usize = 30;

        let mut loaded = HashSet::new();
        loaded.insert(file_name.to_string());

        let lib_stub_name = "__lib__.d.ts";
        let lib_source = if let Some(proj) = project {
            proj.files.get(lib_stub_name).map(|pf| pf.source.clone())
        } else {
            None
        };
        if let Some(lib_source) = lib_source.or_else(|| effective_lib_source(options)) {
            let _ = qe.add_source(lib_stub_name.to_string(), lib_source);
            loaded.insert(lib_stub_name.to_string());
        }

        // Collect the direct imports of the current file as the first layer
        let mut pending: Vec<(String, String)> = Vec::new(); // (specifier, containing_file)
        for stmt in &sf.statements {
            if let StmtKind::Import(imp) = &stmt.kind {
                pending.push((imp.source.clone(), file_name.to_string()));
            }
        }

        let mut depth: u8 = 0;
        while !pending.is_empty() && depth < MAX_IMPORT_DEPTH && loaded.len() < MAX_IMPORT_FILES {
            depth += 1;
            let current_batch = std::mem::take(&mut pending);
            // Next-level imports discovered from files loaded in this batch
            let mut next_pending: Vec<(String, String)> = Vec::new();

            for (module_specifier, containing_file) in &current_batch {
                if loaded.len() >= MAX_IMPORT_FILES {
                    break;
                }
                let resolved = tsc_rs_resolver::resolve_module_name(
                    module_specifier,
                    containing_file,
                    options,
                );
                let Some(resolved) = resolved else {
                    continue;
                };
                let resolved_path = resolved.resolved_file_name;
                if loaded.contains(&resolved_path) {
                    continue;
                }
                loaded.insert(resolved_path.clone());

                // Get source from project state or disk.
                // Skip very large files (>200KB) to avoid slow QE analysis.
                let source_text = project
                    .and_then(|p| p.files.get(&resolved_path).map(|pf| pf.source.clone()))
                    .or_else(|| {
                        let meta = std::fs::metadata(&resolved_path).ok()?;
                        if meta.len() > 200_000 {
                            return None; // Skip huge .d.ts files
                        }
                        std::fs::read_to_string(&resolved_path).ok()
                    });

                if let Some(src) = &source_text {
                    // Fast scan for import specifiers to discover transitive deps.
                    // Avoids a full parse — the QE will parse in check_all().
                    if depth < MAX_IMPORT_DEPTH {
                        for specifier in fast_extract_import_specifiers(src) {
                            next_pending.push((specifier, resolved_path.clone()));
                        }
                    }
                    let _ = qe.add_source(resolved_path, src.clone());
                }
            }
            pending = next_pending;
        }
    }

    fn remove(&mut self, uri: &str) {
        self.files.remove(uri);
    }

    fn len(&self) -> usize {
        self.files.len()
    }

    fn get(&self, uri: &str) -> Option<&CachedFile> {
        self.files.get(uri)
    }

    fn iter(&self) -> impl Iterator<Item = (&String, &CachedFile)> {
        self.files.iter()
    }
}

// ---------------------------------------------------------------------------
// Project state (multi-file awareness)
// ---------------------------------------------------------------------------

/// Parsed and bound state for a single project file.
struct ProjectFile {
    source: String,
    sym_table: SymbolTable,
}

/// Project-wide state built on `initialize`.
///
/// Holds all discovered project files (parsed + bound), a cross-file export
/// map, the resolved compiler options, and the parsed lib stubs.
pub struct ProjectState {
    /// All project files keyed by their absolute file path.
    files: HashMap<String, ProjectFile>,
    /// Files explicitly loaded from the root project config.
    configured_files: HashSet<String>,
    /// Cross-file export map: module file path -> vec of (export name, symbol id).
    export_map: HashMap<String, Vec<(String, SymbolId)>>,
    /// Compiler options from the root project config (or defaults).
    options: CompilerOptions,
    /// Root directory of the project (from rootUri).
    root_path: String,
}

fn project_config_path(root_path: &str) -> Option<String> {
    let root = Path::new(root_path);
    for config_name in ["tsconfig.json", "jsconfig.json"] {
        let candidate = root.join(config_name);
        if candidate.exists() {
            return Some(candidate.to_string_lossy().into_owned());
        }
    }
    None
}

impl ProjectState {
    fn normalize_project_path(&self, file_name: &str) -> String {
        let path = Path::new(file_name);
        if path.is_absolute() || file_name == "__lib__.d.ts" {
            file_name.to_string()
        } else {
            Path::new(&self.root_path)
                .join(path)
                .to_string_lossy()
                .into_owned()
        }
    }

    /// Build a lightweight project state from pre-analyzed files (for testing).
    pub fn from_file_map(files: HashMap<String, (String, SymbolTable)>) -> Self {
        let pf_map: HashMap<String, ProjectFile> = files
            .into_iter()
            .map(|(name, (source, sym_table))| (name, ProjectFile { source, sym_table }))
            .collect();
        ProjectState {
            files: pf_map,
            configured_files: HashSet::new(),
            export_map: HashMap::new(),
            options: CompilerOptions::default(),
            root_path: String::new(),
        }
    }

    /// Build project state from a root directory.
    fn from_root(root_path: &str) -> Self {
        let mut state = ProjectState {
            files: HashMap::new(),
            configured_files: HashSet::new(),
            export_map: HashMap::new(),
            options: CompilerOptions::default(),
            root_path: root_path.to_string(),
        };

        // Try loading a root project config, preferring tsconfig.json when both
        // TypeScript and JavaScript configs exist.
        if let Some(config_path) = project_config_path(root_path) {
            if let Ok(parsed) = tsc_rs_project::parse_tsconfig(&config_path) {
                state.options = parsed.options.clone();
                // Parse and bind all discovered project files
                for file_name in &parsed.file_names {
                    let normalized = state.normalize_project_path(file_name);
                    state.configured_files.insert(normalized.clone());
                    state.load_file(&normalized);
                }
            }
        }

        // Load the standard library unless noLib disables it.
        state.load_lib_stubs();

        // Load @types packages from tsconfig "types" field and auto-discover.
        state.load_at_types();

        // Build the cross-file export map.
        state.rebuild_export_map();

        state
    }

    /// Parse and bind a single file, adding it to the project.
    fn load_file(&mut self, file_name: &str) {
        if self.files.contains_key(file_name) {
            return;
        }
        let source = match std::fs::read_to_string(file_name) {
            Ok(s) => s,
            Err(_) => return,
        };
        let sf = tsc_rs_parser::parse(file_name, &source);
        let sym_table = tsc_rs_symbols::bind(&sf);
        self.files
            .insert(file_name.to_string(), ProjectFile { source, sym_table });
    }

    /// Parse the standard library and add it to the project files.
    fn load_lib_stubs(&mut self) {
        let stub_name = "__lib__.d.ts";
        if self.files.contains_key(stub_name) {
            return;
        }
        let Some(source) = effective_lib_source(&self.options) else {
            return;
        };
        let sf = tsc_rs_parser::parse(stub_name, &source);
        let sym_table = tsc_rs_symbols::bind(&sf);
        self.files
            .insert(stub_name.to_string(), ProjectFile { source, sym_table });
    }

    /// Load type declaration packages from `@types/` in node_modules.
    ///
    /// If tsconfig specifies `"types": ["node", "bun"]`, loads those specifically.
    /// Otherwise, auto-discovers `@types/*` packages in the nearest node_modules.
    /// Only loads the entry-point `.d.ts` file (not the entire package tree).
    fn load_at_types(&mut self) {
        let root = Path::new(&self.root_path);

        // Find the nearest node_modules/@types directory
        let mut search_dir = root.to_path_buf();
        let at_types_dir = loop {
            let candidate = search_dir.join("node_modules").join("@types");
            if candidate.is_dir() {
                break Some(candidate);
            }
            if !search_dir.pop() {
                break None;
            }
        };

        let Some(at_types_dir) = at_types_dir else {
            return;
        };

        let types_to_load: Vec<String> = match &self.options.types {
            Some(list) => {
                // Explicit `compilerOptions.types`. `[]` → load nothing
                // (caller opted out); `[..]` → load just those.
                if list.is_empty() {
                    return;
                }
                list.clone()
            }
            None => {
                // Auto-discover: load all @types/* packages (TypeScript default)
                let Ok(entries) = std::fs::read_dir(&at_types_dir) else {
                    return;
                };
                entries
                    .filter_map(|e| e.ok())
                    .filter(|e| e.path().is_dir())
                    .filter_map(|e| e.file_name().into_string().ok())
                    // Skip scoped packages (@types/@foo) — those are not standard
                    .filter(|name| !name.starts_with('.') && !name.starts_with('@'))
                    .collect()
            }
        };

        for type_name in &types_to_load {
            let pkg_dir = at_types_dir.join(type_name);
            if !pkg_dir.is_dir() {
                continue;
            }

            // Find the entry point: package.json "types"/"typings" field, or index.d.ts
            let entry_file = Self::find_types_entry(&pkg_dir);
            if let Some(entry) = entry_file {
                self.load_file(&entry);
            }
        }
    }

    /// Find the `.d.ts` entry point for a type package.
    fn find_types_entry(pkg_dir: &Path) -> Option<String> {
        // Try package.json types/typings field
        let pkg_json = pkg_dir.join("package.json");
        if let Ok(content) = std::fs::read_to_string(&pkg_json) {
            for field in ["types", "typings", "main"] {
                if let Some(value) = extract_pkg_json_field(&content, field) {
                    let resolved = pkg_dir.join(&value);
                    if resolved.is_file() {
                        return Some(resolved.to_string_lossy().into_owned());
                    }
                }
            }
        }
        // Fallback: index.d.ts
        let index = pkg_dir.join("index.d.ts");
        if index.is_file() {
            return Some(index.to_string_lossy().into_owned());
        }
        None
    }

    /// Rebuild the export map from all project files.
    fn rebuild_export_map(&mut self) {
        self.export_map.clear();
        for (path, pf) in &self.files {
            let mut exports = Vec::new();
            for sym in &pf.sym_table.symbols {
                if sym.flags & SYM_EXPORT != 0 {
                    exports.push((sym.name.clone(), sym.id));
                }
            }
            if !exports.is_empty() {
                self.export_map.insert(path.clone(), exports);
            }
        }
    }

    /// Update a single file (e.g. after editing) and refresh the export map.
    fn update_file(&mut self, file_name: &str, source: &str) {
        let sf = tsc_rs_parser::parse(file_name, source);
        let sym_table = tsc_rs_symbols::bind(&sf);
        self.files.insert(
            file_name.to_string(),
            ProjectFile {
                source: source.to_string(),
                sym_table,
            },
        );
        // Rebuild just this file's exports
        let mut exports = Vec::new();
        if let Some(pf) = self.files.get(file_name) {
            for sym in &pf.sym_table.symbols {
                if sym.flags & SYM_EXPORT != 0 {
                    exports.push((sym.name.clone(), sym.id));
                }
            }
        }
        if exports.is_empty() {
            self.export_map.remove(file_name);
        } else {
            self.export_map.insert(file_name.to_string(), exports);
        }
    }

    /// Restore a file from disk after closing an edited document. If the file
    /// no longer exists on disk, drop it from the project state.
    fn restore_file_from_disk(&mut self, file_name: &str) {
        if file_name == "__lib__.d.ts" {
            return;
        }
        if !self.configured_files.contains(file_name) {
            self.files.remove(file_name);
            self.export_map.remove(file_name);
            return;
        }
        match std::fs::read_to_string(file_name) {
            Ok(source) => self.update_file(file_name, &source),
            Err(_) => {
                self.files.remove(file_name);
                self.export_map.remove(file_name);
            }
        }
    }

    /// Resolve an import specifier from a containing file to a resolved path.
    fn resolve_import(&self, module_specifier: &str, containing_file: &str) -> Option<String> {
        let resolved =
            tsc_rs_resolver::resolve_module_name(module_specifier, containing_file, &self.options);
        if let Some(r) = resolved {
            return Some(r.resolved_file_name);
        }
        // Fallback: simple relative path resolution against known files.
        // This handles virtual file systems (e.g., test harness) where the
        // resolver can't check file existence on disk.
        if module_specifier.starts_with("./") || module_specifier.starts_with("../") {
            let dir = Path::new(containing_file)
                .parent()
                .unwrap_or(Path::new("/"));
            let candidate_base = dir.join(module_specifier.trim_start_matches("./"));
            for ext in &[".ts", ".tsx", ".js", ".jsx", ".d.ts", ""] {
                let candidate = format!("{}{}", candidate_base.display(), ext);
                if self.files.contains_key(&candidate) {
                    return Some(candidate);
                }
            }
            // Try with /index variants
            for ext in &["/index.ts", "/index.d.ts", "/index.js"] {
                let candidate = format!("{}{}", candidate_base.display(), ext);
                if self.files.contains_key(&candidate) {
                    return Some(candidate);
                }
            }
        }
        None
    }

    /// Get the project file for a given path (if loaded).
    fn get_file(&self, path: &str) -> Option<&ProjectFile> {
        self.files.get(path)
    }
}

#[derive(Default)]
struct WorkspaceProjects {
    projects: HashMap<String, ProjectState>,
}

impl WorkspaceProjects {
    fn from_roots(roots: Vec<String>) -> Self {
        let mut projects = HashMap::new();
        for root in roots {
            projects.insert(root.clone(), ProjectState::from_root(&root));
        }
        Self { projects }
    }

    fn matching_root(&self, file_name: &str) -> Option<String> {
        let file_path = Path::new(file_name);
        self.projects
            .values()
            .filter(|project| {
                project.files.contains_key(file_name) || file_path.starts_with(&project.root_path)
            })
            .max_by_key(|project| {
                (
                    project.files.contains_key(file_name),
                    project.root_path.len(),
                )
            })
            .map(|project| project.root_path.clone())
    }

    fn project_for_file(&self, file_name: &str) -> Option<&ProjectState> {
        let root = self.matching_root(file_name)?;
        self.projects.get(&root)
    }

    fn project_for_file_mut(&mut self, file_name: &str) -> Option<&mut ProjectState> {
        let root = self.matching_root(file_name)?;
        self.projects.get_mut(&root)
    }

    fn ensure_for_file(&mut self, file_name: &str) {
        if file_name == "__lib__.d.ts" {
            return;
        }
        // Always ensure the project rooted at the *nearest* tsconfig to the
        // file exists — even if a broader ancestor project (e.g. a monorepo
        // root) already prefix-matches. Otherwise a file under
        // `<repo>/apps/app/...` would inherit the repo-root project's options
        // and miss `apps/app/tsconfig.json`'s `paths`/`baseUrl`, breaking path
        // alias resolution. `matching_root` prefers the longest root_path, so
        // the nearer project wins once it is loaded.
        let Some(root) = infer_project_root_for_file(file_name) else {
            return;
        };
        self.projects
            .entry(root.clone())
            .or_insert_with(|| ProjectState::from_root(&root));
    }

    fn options_for_file(&self, file_name: &str) -> CompilerOptions {
        self.project_for_file(file_name)
            .map(|project| project.options.clone())
            .unwrap_or_default()
    }

    fn update_file(&mut self, file_name: &str, text: &str) {
        self.ensure_for_file(file_name);
        if let Some(project) = self.project_for_file_mut(file_name) {
            project.update_file(file_name, text);
        }
    }

    fn restore_file_from_disk(&mut self, file_name: &str) {
        if let Some(project) = self.project_for_file_mut(file_name) {
            project.restore_file_from_disk(file_name);
        }
    }

    fn reload_root(&mut self, root: &str) {
        self.projects
            .insert(root.to_string(), ProjectState::from_root(root));
    }

    fn add_root(&mut self, root: &str) {
        self.projects
            .entry(root.to_string())
            .or_insert_with(|| ProjectState::from_root(root));
    }

    fn remove_root(&mut self, root: &str) {
        self.projects.remove(root);
    }

    fn handle_watched_file_change(&mut self, file_name: &str) {
        if let Some(root) = config_root_for_path(file_name) {
            self.reload_root(&root);
            return;
        }
        self.ensure_for_file(file_name);
        self.restore_file_from_disk(file_name);
    }

    fn iter(&self) -> impl Iterator<Item = &ProjectState> {
        self.projects.values()
    }

    fn project_count(&self) -> usize {
        self.projects.len()
    }

    fn total_file_count(&self) -> usize {
        self.projects.values().map(|p| p.files.len()).sum()
    }
}

fn has_uri_scheme(value: &str) -> bool {
    let Some(colon_idx) = value.find(':') else {
        return false;
    };
    if colon_idx <= 1 {
        return false;
    }
    value[..colon_idx]
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '+' | '-' | '.'))
}

fn infer_project_root_for_file(file_name: &str) -> Option<String> {
    if has_uri_scheme(file_name) {
        return None;
    }
    let file_path = Path::new(file_name);
    let start_dir = if file_path.is_dir() {
        file_path
    } else {
        file_path.parent()?
    };
    for ancestor in start_dir.ancestors() {
        if project_config_path(ancestor.to_str()?).is_some() {
            return Some(ancestor.to_string_lossy().into_owned());
        }
    }
    Some(start_dir.to_string_lossy().into_owned())
}

fn config_root_for_path(file_name: &str) -> Option<String> {
    let path = Path::new(file_name);
    let file_name = path.file_name()?.to_str()?;
    let is_config = file_name == "tsconfig.json"
        || file_name == "jsconfig.json"
        || (file_name.starts_with("tsconfig.") && file_name.ends_with(".json"));
    if !is_config {
        return None;
    }
    path.parent()
        .map(|parent| parent.to_string_lossy().into_owned())
}

fn project_roots_from_initialize(msg: &Value) -> Vec<String> {
    let mut roots = Vec::new();
    if let Some(root_uri) = msg.pointer("/params/rootUri").and_then(|v| v.as_str()) {
        roots.push(uri_to_filename(root_uri));
    }
    if let Some(workspace_folders) = msg
        .pointer("/params/workspaceFolders")
        .and_then(|v| v.as_array())
    {
        for folder in workspace_folders {
            if let Some(uri) = folder.get("uri").and_then(|v| v.as_str()) {
                roots.push(uri_to_filename(uri));
            }
        }
    }
    if let Some(root_path) = msg.pointer("/params/rootPath").and_then(|v| v.as_str()) {
        roots.push(root_path.to_string());
    }
    let mut deduped = Vec::new();
    let mut seen = HashSet::new();
    for root in roots {
        if seen.insert(root.clone()) {
            deduped.push(root);
        }
    }
    deduped
}

// ---------------------------------------------------------------------------
// Position helpers
// ---------------------------------------------------------------------------

/// Convert a zero-based (line, character) pair to a byte offset in `text`.
pub fn position_to_offset(text: &str, line: u32, character: u32) -> u32 {
    let mut current_line = 0u32;
    let mut offset = 0u32;
    for ch in text.chars() {
        if current_line == line {
            if character == 0 {
                return offset;
            }
            // Walk `character` UTF-16 code units within the line.
            let mut col = 0u32;
            for ch2 in text[offset as usize..].chars() {
                if ch2 == '\n' {
                    break;
                }
                if col == character {
                    return offset + ch2.len_utf8() as u32 - ch2.len_utf8() as u32;
                }
                offset += ch2.len_utf8() as u32;
                col += if ch2.len_utf16() > 1 { 2 } else { 1 };
            }
            return offset;
        }
        if ch == '\n' {
            current_line += 1;
        }
        offset += ch.len_utf8() as u32;
    }
    offset
}

/// Convert a byte offset to a zero-based (line, character) pair.
pub fn offset_to_position(text: &str, offset: u32) -> (u32, u32) {
    let offset = offset as usize;
    let mut line = 0u32;
    let mut col = 0u32; // UTF-16 code units
    for (i, ch) in text.char_indices() {
        if i >= offset {
            return (line, col);
        }
        if ch == '\n' {
            line += 1;
            col = 0;
        } else {
            col += if ch.len_utf16() > 1 { 2 } else { 1 };
        }
    }
    (line, col)
}

fn hex_value(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

fn percent_decode(input: &str) -> Option<String> {
    let bytes = input.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            let hi = hex_value(bytes[i + 1])?;
            let lo = hex_value(bytes[i + 2])?;
            out.push((hi << 4) | lo);
            i += 3;
            continue;
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf8(out).ok()
}

fn percent_encode_path(path: &str) -> String {
    let mut encoded = String::with_capacity(path.len());
    for byte in path.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~' | b'/' | b':') {
            encoded.push(byte as char);
        } else {
            encoded.push_str(&format!("%{byte:02X}"));
        }
    }
    encoded
}

/// Extract a local filename from a file URI.
/// Extract the last path component from a URI for compact logging.
fn short_uri(uri: &str) -> &str {
    uri.rsplit('/').next().unwrap_or(uri)
}

/// Fast import specifier extraction without full parsing.
///
/// Scans source text for `import ... from "specifier"` and `import "specifier"`
/// patterns using simple string matching. Much faster than a full parse when
/// we only need to discover transitive dependencies for the QueryEngine.
fn fast_extract_import_specifiers(source: &str) -> Vec<String> {
    let mut specifiers = Vec::new();
    let bytes = source.as_bytes();
    let len = bytes.len();
    let mut i = 0;

    while i < len {
        // Skip to next potential import/export keyword
        if i + 6 >= len {
            break;
        }

        // Look for `import` or `export` at word boundary
        let is_import = &bytes[i..i + 6] == b"import"
            && (i == 0 || !is_ident_byte(bytes[i - 1]))
            && (i + 6 >= len || !is_ident_byte(bytes[i + 6]));
        let is_export = i + 6 < len
            && &bytes[i..i + 6] == b"export"
            && (i == 0 || !is_ident_byte(bytes[i - 1]))
            && (i + 6 >= len || !is_ident_byte(bytes[i + 6]));

        if !is_import && !is_export {
            i += 1;
            continue;
        }

        // Find the `from` keyword or direct string after import
        // Scan forward for a string literal (the module specifier)
        let start = i;
        i += 6; // skip `import`/`export`

        // Look for `from` or a direct string on the same statement (up to `;` or newline)
        let mut found_from = false;
        let stmt_end = source[start..].find(';').map(|p| start + p).unwrap_or(len);
        let line_end = source[start..].find('\n').map(|p| start + p).unwrap_or(len);
        let search_end = stmt_end.min(line_end + 100).min(len); // allow multi-line imports

        while i < search_end {
            // Look for `from` keyword
            if i + 4 <= search_end
                && &bytes[i..i + 4] == b"from"
                && (i == 0 || !is_ident_byte(bytes[i - 1]))
                && (i + 4 >= len || !is_ident_byte(bytes[i + 4]))
            {
                found_from = true;
                i += 4;
                continue;
            }

            // Look for string literal (the specifier)
            if (found_from || is_import) && (bytes[i] == b'"' || bytes[i] == b'\'') {
                let quote = bytes[i];
                let str_start = i + 1;
                i += 1;
                while i < search_end && bytes[i] != quote {
                    if bytes[i] == b'\\' {
                        i += 1; // skip escape
                    }
                    i += 1;
                }
                if i < search_end {
                    let spec = &source[str_start..i];
                    if !spec.is_empty() && found_from {
                        specifiers.push(spec.to_string());
                    }
                    i += 1; // skip closing quote
                    break; // done with this import
                }
            }

            i += 1;
        }
    }
    specifiers
}

/// Simple JSON string field extractor (avoids serde dependency).
/// Finds `"field": "value"` and returns `value`.
fn extract_pkg_json_field(json: &str, field: &str) -> Option<String> {
    let pattern = format!("\"{}\"", field);
    let idx = json.find(&pattern)?;
    let rest = &json[idx + pattern.len()..];
    // Skip whitespace and colon
    let rest = rest.trim_start();
    let rest = rest.strip_prefix(':')?;
    let rest = rest.trim_start();
    // Extract string value
    let rest = rest.strip_prefix('"')?;
    let end = rest.find('"')?;
    Some(rest[..end].to_string())
}

/// Extract the last path component from a file path for compact logging.
fn short_path(p: &str) -> &str {
    let p = p.trim_end_matches('/').trim_end_matches('\\');
    p.rsplit(|c| c == '/' || c == '\\').next().unwrap_or(p)
}

/// Extract the identifier/token at a byte offset for logging.
pub fn extract_token_at(text: &str, offset: u32) -> String {
    let bytes = text.as_bytes();
    let off = offset as usize;
    if off >= bytes.len() {
        return String::new();
    }
    // Walk backwards to find token start
    let mut start = off;
    while start > 0 && is_ident_byte(bytes[start - 1]) {
        start -= 1;
    }
    // Include leading `#` for private names
    if start > 0 && bytes[start - 1] == b'#' {
        start -= 1;
    }
    // Walk forward to find token end
    let mut end = off;
    // If we're on a `#`, skip it and continue with ident chars
    if end < bytes.len() && bytes[end] == b'#' {
        end += 1;
    }
    while end < bytes.len() && is_ident_byte(bytes[end]) {
        end += 1;
    }
    if start == end {
        return String::new();
    }
    String::from_utf8_lossy(&bytes[start..end]).into_owned()
}

fn is_ident_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || matches!(b, b'_' | b'$')
}

fn uri_to_filename(uri: &str) -> String {
    let Some(rest) = uri.strip_prefix("file://") else {
        return uri.to_string();
    };
    let rest = rest.strip_prefix("localhost").unwrap_or(rest);
    let decoded = percent_decode(rest).unwrap_or_else(|| rest.to_string());
    #[cfg(windows)]
    {
        if decoded.starts_with('/') && decoded.as_bytes().get(2) == Some(&b':') {
            decoded[1..].to_string()
        } else {
            decoded
        }
    }
    #[cfg(not(windows))]
    {
        decoded
    }
}

fn filename_to_uri(file_name: &str) -> String {
    #[cfg(windows)]
    let normalized = file_name.replace('\\', "/");
    #[cfg(not(windows))]
    let normalized = file_name.to_string();

    if normalized.starts_with('/') {
        format!("file://{}", percent_encode_path(&normalized))
    } else {
        format!("file:///{}", percent_encode_path(&normalized))
    }
}

fn text_for_file<'a>(
    file_name: &str,
    current_file_name: &str,
    current_text: &'a str,
    project: Option<&'a ProjectState>,
) -> &'a str {
    if file_name == current_file_name {
        current_text
    } else {
        project
            .and_then(|proj| proj.get_file(file_name))
            .map(|pf| pf.source.as_str())
            .unwrap_or(current_text)
    }
}

fn append_workspace_symbols_for_file(
    symbols: &mut Vec<Value>,
    query_lower: &str,
    uri: &str,
    text: &str,
    sym_table: &SymbolTable,
) {
    for sym in &sym_table.symbols {
        if sym.name.is_empty() {
            continue;
        }
        if !query_lower.is_empty() && !sym.name.to_lowercase().contains(query_lower) {
            continue;
        }
        let kind = symbol_kind_for_flags(sym.flags);
        if let Some(decl) = sym.declarations.first() {
            let (sl, sc) = offset_to_position(text, decl.span.start);
            let (el, ec) = offset_to_position(text, decl.span.end);
            symbols.push(json!({
                "name": sym.name,
                "kind": kind,
                "location": {
                    "uri": uri,
                    "range": {
                        "start": { "line": sl, "character": sc },
                        "end": { "line": el, "character": ec }
                    }
                }
            }));
        }
    }
}

// ---------------------------------------------------------------------------
// Diagnostics pipeline
// ---------------------------------------------------------------------------

/// Run parse -> bind -> check on a document and return the combined diagnostics.
pub fn diagnose(file_name: &str, source: &str) -> (Vec<Diagnostic>, SymbolTable) {
    let sf = tsc_rs_parser::parse(file_name, source);
    let sym_table = tsc_rs_symbols::bind(&sf);
    let check_out = tsc_rs_types::check(&sf, &sym_table);

    let mut all_diags: Vec<Diagnostic> = sf.diagnostics;

    // Convert binder diagnostics.
    for bd in &sym_table.diagnostics {
        all_diags.push(Diagnostic {
            code: 2300,
            message: bd.message.clone(),
            category: DiagnosticCategory::Error,
            file_name: Some(bd.file_name.clone()),
            span: Some(bd.span),
            related: None,
        });
    }

    all_diags.extend(check_out.diagnostics);
    (all_diags, sym_table)
}

/// Convert internal diagnostics to LSP-format JSON.
fn diagnostics_to_lsp(diagnostics: &[Diagnostic], text: &str) -> Value {
    let lsp_diags: Vec<Value> = diagnostics
        .iter()
        .map(|d| {
            let span = d.span.unwrap_or(Span::new(0, 0));
            let (start_line, start_char) = offset_to_position(text, span.start);
            let (end_line, end_char) = offset_to_position(text, span.end);
            let severity = match d.category {
                DiagnosticCategory::Error => 1,
                DiagnosticCategory::Warning => 2,
                DiagnosticCategory::Suggestion => 3,
                DiagnosticCategory::Message => 4,
            };
            json!({
                "range": {
                    "start": { "line": start_line, "character": start_char },
                    "end": { "line": end_line, "character": end_char }
                },
                "severity": severity,
                "code": d.code,
                "source": "tsc-rs",
                "message": d.message
            })
        })
        .collect();
    Value::Array(lsp_diags)
}

