fn jsdoc_keyword_entries(names: &[&str], at_prefix: bool) -> Vec<Value> {
    names
        .iter()
        .map(|n| {
            let name = if at_prefix {
                format!("@{}", n)
            } else {
                (*n).to_string()
            };
            json!({ "label": name, "kind": 14 })
        })
        .collect()
}

/// Raw parameter item texts of the declaration a JSDoc comment (ending at
/// byte `close`, exclusive of `*/`) attaches to. Mirrors the attachment rule
/// used for @param name completions: first `(...)` after `*/` unless a `;`
/// or another comment starts first.
fn jsdoc_following_param_items(source: &str, close: usize) -> Vec<String> {
    let mut items: Vec<String> = Vec::new();
    if close + 2 > source.len() {
        return items;
    }
    let after = &source[close + 2..];
    let scan = &after[..after.len().min(300)];
    let stop = scan.find(';').min(scan.find("/*")).unwrap_or(scan.len());
    let Some(lp) = scan[..stop.min(scan.len())].find('(') else {
        return items;
    };
    let seg = &scan[lp + 1..];
    let mut depth = 1i32;
    let mut end = seg.len();
    for (k, b) in seg.bytes().enumerate() {
        match b {
            b'(' | b'[' | b'{' | b'<' => depth += 1,
            b')' | b']' | b'}' | b'>' => {
                depth -= 1;
                if depth == 0 {
                    end = k;
                    break;
                }
            }
            _ => {}
        }
    }
    let list = &seg[..end];
    let lb = list.as_bytes();
    let mut d = 0i32;
    let mut item_start = 0usize;
    for k in 0..=list.len() {
        let at_end = k == list.len();
        if !at_end {
            match lb[k] {
                b'(' | b'[' | b'{' | b'<' => d += 1,
                b')' | b']' | b'}' | b'>' => d -= 1,
                _ => {}
            }
        }
        if at_end || (lb[k] == b',' && d == 0) {
            let item = list[item_start..k].trim();
            if !item.is_empty() {
                items.push(item.to_string());
            }
            item_start = k + 1;
        }
    }
    items
}

/// Split the top-level members of an object destructuring pattern body
/// (the text between its braces).
fn split_pattern_members(body: &str) -> Vec<String> {
    let mut out = Vec::new();
    let b = body.as_bytes();
    let mut d = 0i32;
    let mut start = 0usize;
    for k in 0..=body.len() {
        let at_end = k == body.len();
        if !at_end {
            match b[k] {
                b'(' | b'[' | b'{' => d += 1,
                b')' | b']' | b'}' => d -= 1,
                _ => {}
            }
        }
        if at_end || (b[k] == b',' && d == 0) {
            let m = body[start..k].trim();
            if !m.is_empty() {
                out.push(m.to_string());
            }
            start = k + 1;
        }
    }
    out
}

/// Split `item` at its top-level `=` (outside any brackets), returning
/// (pattern, Some(default_text)).
fn split_top_level_default(item: &str) -> (&str, Option<&str>) {
    let b = item.as_bytes();
    let mut d = 0i32;
    for k in 0..item.len() {
        match b[k] {
            b'(' | b'[' | b'{' => d += 1,
            b')' | b']' | b'}' => d -= 1,
            b'=' if d == 0
                && b.get(k + 1) != Some(&b'=')
                && (k == 0
                    || (b[k - 1] != b'='
                        && b[k - 1] != b'!'
                        && b[k - 1] != b'<'
                        && b[k - 1] != b'>')) =>
            {
                return (item[..k].trim_end(), Some(item[k + 1..].trim()));
            }
            _ => {}
        }
    }
    (item, None)
}

/// JSDoc type text inferred from a default-value expression, plus whether
/// the default text is simple enough to inline into `[name=default]`.
/// `tuple_context` renders array literals as tuples (`[number, boolean]`,
/// used when the member destructures with an array pattern) instead of the
/// union-array form (`(number | boolean)[]`).
fn jsdoc_default_type(def: &str, tuple_context: bool) -> (String, bool) {
    let d = def.trim();
    let first = d.bytes().next().unwrap_or(b' ');
    if first.is_ascii_digit() || (first == b'-' && d.len() > 1) {
        ("number".to_string(), true)
    } else if first == b'"' || first == b'\'' || first == b'`' {
        ("string".to_string(), true)
    } else if d == "true" || d == "false" {
        ("boolean".to_string(), true)
    } else if first == b'{' {
        ("Object".to_string(), true)
    } else if first == b'[' {
        let body = &d[1..d.rfind(']').unwrap_or(d.len())];
        let mut elems: Vec<&str> = Vec::new();
        for e in split_pattern_members(body) {
            let e = e.trim();
            let f = e.bytes().next().unwrap_or(b' ');
            let t = if f.is_ascii_digit() || (f == b'-' && e.len() > 1) {
                "number"
            } else if f == b'"' || f == b'\'' || f == b'`' {
                "string"
            } else if e == "true" || e == "false" {
                "boolean"
            } else {
                "*"
            };
            if !elems.contains(&t) || tuple_context {
                elems.push(t);
            }
        }
        let ty = if tuple_context {
            format!("[{}]", elems.join(", "))
        } else if elems.len() > 1 {
            format!("({})[]", elems.join(" | "))
        } else {
            format!("{}[]", elems.first().copied().unwrap_or("*"))
        };
        (ty, true)
    } else {
        // Arbitrary expressions still inline unless unwieldy (tsc omits
        // very long initializers — `[a]` instead of `[a=…]`).
        ("*".to_string(), d.len() <= 80 && !d.contains('\n'))
    }
}

/// Names documented by `@param` lines in the comment starting at `open`.
fn jsdoc_documented_param_names(source: &str, open: usize, p: usize) -> Vec<String> {
    let close = source[p..]
        .find("*/")
        .map(|k| p + k)
        .unwrap_or(source.len());
    let mut documented: Vec<String> = Vec::new();
    for line in source[open..close].lines() {
        let lt = line.trim_start().trim_start_matches('*').trim_start();
        if let Some(tail) = lt.strip_prefix("@param") {
            let mut t = tail.trim_start();
            if t.starts_with('{') {
                let mut depth = 0i32;
                let mut cut = t.len();
                for (k, b) in t.bytes().enumerate() {
                    match b {
                        b'{' => depth += 1,
                        b'}' => {
                            depth -= 1;
                            if depth == 0 {
                                cut = k + 1;
                                break;
                            }
                        }
                        _ => {}
                    }
                }
                t = t[cut.min(t.len())..].trim_start();
            }
            let name: String = t
                .bytes()
                .take_while(|&b| is_ident_byte(b))
                .map(|b| b as char)
                .collect();
            if !name.is_empty() {
                documented.push(name);
            }
        }
    }
    documented
}

/// tsc's @param snippet completions: one entry per undocumented parameter of
/// the attached declaration. JS files carry `{type}` annotations and nested
/// destructuring documentation joined with CRLF + `* ` continuations.
fn jsdoc_param_snippet_labels(
    source: &str,
    open: usize,
    p: usize,
    documented: &[String],
    is_js: bool,
) -> Vec<String> {
    let close = source[p..]
        .find("*/")
        .map(|k| p + k)
        .unwrap_or(source.len());
    let items = jsdoc_following_param_items(source, close);
    let mut labels = Vec::new();
    let _ = open;
    for (idx, raw) in items.iter().enumerate() {
        let mut item = raw.as_str();
        let rest = item.starts_with("...");
        if rest {
            item = &item[3..];
        }
        // Strip a TS type annotation at top level (`: T`).
        let ib = item.as_bytes();
        let mut d = 0i32;
        let mut cut = item.len();
        for k in 0..item.len() {
            match ib[k] {
                b'(' | b'[' | b'{' => d += 1,
                b')' | b']' | b'}' => d -= 1,
                b':' if d == 0 => {
                    cut = k;
                    break;
                }
                _ => {}
            }
        }
        let (decl, ann) = (item[..cut].trim_end(), item[cut..].trim());
        let _ = ann;
        let (pattern, default) = split_top_level_default(decl);
        let pattern = pattern.trim();
        let is_pattern = pattern.starts_with('{') || pattern.starts_with('[');
        let name = if is_pattern {
            format!("param{}", idx)
        } else {
            pattern
                .bytes()
                .take_while(|&b| is_ident_byte(b))
                .map(|b| b as char)
                .collect()
        };
        if name.is_empty() || documented.iter().any(|d| *d == name) {
            continue;
        }

        if !is_js {
            labels.push(format!("param {} ", name));
            continue;
        }

        // JS: head line with a {type}, then nested member lines.
        let mut nested: Vec<String> = Vec::new();
        let head_ty: String;
        if is_pattern {
            let obj_body = pattern.strip_prefix('{').and_then(|t| t.strip_suffix('}'));
            let has_computed_key = obj_body
                .map(|b| split_pattern_members(b).iter().any(|m| m.starts_with('[')))
                .unwrap_or(true);
            match obj_body {
                Some(body) if !rest && !has_computed_key => {
                    head_ty = "Object".to_string();
                    collect_pattern_member_labels(body, &name, &mut nested);
                }
                _ if rest => {
                    head_ty = "...*".to_string();
                }
                _ => {
                    // Array patterns, computed keys: opaque.
                    head_ty = "*".to_string();
                }
            }
        } else if rest {
            head_ty = "...*".to_string();
        } else if let Some(def) = default {
            head_ty = jsdoc_default_type(def, false).0;
        } else {
            head_ty = "*".to_string();
        }
        let head_name = match default {
            Some(def) => {
                let (_, simple) = jsdoc_default_type(def, false);
                if simple {
                    format!("[{}={}]", name, def)
                } else {
                    format!("[{}]", name)
                }
            }
            None => name.clone(),
        };
        let mut label = format!("param {{{}}} {} ", head_ty, head_name);
        for n in nested {
            label.push_str("\r\n* ");
            label.push_str(&n);
        }
        labels.push(label);
    }
    labels
}

/// Nested `@param` documentation lines for the members of an object
/// destructuring pattern body, e.g. `@param {number} [param0.a=1] `.
fn collect_pattern_member_labels(body: &str, parent: &str, out: &mut Vec<String>) {
    for m in split_pattern_members(body) {
        if m.starts_with("...") {
            let n: String = m[3..]
                .bytes()
                .take_while(|&b| is_ident_byte(b))
                .map(|b| b as char)
                .collect();
            if !n.is_empty() {
                out.push(format!("@param {{...*}} {}.{} ", parent, n));
            }
            continue;
        }
        // key [: sub] [= default]
        let (decl, default) = split_top_level_default(&m);
        let decl = decl.trim();
        let (key, sub) = match decl.find(':') {
            Some(c) if !decl.starts_with('[') => (decl[..c].trim(), Some(decl[c + 1..].trim())),
            _ => (decl, None),
        };
        let key = key.trim_matches(|c| c == '"' || c == '\'');
        if key.starts_with('[') {
            continue; // computed — not documentable
        }
        let path = format!("{}.{}", parent, key);
        let sub_obj = sub
            .filter(|t| t.starts_with('{'))
            .and_then(|t| t.strip_prefix('{'))
            .and_then(|t| t.strip_suffix('}'));
        let (ty, bracketed): (String, String) = match (default, sub) {
            (Some(def), _) => {
                let tuple_ctx = sub.map(|t| t.starts_with('[')).unwrap_or(false);
                let (t, simple) = jsdoc_default_type(def, tuple_ctx);
                let t = if sub_obj.is_some() {
                    "Object".to_string()
                } else {
                    t
                };
                if simple {
                    (t, format!("[{}={}]", path, def))
                } else {
                    (t, format!("[{}]", path))
                }
            }
            (None, Some(t)) if t.starts_with('{') => ("Object".to_string(), path.clone()),
            _ => ("*".to_string(), path.clone()),
        };
        out.push(format!("@param {{{}}} {} ", ty, bracketed));
        if let Some(inner) = sub_obj {
            collect_pattern_member_labels(inner, &path, out);
        }
    }
}

/// Exported symbol names of the module `spec` resolves to, as (label, kind).
fn module_export_entries(
    query_engine: &QueryEngine,
    spec: &str,
    from_file: &str,
) -> Vec<(String, u64)> {
    let resolved = query_engine
        .resolve_import_path(spec, from_file)
        .or_else(|| {
            // Bare specifier against the in-memory file set: node_modules lookup.
            if spec.starts_with('.') {
                return None;
            }
            let names = query_engine.source_file_names();
            let cands = [
                format!("/node_modules/{}/index.d.ts", spec),
                format!("/node_modules/{}/index.ts", spec),
                format!("/node_modules/{}.d.ts", spec),
                format!("/node_modules/@types/{}/index.d.ts", spec),
            ];
            names
                .iter()
                .find(|n| cands.iter().any(|c| n.ends_with(c.as_str())))
                .cloned()
        });
    let Some(sf) = resolved else {
        return Vec::new();
    };
    let Some(syms) = query_engine.get_file_symbols(&sf) else {
        return Vec::new();
    };
    let mut out: Vec<(String, u64)> = Vec::new();
    for sym in &syms.symbols {
        if sym.flags & tsc_rs_symbols::SYM_EXPORT == 0 {
            continue;
        }
        if sym.name == "default" || out.iter().any(|(n, _)| *n == sym.name) {
            continue;
        }
        let kind: u64 = if sym.flags & tsc_rs_symbols::SYM_CLASS != 0 {
            7
        } else if sym.flags & (tsc_rs_symbols::SYM_INTERFACE | tsc_rs_symbols::SYM_TYPE_ALIAS) != 0
        {
            8
        } else if sym.flags & tsc_rs_symbols::SYM_ENUM != 0 {
            13
        } else if sym.flags & tsc_rs_symbols::SYM_MODULE != 0 {
            9
        } else if sym.flags & tsc_rs_symbols::SYM_FUNCTION != 0 {
            3
        } else {
            6
        };
        out.push((sym.name.clone(), kind));
    }
    out
}

/// Completions inside a `/** ... */` JSDoc comment: tag names after `@`,
/// `@tag`-prefixed entries at bare line positions, inline tag names after
/// `{@`, and parameter names after `@param`. Returns None when the position
/// has no JSDoc-specific completions (falls back to the comment early-return).
fn jsdoc_completions(
    source: &str,
    offset: u32,
    query_engine: &QueryEngine,
    file_name: &str,
) -> Option<Vec<Value>> {
    let bytes = source.as_bytes();
    let p = (offset as usize).min(bytes.len());
    // Must be inside a `/**` comment (not a plain `/*`).
    let open = source[..p].rfind("/*")?;
    if !source[open..].starts_with("/**") {
        return None;
    }
    if source[open..p].contains("*/") {
        return None;
    }

    // Line prefix, stripped of leading whitespace, a leading `/**`, leading
    // `*` decorations, and following whitespace.
    let line_start = source[..p].rfind('\n').map(|i| i + 1).unwrap_or(0);
    let mut r = line_start;
    while r < p && (bytes[r] == b' ' || bytes[r] == b'\t') {
        r += 1;
    }
    if r == open {
        r += 1; // the `/`
    }
    while r < p && bytes[r] == b'*' {
        r += 1;
    }
    while r < p && (bytes[r] == b' ' || bytes[r] == b'\t') {
        r += 1;
    }
    let rest = &source[r..p];

    // Inline tag: `{@` followed only by ident chars up to the cursor.
    {
        let mut i = p;
        while i > r && is_ident_byte(bytes[i - 1]) {
            i -= 1;
        }
        if i >= 2 && bytes[i - 1] == b'@' && bytes[i - 2] == b'{' {
            return Some(jsdoc_keyword_entries(JSDOC_INLINE_TAG_NAMES, false));
        }
    }

    // Bare position (nothing typed on the line yet): offer `@tag` entries
    // plus @param snippet entries for undocumented parameters.
    if rest.is_empty() {
        let mut items = jsdoc_keyword_entries(JSDOC_TAG_NAMES, true);
        let documented = jsdoc_documented_param_names(source, open, p);
        let is_js = file_name.ends_with(".js") || file_name.ends_with(".jsx");
        for l in jsdoc_param_snippet_labels(source, open, p, &documented, is_js) {
            items.push(json!({ "label": format!("@{}", l), "kind": 15 }));
        }
        return Some(items);
    }

    if !rest.starts_with('@') {
        return None;
    }

    // Partial tag name: `@` + ident chars only, cursor at the end.
    if rest[1..].bytes().all(is_ident_byte) {
        let mut items = jsdoc_keyword_entries(JSDOC_TAG_NAMES, false);
        let documented = jsdoc_documented_param_names(source, open, p);
        let is_js = file_name.ends_with(".js") || file_name.ends_with(".jsx");
        for l in jsdoc_param_snippet_labels(source, open, p, &documented, is_js) {
            items.push(json!({ "label": l, "kind": 15 }));
        }
        return Some(items);
    }

    // `@import { … } from "mod"`: named-import completions — the module's
    // exported names, minus ones already listed in the clause.
    if rest.starts_with("@import") && rest.contains('{') {
        let line_end = source[p..]
            .find('\n')
            .map(|k| p + k)
            .unwrap_or(source.len());
        if let Some(spec) = source[p..line_end]
            .split(" from ")
            .nth(1)
            .and_then(extract_quoted)
        {
            let mut i = p;
            while i > r && is_ident_byte(bytes[i - 1]) {
                i -= 1;
            }
            let partial = &source[i..p];
            let clause_before = &rest[rest.find('{').unwrap() + 1..];
            let taken: Vec<&str> = clause_before
                .split(',')
                .map(|t| t.trim())
                .filter(|t| !t.is_empty())
                .collect();
            let items: Vec<Value> = module_export_entries(query_engine, spec, file_name)
                .into_iter()
                .filter(|(n, _)| n.starts_with(partial) && !taken.iter().any(|t| t == n))
                .map(|(n, k)| json!({ "label": n, "kind": k }))
                .collect();
            return Some(items);
        }
    }

    // Inside an unclosed `{type}` expression of any tag: type keywords.
    {
        let mut depth = 0i32;
        for b in rest.bytes() {
            match b {
                b'{' => depth += 1,
                b'}' => depth -= 1,
                _ => {}
            }
        }
        if depth > 1 {
            // Inside an object-literal type within the braces — property
            // names are fresh identifiers; tsc offers nothing.
            return Some(Vec::new());
        }
        if depth == 1 {
            // Qualified name `Ns.…`: members of an imported namespace.
            let mut i = p;
            while i > r && is_ident_byte(bytes[i - 1]) {
                i -= 1;
            }
            let partial = &source[i..p];
            if i > r && bytes[i - 1] == b'.' {
                let mut q = i - 1;
                while q > r && is_ident_byte(bytes[q - 1]) {
                    q -= 1;
                }
                let first = &source[q..i - 1];
                let items: Vec<Value> = if !first.is_empty() && (q == r || bytes[q - 1] != b'.') {
                    find_import_binding(source, first)
                        .map(|(spec, _)| {
                            module_export_entries(query_engine, &spec, file_name)
                                .into_iter()
                                .filter(|(n, _)| n.starts_with(partial))
                                .map(|(n, k)| json!({ "label": n, "kind": k }))
                                .collect()
                        })
                        .unwrap_or_default()
                } else {
                    Vec::new()
                };
                return Some(items);
            }
            const TYPE_KEYWORDS: &[&str] = &[
                "any",
                "bigint",
                "boolean",
                "never",
                "null",
                "number",
                "object",
                "string",
                "symbol",
                "undefined",
                "unknown",
                "void",
            ];
            return Some(jsdoc_keyword_entries(TYPE_KEYWORDS, false));
        }
    }

    // `@param` name position: optional `{type}` groups and whitespace, then
    // an optional partial name the cursor sits in.
    let tag_end = 1 + rest[1..].bytes().take_while(|&b| is_ident_byte(b)).count();
    if &rest[..tag_end] != "@param" {
        return None;
    }
    let mut i = r + tag_end;
    let mut partial = "";
    loop {
        while i < p && (bytes[i] == b' ' || bytes[i] == b'\t') {
            i += 1;
        }
        if i >= p {
            break;
        }
        if bytes[i] == b'{' {
            let mut depth = 0i32;
            while i < p {
                match bytes[i] {
                    b'{' => depth += 1,
                    b'}' => {
                        depth -= 1;
                        if depth == 0 {
                            i += 1;
                            break;
                        }
                    }
                    _ => {}
                }
                i += 1;
            }
            if depth > 0 {
                // Cursor is inside the type braces — not a name position.
                return None;
            }
            continue;
        }
        if is_ident_byte(bytes[i]) {
            let start = i;
            while i < p && is_ident_byte(bytes[i]) {
                i += 1;
            }
            if i >= p {
                partial = &source[start..p];
                break;
            }
            // A completed name followed by more content — description text.
            return None;
        }
        return None;
    }

    // Names already documented by OTHER `@param` lines in this comment.
    let close = source[p..]
        .find("*/")
        .map(|k| p + k)
        .unwrap_or(source.len());
    let mut documented: Vec<String> = Vec::new();
    for line in source[open..close].lines() {
        let lt = line.trim_start().trim_start_matches('*').trim_start();
        if let Some(tail) = lt.strip_prefix("@param") {
            let mut t = tail.trim_start();
            if t.starts_with('{') {
                let mut depth = 0i32;
                let mut cut = t.len();
                for (k, b) in t.bytes().enumerate() {
                    match b {
                        b'{' => depth += 1,
                        b'}' => {
                            depth -= 1;
                            if depth == 0 {
                                cut = k + 1;
                                break;
                            }
                        }
                        _ => {}
                    }
                }
                t = t[cut.min(t.len())..].trim_start();
            }
            let name: String = t
                .bytes()
                .take_while(|&b| is_ident_byte(b))
                .map(|b| b as char)
                .collect();
            if !name.is_empty() {
                documented.push(name);
            }
        }
    }
    // The cursor's own partial name is not "documented".
    if !partial.is_empty() {
        if let Some(k) = documented.iter().position(|d| d == partial) {
            documented.remove(k);
        }
    }

    // Parameter names of the declaration the comment attaches to: the first
    // `(...)` after `*/`, unless a `;` or another comment starts first.
    let mut params: Vec<String> = Vec::new();
    if close < source.len() {
        let after = &source[close + 2..];
        let scan = &after[..after.len().min(300)];
        let stop = scan.find(';').min(scan.find("/*")).unwrap_or(scan.len());
        if let Some(lp) = scan[..stop.min(scan.len())].find('(') {
            let seg = &scan[lp + 1..];
            let mut depth = 1i32;
            let mut end = seg.len();
            for (k, b) in seg.bytes().enumerate() {
                match b {
                    b'(' | b'[' | b'{' | b'<' => depth += 1,
                    b')' | b']' | b'}' | b'>' => {
                        depth -= 1;
                        if depth == 0 {
                            end = k;
                            break;
                        }
                    }
                    _ => {}
                }
            }
            let mut item_start = 0usize;
            let list = &seg[..end];
            let lb = list.as_bytes();
            let mut d = 0i32;
            for k in 0..=list.len() {
                let at_end = k == list.len();
                if !at_end {
                    match lb[k] {
                        b'(' | b'[' | b'{' | b'<' => d += 1,
                        b')' | b']' | b'}' | b'>' => d -= 1,
                        _ => {}
                    }
                }
                if at_end || (lb[k] == b',' && d == 0) {
                    let item = list[item_start..k].trim().trim_start_matches("...");
                    let name: String = item
                        .bytes()
                        .take_while(|&b| is_ident_byte(b))
                        .map(|b| b as char)
                        .collect();
                    if !name.is_empty() && name != "this" {
                        params.push(name);
                    }
                    item_start = k + 1;
                }
            }
        }
    }

    let items: Vec<Value> = params
        .into_iter()
        .filter(|n| n.starts_with(partial) && !documented.iter().any(|d| d == n))
        .map(|n| json!({ "label": n, "kind": 6 }))
        .collect();
    Some(items)
}

pub fn completions_at(
    sym_table: &SymbolTable,
    check_out: &TypeCheckOutput,
    source: &str,
    offset: u32,
    query_engine: &QueryEngine,
    file_name: &str,
) -> Vec<Value> {
    completions_at_with_prefs(
        sym_table,
        check_out,
        source,
        offset,
        query_engine,
        file_name,
        false,
    )
}

/// `completions_at` with tsserver-style preferences: when
/// `include_module_exports` is set, identifier positions also offer
/// auto-importable exports from the project's other files.
pub fn completions_at_with_prefs(
    sym_table: &SymbolTable,
    check_out: &TypeCheckOutput,
    source: &str,
    offset: u32,
    query_engine: &QueryEngine,
    file_name: &str,
    include_module_exports: bool,
) -> Vec<Value> {
    let ctx = string_context_at(source, offset);

    // `/// <reference path="…"` — file path completions inside the
    // triple-slash line comment.
    if matches!(ctx, StringContext::InLineComment) {
        if let Some(items) =
            triple_slash_ref_path_completions(source, offset, query_engine, file_name)
        {
            return items;
        }
    }

    // Inside a JSDoc block comment — tag / param-name completions
    if matches!(ctx, StringContext::InBlockComment) {
        // `@import … "…"` module-specifier strings reuse the string-literal
        // path (its module-specifier branch keys off the text before the
        // quote, which works inside comments too).
        let bytes_c = source.as_bytes();
        let pc = (offset as usize).min(bytes_c.len());
        let ls = source[..pc].rfind('\n').map(|i| i + 1).unwrap_or(0);
        let line_before = &source[ls..pc];
        let stripped = line_before
            .trim_start()
            .trim_start_matches("/**")
            .trim_start_matches("/*")
            .trim_start_matches('*')
            .trim_start();
        if stripped.starts_with("@import")
            && (line_before.bytes().filter(|&b| b == b'"').count() % 2 == 1
                || line_before.bytes().filter(|&b| b == b'\'').count() % 2 == 1)
        {
            return string_literal_completions(
                sym_table,
                check_out,
                source,
                offset,
                query_engine,
                file_name,
            );
        }
        if let Some(items) = jsdoc_completions(source, offset, query_engine, file_name) {
            return items;
        }
    }

    // Inside a comment — no completions
    if matches!(
        ctx,
        StringContext::InLineComment | StringContext::InBlockComment
    ) {
        return Vec::new();
    }

    // Inside a string literal — provide string literal completions
    // (e.g. string union member completions, indexed access property names)
    if matches!(
        ctx,
        StringContext::InSingleQuoteString
            | StringContext::InDoubleQuoteString
            | StringContext::InTemplateString
    ) {
        return string_literal_completions(
            sym_table,
            check_out,
            source,
            offset,
            query_engine,
            file_name,
        );
    }

    // Incomplete import statements replace scope completions entirely.
    if let Some(items) = import_statement_completions(source, offset, query_engine, file_name) {
        return items;
    }

    // Exhaustive switch-case entry (`case E.A: ...`) augments the list.
    let exhaustive_case = exhaustive_case_completion(
        source,
        offset,
        sym_table,
        check_out,
        query_engine,
        file_name,
    );

    // Suppress completions at positions where no completions should appear
    // (declaration names, parameter names, etc.)
    if is_completion_list_blocker(source, offset) {
        return Vec::new();
    }

    // Check if the character before cursor is '.' (or '?.')
    let before = if offset > 0 {
        source.as_bytes().get((offset - 1) as usize).copied()
    } else {
        None
    };

    // A `.` is only a MEMBER-ACCESS trigger when the token before it is a
    // valid receiver: an identifier (incl. this/super), `)`, `]`, a string
    // quote, or a template backtick. `a/.` (division), `1.` (float
    // continuation), or a dot after an operator/comma must yield NO
    // completions (completionListAfterSlash).
    fn dot_is_member_trigger(source: &str, dot_pos: usize) -> bool {
        let bytes = source.as_bytes();
        let mut i = dot_pos;
        // Fluent chains put the receiver on the previous line — skip
        // whitespace (incl. newlines) between the dot and its receiver.
        while i > 0 && (bytes[i - 1] as char).is_whitespace() {
            i -= 1;
        }
        // walk back over the receiver token
        let tok_end = i;
        while i > 0 && (is_ident_byte(bytes[i - 1]) || bytes[i - 1] == b'$') {
            i -= 1;
        }
        if i < tok_end {
            // Non-empty ident-ish token: a NUMERIC token (starts with a
            // digit) makes the dot a float continuation, not member access.
            return !bytes[i].is_ascii_digit();
        }
        // `5..` — the first dot terminated a numeric literal, so THIS dot
        // is member access on the number.
        if bytes.get(i.wrapping_sub(1)) == Some(&b'.') && i >= 2 {
            let mut d = i - 1;
            while d > 0 && bytes[d - 1].is_ascii_digit() {
                d -= 1;
            }
            if d < i - 1 && (d == 0 || !is_ident_byte(bytes[d - 1])) {
                return true;
            }
        }
        match bytes.get(i.wrapping_sub(1)).copied() {
            // `x?.` — the `?` of optional chaining; the receiver sits before it.
            Some(b'?') if i >= 2 => {
                let j = i - 1;
                let mut k = j;
                while k > 0 && (is_ident_byte(bytes[k - 1]) || bytes[k - 1] == b'$') {
                    k -= 1;
                }
                (k < j && !bytes[k].is_ascii_digit())
                    || matches!(
                        bytes.get(k.wrapping_sub(1)).copied(),
                        Some(b')' | b']' | b'}' | b'"' | b'\'' | b'`')
                    )
            }
            Some(b')' | b']' | b'}' | b'"' | b'\'' | b'`') => i > 0,
            _ => false,
        }
    }

    // Also detect `?.` — the char before cursor could be `.` preceded by `?`
    // Also detect `this.foo|` or `this.#priv|` — cursor mid-token after `.`
    let (is_dot_access, effective_offset) = if before == Some(b'.') {
        let dot = offset as usize - 1;
        let bytes = source.as_bytes();
        // Spread (`...`) is not member access — fall through to scope
        // completions. A dot inside a string literal belongs to the
        // string/path completion flows. Only a genuine operator-dot
        // (`a/.`, `1.`) yields nothing.
        let is_spread = dot >= 2 && bytes[dot - 1] == b'.' && bytes[dot - 2] == b'.';
        let in_string = {
            let line_start = source[..dot].rfind('\n').map(|i| i + 1).unwrap_or(0);
            let line = &source[line_start..dot];
            let dq = line.matches('"').count();
            let sq = line.matches('\'').count();
            dq % 2 == 1 || sq % 2 == 1
        };
        if is_spread || in_string {
            (false, offset)
        } else if dot_is_member_trigger(source, dot) {
            (true, offset)
        } else {
            return Vec::new();
        }
    } else {
        // Check if we're typing a token that's preceded by `.`
        let token = extract_token_at(source, offset);
        if !token.is_empty() {
            let bytes = source.as_bytes();
            let mut tok_start = offset as usize;
            while tok_start > 0
                && (is_ident_byte(bytes[tok_start - 1]) || bytes[tok_start - 1] == b'#')
            {
                tok_start -= 1;
            }
            if tok_start > 0 && bytes[tok_start - 1] == b'.' {
                // Use the dot position + 1 as the effective offset for member lookup
                (true, tok_start as u32)
            } else {
                (false, offset)
            }
        } else {
            (false, offset)
        }
    };

    // Check if this is a spread operator `...` rather than a member access `.`
    let is_spread = if is_dot_access && effective_offset >= 3 {
        let bytes = source.as_bytes();
        let dot_pos = (effective_offset - 1) as usize;
        dot_pos >= 2 && bytes[dot_pos - 1] == b'.' && bytes[dot_pos - 2] == b'.'
    } else {
        false
    };

    if is_dot_access && !is_spread {
        // Special case: import.meta and new.target meta-property completions
        let dot_pos = effective_offset - 1;
        let ident = extract_token_at(source, dot_pos.saturating_sub(1));
        if ident == "import" {
            return vec![json!({"label": "meta", "kind": 10, "detail": "ImportMeta"})];
        }
        if ident == "new" {
            // Only inside function bodies — check if there's a function context
            if is_inside_function_body(source, offset) {
                return vec![json!({"label": "target", "kind": 10, "detail": "() => void"})];
            }
        }

        // Block completions for invalid implements/extends dot-access patterns.
        // `class X implements Foo.` and `interface X implements Foo.` are invalid syntax.
        {
            let bytes = source.as_bytes();
            let dot_pos = (offset - 1) as usize;
            let ident_before = extract_token_at(source, dot_pos.saturating_sub(1) as u32);
            if !ident_before.is_empty() {
                // Find the text before the identifier to check for `implements`/`extends`
                let ident_start = dot_pos.saturating_sub(ident_before.len());
                let prefix = source[..ident_start].trim_end();
                if prefix.ends_with("implements") {
                    // `implements X.` is never valid for dot access completions
                    return Vec::new();
                }
                // `interface Y extends X.` — interfaces don't have static
                // members, so dot-access is invalid.
                if prefix.ends_with("extends") {
                    // Check if this is an interface extends (not class extends)
                    let before_extends = prefix.trim_end_matches("extends").trim_end();
                    if before_extends.ends_with('}') || before_extends.ends_with(',') {
                        // After a closing brace or comma — this is `interface X extends Y.`
                        return Vec::new();
                    }
                    // Check if the extends is preceded by an interface name
                    // by scanning back for the `interface` keyword
                    let line_start = before_extends.rfind('\n').map(|p| p + 1).unwrap_or(0);
                    let line = &before_extends[line_start..];
                    if line.trim_start().starts_with("interface") {
                        return Vec::new();
                    }
                }
            }
        }

        // Determine if the cursor is outside the declaring class (for filtering private members)
        let enclosing_class = find_enclosing_class_name(source, effective_offset);

        // `5..` — numeric literal member access: the receiver is `5.`
        // (float-continuation dot), the trigger dot follows it.
        {
            let b = source.as_bytes();
            let dot = (effective_offset as usize).min(b.len());
            if dot >= 3 && b[dot - 1] == b'.' && b[dot - 2] == b'.' {
                let mut d = dot - 2;
                while d > 0 && b[d - 1].is_ascii_digit() {
                    d -= 1;
                }
                if d < dot - 2 && (d == 0 || !is_ident_byte(b[d - 1]) && b[d - 1] != b'.') {
                    let items = member_completions_for_type("number", sym_table, query_engine);
                    if !items.is_empty() {
                        return items;
                    }
                }
            }
        }

        // Call-result receivers in JS resolve through their declaration's
        // JSDoc first — the nearest expression type before `).` is the last
        // ARGUMENT, not the call result.
        if file_name.ends_with(".js") || file_name.ends_with(".jsx") {
            let b = source.as_bytes();
            let mut k = (effective_offset as usize).min(b.len());
            while k > 0 && is_ident_byte(b[k - 1]) {
                k -= 1;
            }
            if k >= 2 && b[k - 1] == b'.' && b[k - 2] == b')' {
                if let Some(items) = js_jsdoc_type_member_completions(
                    source,
                    effective_offset,
                    sym_table,
                    query_engine,
                ) {
                    return items;
                }
            }
        }
        // First try expression_types-based resolution
        let members = member_completions(
            sym_table,
            check_out,
            source,
            effective_offset,
            query_engine,
            file_name,
        );
        if !members.is_empty() {
            return filter_private_members(
                members,
                &enclosing_class,
                source,
                effective_offset,
                sym_table,
            );
        }
        // Closure-style @type annotations in JS files
        if file_name.ends_with(".js") || file_name.ends_with(".jsx") {
            if let Some(items) =
                js_jsdoc_type_member_completions(source, effective_offset, sym_table, query_engine)
            {
                return items;
            }
        }
        // CommonJS require()/export= results (JS files and TS export=)
        if let Some(items) = cjs_require_member_completions(
            source,
            effective_offset,
            sym_table,
            query_engine,
            file_name,
        ) {
            return items;
        }
        // Untyped receivers in JS: loose in-scope identifier entries.
        // (@ts-check files behave like TS — no loose entries.)
        if (file_name.ends_with(".js") || file_name.ends_with(".jsx"))
            && !source.contains("@ts-check")
        {
            let mut loose: Vec<Value> = Vec::new();
            for sym in &sym_table.symbols {
                if sym.flags
                    & (tsc_rs_symbols::SYM_VARIABLE
                        | tsc_rs_symbols::SYM_FUNCTION
                        | tsc_rs_symbols::SYM_CLASS
                        | tsc_rs_symbols::SYM_PROPERTY
                        | tsc_rs_symbols::SYM_METHOD)
                    == 0
                {
                    continue;
                }
                if sym.name.is_empty() || sym.name.starts_with('#') {
                    continue;
                }
                if loose
                    .iter()
                    .any(|v| v.get("label").and_then(|l| l.as_str()) == Some(sym.name.as_str()))
                {
                    continue;
                }
                loose.push(json!({ "label": sym.name, "kind": 6 }));
            }
            if !loose.is_empty() {
                return loose;
            }
        }
        // Fallback: extract the identifier before the dot and look up its type

        // Special case: this. — find enclosing class and return its members
        if ident == "this" {
            if let Some(class_members) =
                find_enclosing_class_members(source, effective_offset, sym_table)
            {
                return filter_private_members(
                    class_members,
                    &enclosing_class,
                    source,
                    effective_offset,
                    sym_table,
                );
            }
        }

        // Special case: super. — find enclosing class's parent class and return its members
        if ident == "super" {
            if let Some(parent_members) =
                find_super_class_members(source, effective_offset, sym_table)
            {
                return parent_members;
            }
        }

        if !ident.is_empty() {
            // Look up the variable's type from expression_types at its declaration
            for sym in &sym_table.symbols {
                if sym.name == ident {
                    // Same-file namespace blocks: the binder flattens their
                    // contents, so parse member names from the block text.
                    if sym.flags & tsc_rs_symbols::SYM_MODULE != 0
                        && sym.members.is_empty()
                        && sym.exports.is_empty()
                    {
                        if let Some(mut items) =
                            namespace_block_member_completions(source, &sym.name)
                        {
                            // `typeof ns.` sees only VALUE members.
                            let recv_start = source[..(effective_offset as usize)
                                .saturating_sub(1)
                                .min(source.len())]
                                .rfind(&sym.name)
                                .unwrap_or(0);
                            let before_recv = source[..recv_start].trim_end();
                            if before_recv.ends_with("typeof") {
                                items.retain(|v| {
                                    matches!(
                                        v.get("kind").and_then(|k| k.as_u64()),
                                        Some(3 | 6 | 7 | 9 | 13)
                                    )
                                });
                            }
                            if !items.is_empty() {
                                return items;
                            }
                        }
                    }
                    // Direct members lookup (works for enums, classes, interfaces).
                    // Namespaces store exported members in `exports`.
                    if !sym.members.is_empty() || !sym.exports.is_empty() {
                        // `typeof ns.` sees only VALUE members.
                        let typeof_receiver = {
                            let recv_end = source[..(effective_offset as usize)
                                .saturating_sub(1)
                                .min(source.len())]
                                .rfind(ident.as_str())
                                .unwrap_or(0);
                            source[..recv_end].trim_end().ends_with("typeof")
                        };
                        let mut items = Vec::new();
                        for (member_name, &member_id) in sym.members.iter().chain(&sym.exports) {
                            if let Some(member_sym) = sym_table.get_symbol(member_id) {
                                // `export import M = N` inside namespace N is a
                                // self-alias with no referenceable members.
                                if member_sym.flags & tsc_rs_symbols::SYM_IMPORT != 0 {
                                    let self_alias = member_sym.declarations.iter().any(|d| {
                                        let st = d.span.start as usize;
                                        source
                                            .get(st..source.len().min(st + 120))
                                            .and_then(|t| t.lines().next())
                                            .and_then(|line| line.split('=').nth(1))
                                            .map(|r| r.trim().trim_end_matches(';').trim() == ident)
                                            .unwrap_or(false)
                                    });
                                    if self_alias {
                                        continue;
                                    }
                                }
                                let kind = completion_kind_for_flags(member_sym.flags);
                                if typeof_receiver && !matches!(kind, 3 | 6 | 7 | 9 | 13) {
                                    continue;
                                }
                                items.push(
                                    json!({"label": member_name, "kind": kind, "detail": &ident}),
                                );
                            }
                        }
                        if !items.is_empty() {
                            return filter_private_members(
                                items,
                                &enclosing_class,
                                source,
                                offset,
                                sym_table,
                            );
                        }
                    }
                    // Try expression_types at declaration
                    for decl in &sym.declarations {
                        if let Some(ty) = check_out.expression_types.get(&decl.span.start) {
                            let results = member_completions_for_type(ty, sym_table, query_engine);
                            return filter_private_members(
                                results,
                                &enclosing_class,
                                source,
                                offset,
                                sym_table,
                            );
                        }
                    }
                }
            }
            // Try QE member completions directly by identifier name
            let qe_members = query_engine.get_type_member_completions(&ident);
            if !qe_members.is_empty() {
                let results: Vec<Value> = qe_members
                    .into_iter()
                    .map(|(name, flags, detail)| {
                        let kind = completion_kind_for_flags(flags);
                        match detail {
                            Some(ts) => json!({"label": name, "kind": kind, "detail": ts}),
                            None => json!({"label": name, "kind": kind, "detail": &ident}),
                        }
                    })
                    .collect();
                return filter_private_members(
                    results,
                    &enclosing_class,
                    source,
                    offset,
                    sym_table,
                );
            }
        }
        return Vec::new();
    }

    // Check if we're in an import/export specifier context
    if let Some(import_export_items) =
        import_export_specifier_completions(source, offset, sym_table, query_engine)
    {
        return import_export_items;
    }

    // Check if we're directly inside an interface body at the member declaration level.
    // In that position, only `readonly` should appear (not scope variables or statement keywords).
    if is_at_interface_member_start(source, offset) {
        return vec![json!({
            "label": "readonly",
            "kind": 14,
            "sortText": "15"
        })];
    }

    // Check if we're inside an object binding pattern: `let { | } = expr`
    // Provide property completions from the source type.
    if is_in_object_binding_pattern_body(source, offset) {
        let props = binding_pattern_completions(source, offset, sym_table, check_out, query_engine);
        return props;
    }

    // Check if we're inside an object literal with a contextual type.
    // If so, offer only the target type's property names.
    if let Some(obj_completions) = object_literal_contextual_completions(
        source,
        offset,
        sym_table,
        check_out,
        query_engine,
        false,
    ) {
        return obj_completions;
    }

    // JSX closing-tag position: `</|` offers the innermost unclosed tag.
    if let Some(items) = jsx_closing_tag_completions(source, offset) {
        return items;
    }
    // JSX attribute-name position: cursor inside an opening tag
    // (`<foo prop_|`, `<Comp |/>`) — offer the element's prop names.
    if let Some(attr_items) =
        jsx_attribute_completions(source, offset, sym_table, check_out, query_engine)
    {
        if !attr_items.is_empty() {
            return attr_items;
        }
    }

    // Check if we're in a type annotation context (after `:` type annotation, inside type literal,
    // in generic type arguments, etc.). In type contexts, filter out value-only symbols.
    let in_type_context =
        is_in_type_annotation_context(source, offset) && !is_after_typeof_keyword(source, offset);

    let mut items = scope_completions(
        sym_table,
        query_engine,
        source,
        offset,
        file_name,
        include_module_exports,
    );
    if let Some(entries) = exhaustive_case {
        items.extend(entries);
    }
    // An index-signature's parameter (`[foo: string]: typeof |`) is in
    // scope for its own type annotation but is never bound as a symbol.
    {
        let line_start = source[..(offset as usize).min(source.len())]
            .rfind('\n')
            .map(|i| i + 1)
            .unwrap_or(0);
        let line = &source[line_start..(offset as usize).min(source.len())];
        if let Some(ob) = line.find('[') {
            let after = &line[ob + 1..];
            let name: String = after
                .bytes()
                .take_while(|&b| is_ident_byte(b))
                .map(|b| b as char)
                .collect();
            let rest = after[name.len()..].trim_start();
            if !name.is_empty() && rest.starts_with(':') && line[ob..].contains(']') {
                if !items
                    .iter()
                    .any(|v| v.get("label").and_then(|l| l.as_str()) == Some(name.as_str()))
                {
                    items.push(json!({ "label": name, "kind": 6 }));
                }
            }
        }
    }
    if include_module_exports {
        let have: HashSet<String> = items
            .iter()
            .filter_map(|v| {
                v.get("label")
                    .and_then(|l| l.as_str())
                    .map(|t| t.to_string())
            })
            .collect();
        for (name, kind) in cross_file_export_candidates(query_engine, file_name, false) {
            if !have.contains(&name) {
                items.push(json!({ "label": name, "kind": kind }));
            }
        }
    }

    // In value (non-type) contexts, filter out type parameters — they are only
    // meaningful in type annotations, not in expressions.
    if !in_type_context {
        items.retain(|item| {
            let kind = item.get("kind").and_then(|k| k.as_u64()).unwrap_or(0);
            if kind == 25 {
                let label = item.get("label").and_then(|l| l.as_str()).unwrap_or("");
                // Check if it's actually a type parameter (not a type alias)
                !sym_table.symbols.iter().any(|s| {
                    s.name == label
                        && s.flags & tsc_rs_symbols::SYM_TYPE_PARAMETER != 0
                        && s.flags & tsc_rs_symbols::SYM_TYPE_ALIAS == 0
                })
            } else {
                true
            }
        });
    }

    // Filter out value-only symbols when in a type annotation context
    if in_type_context {
        items.retain(|item| {
            let label = item.get("label").and_then(|l| l.as_str()).unwrap_or("");
            // Keep types, interfaces, classes, enums, type aliases, type parameters
            let kind = item.get("kind").and_then(|k| k.as_u64()).unwrap_or(0);
            // Kind 7 = class, 8 = interface, 13 = enum, 25 = type alias/parameter
            // Exclude pure modules/namespaces (kind 9) — they aren't types.
            // Qualified access (Namespace.Type) still works in dot-access completions.
            matches!(kind, 7 | 8 | 13 | 25) || is_type_symbol_name(label, sym_table)
        });
    }
    let mut seen: HashSet<String> = items
        .iter()
        .filter_map(|v| {
            v.get("label")
                .and_then(|l| l.as_str())
                .map(|s| s.to_owned())
        })
        .collect();

    // In type annotation context, add only type-related keywords and skip statement/class keywords
    if in_type_context {
        for &kw in TYPE_KEYWORDS {
            if !seen.contains(kw) {
                seen.insert(kw.to_owned());
                items.push(json!({
                    "label": kw,
                    "kind": 14,
                    "sortText": "15"
                }));
            }
        }
        return items;
    }

    // Add contextual keyword completions
    // Only add class keywords when directly in a class body (not in a nested function)
    let in_class_direct = is_inside_class_body_direct(source, offset);
    if in_class_direct {
        for &kw in CLASS_KEYWORDS {
            if !seen.contains(kw) {
                seen.insert(kw.to_owned());
                items.push(json!({
                    "label": kw,
                    "kind": 14,
                    "sortText": "15"
                }));
            }
        }
    }
    // Add statement keywords (TSC returns them in non-dot contexts)
    // But inside a method/function body within a class, suppress class-member keywords
    let in_class_any = is_inside_class_body(source, offset);
    let in_method_body = in_class_any && !in_class_direct;
    for &kw in STATEMENT_KEYWORDS {
        // If we're inside a method body within a class, skip class-member keywords
        if in_method_body && is_class_member_keyword(kw) {
            continue;
        }
        if !seen.contains(kw) {
            seen.insert(kw.to_owned());
            items.push(json!({
                "label": kw,
                "kind": 14,
                "sortText": "15"
            }));
        }
    }

    // Add `arguments` pseudo-variable inside function bodies (not arrow functions)
    if is_inside_function_body(source, offset) && !seen.contains("arguments") {
        seen.insert("arguments".to_owned());
        items.push(json!({
            "label": "arguments",
            "kind": 6,
            "sortText": "0_arguments"
        }));
    }

    items
}

/// Find the enclosing class at a given offset and return its members as completions.
/// Uses brace-depth tracking to determine which class body contains the offset.
fn find_enclosing_class_members(
    source: &str,
    offset: u32,
    sym_table: &SymbolTable,
) -> Option<Vec<Value>> {
    let bytes = source.as_bytes();
    let off = offset as usize;

    // Track class names and their brace depth
    let mut class_stack: Vec<String> = Vec::new();
    let mut brace_depth: i32 = 0;
    let mut class_brace_depths: Vec<(String, i32)> = Vec::new(); // (name, opening brace depth)
    let mut i = 0;
    let mut in_string: Option<u8> = None;
    let mut in_comment = false;
    let mut in_block_comment = false;

    while i < off {
        let b = bytes[i];
        let next = if i + 1 < bytes.len() { bytes[i + 1] } else { 0 };

        if in_comment {
            if b == b'\n' {
                in_comment = false;
            }
            i += 1;
            continue;
        }
        if in_block_comment {
            if b == b'*' && next == b'/' {
                in_block_comment = false;
                i += 2;
                continue;
            }
            i += 1;
            continue;
        }
        if let Some(q) = in_string {
            if b == b'\\' {
                i += 2;
                continue;
            }
            if b == q {
                in_string = None;
            }
            i += 1;
            continue;
        }

        match b {
            b'/' if next == b'/' => {
                in_comment = true;
                i += 2;
                continue;
            }
            b'/' if next == b'*' => {
                in_block_comment = true;
                i += 2;
                continue;
            }
            b'"' | b'\'' | b'`' => {
                in_string = Some(b);
            }
            b'{' => {
                brace_depth += 1;
                // Check if there's a pending class name
                if let Some(name) = class_stack.pop() {
                    class_brace_depths.push((name, brace_depth));
                }
            }
            b'}' => {
                // Check if this closes a class
                if let Some(last) = class_brace_depths.last() {
                    if last.1 == brace_depth {
                        class_brace_depths.pop();
                    }
                }
                brace_depth -= 1;
            }
            b'c' if i + 5 <= bytes.len() && &bytes[i..i + 5] == b"class" => {
                let before_ok = i == 0 || !is_ident_byte(bytes[i - 1]);
                let after_ok = i + 5 >= bytes.len() || !is_ident_byte(bytes[i + 5]);
                if before_ok && after_ok {
                    // Extract class name
                    let mut j = i + 5;
                    while j < bytes.len() && bytes[j].is_ascii_whitespace() {
                        j += 1;
                    }
                    let name_start = j;
                    while j < bytes.len() && is_ident_byte(bytes[j]) {
                        j += 1;
                    }
                    if j > name_start {
                        let name = String::from_utf8_lossy(&bytes[name_start..j]).to_string();
                        class_stack.push(name);
                    }
                }
            }
            _ => {}
        }
        i += 1;
    }

    // The innermost class is the last in class_brace_depths
    let class_name = class_brace_depths.last().map(|(n, _)| n.clone())?;

    // Find the class symbol and return its members
    for sym in &sym_table.symbols {
        if sym.name == class_name && sym.flags & tsc_rs_symbols::SYM_CLASS != 0 {
            let mut items = Vec::new();
            let mut seen = HashSet::new();
            for (member_name, &member_id) in &sym.members {
                if let Some(member_sym) = sym_table.get_symbol(member_id) {
                    let kind = completion_kind_for_flags(member_sym.flags);
                    items.push(json!({"label": member_name, "kind": kind, "detail": &class_name}));
                    seen.insert(member_name.clone());
                }
            }
            // Also include constructor parameter properties (e.g., `constructor(private x)`)
            // which may not be in the symbol table's members map.
            for decl in &sym.declarations {
                let start = decl.span.start as usize;
                let search_end = source.len().min(start + 2000);
                if start < search_end {
                    let region = &source[start..search_end];
                    for param_name in extract_constructor_param_properties(region) {
                        if seen.insert(param_name.clone()) {
                            items.push(
                                json!({"label": param_name, "kind": 10, "detail": &class_name}),
                            );
                        }
                    }
                }
            }
            if !items.is_empty() {
                return Some(items);
            }
        }
    }
    None
}

/// Extract parameter property names from a class source region.
/// Handles patterns like `constructor(private x, public y: string, readonly z)`.
fn extract_constructor_param_properties(class_source: &str) -> Vec<String> {
    let bytes = class_source.as_bytes();
    let mut result = Vec::new();

    // Find `constructor(` in the source
    let Some(ctor_pos) = class_source.find("constructor") else {
        return result;
    };
    let after_ctor = ctor_pos + "constructor".len();
    // Find the opening paren
    let mut p = after_ctor;
    while p < bytes.len() && bytes[p].is_ascii_whitespace() {
        p += 1;
    }
    if p >= bytes.len() || bytes[p] != b'(' {
        return result;
    }
    p += 1; // skip `(`

    // Parse parameter list
    let mut depth = 0i32;
    while p < bytes.len() {
        // Skip whitespace
        while p < bytes.len() && bytes[p].is_ascii_whitespace() {
            p += 1;
        }
        if p >= bytes.len() || bytes[p] == b')' {
            break;
        }

        // Check for access modifier: public, private, protected, readonly, override
        let word_start = p;
        while p < bytes.len() && is_ident_byte(bytes[p]) {
            p += 1;
        }
        let word = &class_source[word_start..p];
        let is_modifier = matches!(
            word,
            "public" | "private" | "protected" | "readonly" | "override"
        );

        if is_modifier {
            // Skip whitespace after modifier
            while p < bytes.len() && bytes[p].is_ascii_whitespace() {
                p += 1;
            }
            // Check for another modifier (e.g., `private readonly x`)
            let word2_start = p;
            while p < bytes.len() && is_ident_byte(bytes[p]) {
                p += 1;
            }
            let word2 = &class_source[word2_start..p];
            if matches!(word2, "readonly" | "override") {
                // Skip another modifier
                while p < bytes.len() && bytes[p].is_ascii_whitespace() {
                    p += 1;
                }
                let name_start = p;
                while p < bytes.len() && is_ident_byte(bytes[p]) {
                    p += 1;
                }
                let name = &class_source[name_start..p];
                if !name.is_empty() {
                    result.push(name.to_string());
                }
            } else if !word2.is_empty() && !matches!(word2, "public" | "private" | "protected") {
                // word2 is the parameter name
                result.push(word2.to_string());
            }
        }

        // Skip to next parameter (find comma or closing paren at depth 0)
        while p < bytes.len() {
            match bytes[p] {
                b'(' | b'<' | b'{' | b'[' => depth += 1,
                b')' | b'>' | b'}' | b']' => {
                    if depth > 0 {
                        depth -= 1;
                    } else {
                        break;
                    }
                }
                b',' if depth == 0 => {
                    p += 1;
                    break;
                }
                _ => {}
            }
            p += 1;
        }
    }
    result
}

/// Check if the cursor is inside a class body (not after a dot).
/// Uses the same brace-depth tracking as `find_enclosing_class_members`.
/// Find the parent class of the enclosing class (for `super.` completions).
/// Returns the parent class's members.
fn find_super_class_members(
    source: &str,
    offset: u32,
    sym_table: &SymbolTable,
) -> Option<Vec<Value>> {
    let bytes = source.as_bytes();
    let off = offset as usize;

    // First, find the enclosing class name using the same logic as find_enclosing_class_members
    let mut class_stack: Vec<String> = Vec::new();
    let mut brace_depth: i32 = 0;
    let mut class_brace_depths: Vec<(String, i32)> = Vec::new();
    let mut i = 0;
    let mut in_string: Option<u8> = None;
    let mut in_comment = false;
    let mut in_block_comment = false;

    while i < off {
        let b = bytes[i];
        let next = if i + 1 < bytes.len() { bytes[i + 1] } else { 0 };

        if in_comment {
            if b == b'\n' {
                in_comment = false;
            }
            i += 1;
            continue;
        }
        if in_block_comment {
            if b == b'*' && next == b'/' {
                in_block_comment = false;
                i += 2;
                continue;
            }
            i += 1;
            continue;
        }
        if let Some(q) = in_string {
            if b == b'\\' {
                i += 2;
                continue;
            }
            if b == q {
                in_string = None;
            }
            i += 1;
            continue;
        }

        match b {
            b'/' if next == b'/' => {
                in_comment = true;
                i += 2;
                continue;
            }
            b'/' if next == b'*' => {
                in_block_comment = true;
                i += 2;
                continue;
            }
            b'"' | b'\'' | b'`' => {
                in_string = Some(b);
            }
            b'{' => {
                brace_depth += 1;
                if let Some(name) = class_stack.pop() {
                    class_brace_depths.push((name, brace_depth));
                }
            }
            b'}' => {
                if let Some(last) = class_brace_depths.last() {
                    if last.1 == brace_depth {
                        class_brace_depths.pop();
                    }
                }
                brace_depth -= 1;
            }
            b'c' if i + 5 <= bytes.len() && &bytes[i..i + 5] == b"class" => {
                let before_ok = i == 0 || !is_ident_byte(bytes[i - 1]);
                let after_ok = i + 5 >= bytes.len() || !is_ident_byte(bytes[i + 5]);
                if before_ok && after_ok {
                    let mut j = i + 5;
                    while j < bytes.len() && bytes[j].is_ascii_whitespace() {
                        j += 1;
                    }
                    let name_start = j;
                    while j < bytes.len() && is_ident_byte(bytes[j]) {
                        j += 1;
                    }
                    if j > name_start {
                        let name = String::from_utf8_lossy(&bytes[name_start..j]).to_string();
                        class_stack.push(name);
                    }
                }
            }
            _ => {}
        }
        i += 1;
    }

    let class_name = class_brace_depths.last().map(|(n, _)| n.clone())?;

    // Now find the parent class from the `extends` clause
    // Look for `class ClassName extends ParentName` in source
    let pattern = format!("class {}", class_name);
    let class_pos = source.find(&pattern)?;
    let after_name = &source[class_pos + pattern.len()..];
    // Look for `extends` before `{` or `implements`
    let brace_pos = after_name.find('{').unwrap_or(after_name.len());
    let extends_region = &after_name[..brace_pos];

    let extends_keyword = "extends ";
    let extends_pos = extends_region.find(extends_keyword)?;
    let after_extends = &extends_region[extends_pos + extends_keyword.len()..];
    // Extract the parent class name (might have generics: `ParentName<T>`)
    let parent_name_end = after_extends
        .find(|c: char| !c.is_alphanumeric() && c != '_')
        .unwrap_or(after_extends.len());
    let parent_name = after_extends[..parent_name_end].trim();
    if parent_name.is_empty() {
        return None;
    }

    // Look up the parent class in the symbol table and return its non-private, non-static,
    // non-property (method-only) members — `super.` only accesses instance methods
    for sym in &sym_table.symbols {
        if sym.name == parent_name
            && sym.flags & tsc_rs_symbols::SYM_CLASS != 0
            && !sym.members.is_empty()
        {
            let mut items = Vec::new();
            for (member_name, &member_id) in &sym.members {
                if let Some(member_sym) = sym_table.get_symbol(member_id) {
                    let flags = member_sym.flags;
                    // Skip properties (only include methods/functions)
                    let is_method =
                        flags & (tsc_rs_symbols::SYM_METHOD | tsc_rs_symbols::SYM_FUNCTION) != 0;
                    let is_property = flags & tsc_rs_symbols::SYM_PROPERTY != 0;
                    if is_property && !is_method {
                        continue;
                    }
                    // Skip private and static members by checking source text around declaration
                    if let Some(decl) = member_sym.declarations.first() {
                        if is_member_private_or_static(source, decl.span.start) {
                            continue;
                        }
                    }
                    let kind = completion_kind_for_flags(flags);
                    items.push(json!({"label": member_name, "kind": kind, "detail": parent_name}));
                }
            }
            return Some(items);
        }
    }

    None
}

/// Check if a class member at the given position has `private` or `static` modifiers.
/// Scans backward from the member declaration position to the start of the line,
/// looking for `private` or `static` keywords.
fn is_member_private_or_static(source: &str, member_pos: u32) -> bool {
    let pos = member_pos as usize;
    if pos >= source.len() {
        return false;
    }

    // Scan backward to find the start of the line
    let line_start = source[..pos].rfind('\n').map(|p| p + 1).unwrap_or(0);
    let line_prefix = &source[line_start..pos];

    // Split the prefix into words and check for private/static keywords
    let words: Vec<&str> = line_prefix.split_whitespace().collect();
    words
        .iter()
        .any(|&w| w == "private" || w == "static" || w == "#")
}

/// Check if the cursor is in a type annotation context (where only types should appear).
///
/// Type annotation contexts include:
/// - After `:` in type annotations: `let x: |`, `function f(x: |)`, `(): |`
/// - Inside type literal bodies: `{ prop: | }` when that `{` is in type position
/// - After `extends`/`implements` in declarations
/// - Inside generic type arguments: `Foo<|>`

/// True when the token being completed directly follows `typeof` — a type
/// QUERY position where VALUE symbols are the valid completions.
fn is_after_typeof_keyword(source: &str, offset: u32) -> bool {
    let bytes = source.as_bytes();
    let mut i = (offset as usize).min(bytes.len());
    while i > 0 && is_ident_byte(bytes[i - 1]) {
        i -= 1;
    }
    while i > 0 && (bytes[i - 1] == b' ' || bytes[i - 1] == b'\t') {
        i -= 1;
    }
    let mut w = i;
    while w > 0 && is_ident_byte(bytes[w - 1]) {
        w -= 1;
    }
    &source[w..i] == "typeof"
}

fn is_in_type_annotation_context(source: &str, offset: u32) -> bool {
    let bytes = source.as_bytes();
    let off = offset as usize;
    if off > bytes.len() {
        return false;
    }

    // Walk backward from cursor, tracking brace/paren/angle bracket depth.
    // We're looking for the nearest "context introducer" — a `:`, `extends`, `implements`,
    // `<`, etc. that isn't inside a nested construct.
    let mut brace_depth: i32 = 0;
    let mut paren_depth: i32 = 0;
    let mut angle_depth: i32 = 0;
    let mut i = off;

    while i > 0 {
        i -= 1;
        let b = bytes[i];

        match b {
            b'}' => brace_depth += 1,
            b'{' => {
                if brace_depth == 0 {
                    // We hit an unmatched `{`. Check if it's a type literal `{`.
                    // A type literal `{` is preceded by `:`, `=` (in `type T = {`),
                    // `|`, `&`, `<`, `extends`, etc.
                    return is_type_literal_brace(source, i);
                }
                brace_depth -= 1;
            }
            b')' => paren_depth += 1,
            b'(' => {
                if paren_depth == 0 {
                    // Unmatched `(` — we're inside a paren group.
                    // Check if this is a type context paren (e.g., `(string | number)` type)
                    return false;
                }
                paren_depth -= 1;
            }
            b'>' if brace_depth == 0 && paren_depth == 0 => {
                angle_depth += 1;
            }
            b'<' if brace_depth == 0 && paren_depth == 0 => {
                if angle_depth > 0 {
                    angle_depth -= 1;
                } else {
                    // Unmatched `<` — could be type argument or JSX.
                    // Type args: preceded by identifier (`Foo<`, `Array<`)
                    // JSX: preceded by operator, `(`, `=`, line start, etc.
                    if i > 0 && is_ident_byte(bytes[i - 1]) {
                        return true;
                    }
                    // Not a type argument (likely JSX or comparison)
                    return false;
                }
            }
            b':' if brace_depth == 0 && paren_depth == 0 && angle_depth == 0 => {
                // Found a colon at the same nesting level.
                // Check if this is a type annotation colon (not object literal key colon or ternary).
                if is_type_annotation_colon(source, i) {
                    return true;
                }
                return false;
            }
            b'|' | b'&' if brace_depth == 0 && paren_depth == 0 && angle_depth == 0 => {
                // Union/intersection type operator — continue looking for the context introducer
                continue;
            }
            b'=' if brace_depth == 0 && paren_depth == 0 && angle_depth == 0 => {
                // Check for `type T = |` (type alias definition)
                if i > 0 {
                    let before_eq = source[..i].trim_end();
                    // Walk back over name
                    let name_end = before_eq.len();
                    let mut ne = name_end;
                    while ne > 0 && is_ident_byte(before_eq.as_bytes()[ne - 1]) {
                        ne -= 1;
                    }
                    let before_name = before_eq[..ne].trim_end();
                    if before_name.ends_with("type") {
                        let tp = before_name.len() - 4;
                        if tp == 0 || !is_ident_byte(before_name.as_bytes()[tp - 1]) {
                            return true;
                        }
                    }
                }
                return false;
            }
            b';' | b'\n' if brace_depth == 0 && paren_depth == 0 && angle_depth == 0 => {
                // Statement/line boundary — stop searching
                return false;
            }
            _ => {}
        }
    }
    false
}

/// Check if a colon at the given position is a type annotation colon.
/// Returns true for `param:`, `prop:`, `): ` (return type), but NOT for
/// object literal key colons like `{key: value}` or ternary `? :`.
fn is_type_annotation_colon(source: &str, colon_pos: usize) -> bool {
    let bytes = source.as_bytes();
    if colon_pos == 0 {
        return false;
    }

    let before = source[..colon_pos].trim_end();
    if before.is_empty() {
        return false;
    }
    let last = before.as_bytes()[before.len() - 1];

    // After `)` — return type annotation: `function f(): |`
    if last == b')' {
        return true;
    }

    // After `?` — optional parameter/property: `prop?: |`
    if last == b'?' {
        return true;
    }

    // After an identifier — could be param type, property type, or object key
    if is_ident_byte(last) {
        // Walk backward to find context
        let mut p = before.len();
        while p > 0 && is_ident_byte(before.as_bytes()[p - 1]) {
            p -= 1;
        }
        let _ident = &before[p..];

        // Check what's before the identifier
        let before_ident = before[..p].trim_end();
        if before_ident.is_empty() {
            return false;
        }
        let prev = before_ident.as_bytes()[before_ident.len() - 1];

        // If preceded by `(`, `,` — this is a parameter, so colon is type annotation
        if prev == b'(' || prev == b',' {
            return true;
        }

        // If preceded by `{` — could be destructuring param, type literal member, or object literal
        // Check if the `{` is a type literal brace
        if prev == b'{' {
            let brace_pos = before_ident.len() - 1;
            // Check if this `{` is in a type context
            return is_type_literal_brace(source, brace_pos);
        }

        // If preceded by `;` — property type in interface/type literal
        if prev == b';' {
            return true;
        }

        // If preceded by `let`, `var`, `const` — variable type annotation
        if before_ident.ends_with("let")
            || before_ident.ends_with("var")
            || before_ident.ends_with("const")
        {
            return true;
        }

        // Default: assume it's a type annotation in declaration context
        return true;
    }

    false
}

/// Check if a `{` at the given position is a type literal brace.
/// Returns true if preceded by `:`, `=` (in type alias), `|`, `&`, `<`, or `extends`.
fn is_type_literal_brace(source: &str, brace_pos: usize) -> bool {
    let bytes = source.as_bytes();
    let mut p = brace_pos;
    while p > 0 && bytes[p - 1].is_ascii_whitespace() {
        p -= 1;
    }
    if p == 0 {
        return false;
    }
    let prev = bytes[p - 1];

    match prev {
        b'|' | b'&' | b'<' => true,
        b':' => is_type_annotation_colon(source, p - 1),
        b'=' => {
            // `type T = {`
            let before_eq = source[..p - 1].trim_end();
            let name_end = before_eq.len();
            let mut ne = name_end;
            while ne > 0 && is_ident_byte(before_eq.as_bytes()[ne - 1]) {
                ne -= 1;
            }
            let before_name = before_eq[..ne].trim_end();
            if before_name.ends_with("type") {
                let tp = before_name.len() - 4;
                return tp == 0 || !is_ident_byte(before_name.as_bytes()[tp - 1]);
            }
            false
        }
        _ => {
            // Check for `extends {`, `implements {`
            if p >= 7 {
                let word_end = p;
                let mut wp = p;
                while wp > 0 && is_ident_byte(bytes[wp - 1]) {
                    wp -= 1;
                }
                let word = &source[wp..word_end];
                if word == "extends" || word == "implements" {
                    return true;
                }
            }
            false
        }
    }
}

/// Check if a symbol name corresponds to a type-like symbol (type, interface, class, enum, type param).
fn is_type_symbol_name(name: &str, sym_table: &SymbolTable) -> bool {
    for sym in &sym_table.symbols {
        if sym.name == name {
            let type_flags = tsc_rs_symbols::SYM_INTERFACE
                | tsc_rs_symbols::SYM_TYPE_ALIAS
                | tsc_rs_symbols::SYM_CLASS
                | tsc_rs_symbols::SYM_ENUM
                | tsc_rs_symbols::SYM_TYPE_PARAMETER;
            if sym.flags & type_flags != 0 {
                return true;
            }
        }
    }
    false
}

/// Check if the cursor is at the start of a member declaration inside an interface body.
///
/// At this position, only `readonly` should appear. This detects the member-declaration
/// position where the cursor is right after `{` or after `;`/newline in an interface body,
/// NOT at a type-value position within a member (like `prop: Type|`).
///
/// Patterns detected:
/// - `interface Foo { | }`
/// - `interface Foo {\n  | }`
/// - After a member: `interface Foo { prop: number; | }`
fn is_at_interface_member_start(source: &str, offset: u32) -> bool {
    let bytes = source.as_bytes();
    let off = offset as usize;
    if off > bytes.len() {
        return false;
    }

    // Check: is the cursor at the beginning of a new member?
    // Look at what's between the last `;`, `{`, or `}` (at same depth) and the cursor.
    // If it's only whitespace or JSDoc comments, we're at member-start position.
    let line_start = source[..off].rfind('\n').map(|p| p + 1).unwrap_or(0);
    let before_on_line = source[line_start..off].trim();

    // If there's already a property name or keyword on this line (non-empty), we're NOT
    // at member start — unless the content is a JSDoc closing `*/`
    if !before_on_line.is_empty() && !before_on_line.ends_with("*/") {
        return false;
    }

    // Now walk backward to find the enclosing `{` at depth 0 and check if it's an interface
    let mut brace_depth: i32 = 0;
    let mut i = off;

    while i > 0 {
        i -= 1;
        let b = bytes[i];

        match b {
            b'}' => {
                brace_depth += 1;
            }
            b'{' => {
                if brace_depth == 0 {
                    // Found the enclosing `{`. Check if it's an interface.
                    return is_interface_open_brace(source, i);
                }
                brace_depth -= 1;
            }
            _ => {}
        }
    }
    false
}

/// Helper: given the position of a `{`, check if it opens an interface body.
fn is_interface_open_brace(source: &str, brace_pos: usize) -> bool {
    let bytes = source.as_bytes();

    // Walk backward from `{`, skipping whitespace and generics/extends clause
    let mut p = brace_pos;
    while p > 0 && bytes[p - 1].is_ascii_whitespace() {
        p -= 1;
    }

    let check_start = p;

    // Skip over extends clause, generic params `<T>`, identifiers, commas
    let mut depth = 0i32;
    while p > 0 {
        let b = bytes[p - 1];
        if depth > 0 {
            if b == b'<' {
                depth -= 1;
            }
            if b == b'>' {
                depth += 1;
            }
            p -= 1;
            continue;
        }
        if b == b'>' {
            depth += 1;
            p -= 1;
            continue;
        }
        if b.is_ascii_whitespace() || is_ident_byte(b) || b == b',' || b == b'.' {
            p -= 1;
            continue;
        }
        break;
    }

    let region = &source[p..check_start];
    let trimmed = region.trim();

    // Check if region starts with "interface"
    if trimmed.starts_with("interface") {
        let after = &trimmed["interface".len()..];
        if after.is_empty() || !is_ident_byte(after.as_bytes()[0]) {
            return true;
        }
    }
    // `export interface ...` or `declare interface ...` or `export declare interface ...`
    let stripped = trimmed
        .strip_prefix("export")
        .map(|s| s.trim_start())
        .unwrap_or(trimmed);
    let stripped = stripped
        .strip_prefix("declare")
        .map(|s| s.trim_start())
        .unwrap_or(stripped);
    if stripped.starts_with("interface") {
        let after = &stripped["interface".len()..];
        if after.is_empty() || !is_ident_byte(after.as_bytes()[0]) {
            return true;
        }
    }

    false
}

/// Check if the cursor is inside an object binding pattern body: `let { | } = expr`
/// or `const { | } = expr` or function parameter `function f({ | })`.
///
/// In these positions, only the properties of the source object should appear,
/// not scope variables or keywords.
fn is_in_object_binding_pattern_body(source: &str, offset: u32) -> bool {
    let bytes = source.as_bytes();
    let off = offset as usize;
    if off > bytes.len() {
        return false;
    }

    // Walk backward from cursor to find the enclosing `{` at depth 0
    let mut brace_depth: i32 = 0;
    let mut i = off;
    let mut in_string: Option<u8> = None;

    while i > 0 {
        i -= 1;
        let b = bytes[i];

        if let Some(q) = in_string {
            if b == q {
                let mut esc = 0;
                let mut j = i;
                while j > 0 && bytes[j - 1] == b'\\' {
                    esc += 1;
                    j -= 1;
                }
                if esc % 2 == 0 {
                    in_string = None;
                }
            }
            continue;
        }

        match b {
            b'"' | b'\'' | b'`' => {
                in_string = Some(b);
            }
            b'}' => {
                brace_depth += 1;
            }
            b'{' => {
                if brace_depth == 0 {
                    // Found enclosing `{`. Check what precedes it.
                    return is_destructuring_open_brace(source, i);
                }
                brace_depth -= 1;
            }
            b';' if brace_depth == 0 => {
                return false;
            }
            _ => {}
        }
    }
    false
}

/// Provide property completions for object literals with a contextual type.
/// Detects patterns like:
///   `var x: SomeType = { | }`
///   `func({ | })`
/// Returns None if not in an object literal context.
/// Resolve the contextual type string governing the object literal that
/// encloses `off`. Handles `var: T = {`, call arguments `f({`/`f(a, {`, and
/// nested member positions `outer = { files: { ... } }` (recursively).
fn enclosing_object_type_str(
    source: &str,
    off: usize,
    sym_table: &SymbolTable,
    check_out: &TypeCheckOutput,
    depth_budget: u32,
) -> Option<String> {
    if depth_budget == 0 {
        return None;
    }
    let bytes = source.as_bytes();
    // Walk backward to the opening `{` at depth 0 (string-aware).
    let mut brace_depth: i32 = 0;
    let mut i = off;
    let mut in_string: Option<u8> = None;
    while i > 0 {
        i -= 1;
        let b = bytes[i];
        if let Some(q) = in_string {
            if b == q {
                let mut esc = 0;
                let mut j = i;
                while j > 0 && bytes[j - 1] == b'\\' {
                    esc += 1;
                    j -= 1;
                }
                if esc % 2 == 0 {
                    in_string = None;
                }
            }
            continue;
        }
        match b {
            b'"' | b'\'' | b'`' => in_string = Some(b),
            b'}' => brace_depth += 1,
            b'{' => {
                if brace_depth == 0 {
                    break;
                }
                brace_depth -= 1;
            }
            b';' if brace_depth == 0 => return None,
            _ => {}
        }
    }
    if i == 0 || bytes[i] != b'{' {
        return None;
    }
    let open_brace = i;
    let mut p = open_brace;
    while p > 0 && bytes[p - 1].is_ascii_whitespace() {
        p -= 1;
    }
    if p == 0 {
        return None;
    }
    match bytes[p - 1] {
        b'=' => {
            if p >= 2
                && (bytes[p - 2] == b'='
                    || bytes[p - 2] == b'!'
                    || bytes[p - 2] == b'<'
                    || bytes[p - 2] == b'>')
            {
                return None;
            }
            let var_name = find_variable_name_before_init(source, p - 1)?;
            for sym in &sym_table.symbols {
                if sym.name == var_name {
                    for decl in &sym.declarations {
                        if let Some(ty_str) = check_out.expression_types.get(&decl.span.start) {
                            return Some(ty_str.clone());
                        }
                    }
                }
            }
            None
        }
        b'(' | b',' => {
            let prev = bytes[p - 1];
            // Argument index
            let arg_index = if prev == b'(' {
                0usize
            } else {
                let mut commas = 1usize;
                let mut depth = 0i32;
                let mut s2 = p - 1;
                while s2 > 0 {
                    s2 -= 1;
                    match bytes[s2] {
                        b')' | b'}' | b']' => depth += 1,
                        b'[' | b'{' => depth -= 1,
                        b'(' => {
                            if depth == 0 {
                                break;
                            }
                            depth -= 1;
                        }
                        b',' if depth == 0 => commas += 1,
                        _ => {}
                    }
                }
                commas
            };
            let paren_pos = if prev == b'(' {
                p - 1
            } else {
                let mut s2 = p - 1;
                let mut depth = 0i32;
                while s2 > 0 {
                    s2 -= 1;
                    match bytes[s2] {
                        b')' | b'}' | b']' => depth += 1,
                        b'[' | b'{' => depth -= 1,
                        b'(' => {
                            if depth == 0 {
                                break;
                            }
                            depth -= 1;
                        }
                        _ => {}
                    }
                }
                s2
            };
            let fn_name = extract_token_at(source, paren_pos.saturating_sub(1) as u32);
            if fn_name.is_empty() {
                return None;
            }
            for sym in &sym_table.symbols {
                if sym.name == fn_name {
                    for decl in &sym.declarations {
                        if let Some(ty_str) = check_out.expression_types.get(&decl.span.start) {
                            if let Some(param_ty) =
                                extract_param_type_from_fn_type(ty_str, arg_index)
                            {
                                return Some(param_ty);
                            }
                        }
                    }
                }
            }
            None
        }
        b':' => {
            // Nested member position: resolve the outer object's type, then
            // this member's declared type.
            let mut q = p - 1;
            while q > 0 && bytes[q - 1].is_ascii_whitespace() {
                q -= 1;
            }
            let mut name_start = q;
            while name_start > 0 && is_ident_byte(bytes[name_start - 1]) {
                name_start -= 1;
            }
            if name_start == q {
                return None;
            }
            let prop_name = &source[name_start..q];
            let outer_ty = enclosing_object_type_str(
                source,
                name_start,
                sym_table,
                check_out,
                depth_budget - 1,
            )?;
            member_type_from_type_str(&outer_ty, prop_name, source, sym_table)
        }
        _ => None,
    }
}

/// Given a type string (structural `{...}` or a named type), find `prop_name`'s
/// declared type as a string. Named types resolve through the symbol table and
/// read the member's annotation from the source text.
fn member_type_from_type_str(
    ty_str: &str,
    prop_name: &str,
    source: &str,
    sym_table: &SymbolTable,
) -> Option<String> {
    let ty = ty_str.trim();
    if ty.starts_with('{') && ty.ends_with('}') {
        let inner = ty[1..ty.len() - 1].trim();
        let bytes = inner.as_bytes();
        let mut depth = 0i32;
        let mut start = 0usize;
        let mut check = |seg: &str| -> Option<String> {
            let seg = seg.trim();
            let rest = if let Some(r) = seg
                .strip_prefix('\'')
                .and_then(|r| r.strip_prefix(prop_name))
                .and_then(|r| r.strip_prefix('\''))
            {
                r
            } else if let Some(r) = seg
                .strip_prefix('"')
                .and_then(|r| r.strip_prefix(prop_name))
                .and_then(|r| r.strip_prefix('"'))
            {
                r
            } else if let Some(r) = seg.strip_prefix(prop_name) {
                // Bare name must not continue as a longer identifier
                if r.as_bytes().first().is_some_and(|&b| is_ident_byte(b)) {
                    return None;
                }
                r
            } else {
                return None;
            };
            let rest = rest.trim_start();
            let rest = rest.strip_prefix('?').unwrap_or(rest).trim_start();
            rest.strip_prefix(':').map(|v| v.trim().to_string())
        };
        for i in 0..bytes.len() {
            match bytes[i] {
                b'(' | b'<' | b'{' | b'[' => depth += 1,
                b')' | b'>' | b'}' | b']' => depth -= 1,
                b';' | b',' if depth == 0 => {
                    if let Some(v) = check(&inner[start..i]) {
                        return Some(v);
                    }
                    start = i + 1;
                }
                _ => {}
            }
        }
        return check(&inner[start..]);
    }
    // Named type: find the symbol, then the member, then read its annotation
    // from the declaration's source text.
    let base = ty.split('<').next().unwrap_or(ty).trim();
    for sym in &sym_table.symbols {
        if sym.name == base && !sym.members.is_empty() {
            if let Some(&member_id) = sym.members.get(prop_name) {
                if let Some(member_sym) = sym_table.get_symbol(member_id) {
                    for decl in &member_sym.declarations {
                        let start = decl.span.start as usize;
                        if start >= source.len() {
                            continue;
                        }
                        let tail = &source[start..];
                        // Skip the (possibly quoted) name, optional `?`, expect `:`
                        let after_colon = tail.find(':').map(|c| &tail[c + 1..])?;
                        // Take annotation up to `;`, `,`, or newline at depth 0
                        let ab = after_colon.as_bytes();
                        let mut depth = 0i32;
                        let mut end = ab.len();
                        for (i, &b) in ab.iter().enumerate() {
                            match b {
                                b'(' | b'<' | b'{' | b'[' => depth += 1,
                                b')' | b'>' | b'}' | b']' => {
                                    if depth == 0 {
                                        end = i;
                                        break;
                                    }
                                    depth -= 1;
                                }
                                b';' | b',' | b'\n' if depth == 0 => {
                                    end = i;
                                    break;
                                }
                                _ => {}
                            }
                        }
                        let ann = after_colon[..end].trim();
                        if !ann.is_empty() {
                            return Some(ann.to_string());
                        }
                    }
                }
            }
        }
    }
    None
}

/// Quote a property name for an object-literal completion label when it is not
/// a valid identifier (e.g. `jspm:browser` -> `"jspm:browser"`).
fn quote_prop_label(name: &str) -> String {
    let mut chars = name.chars();
    let valid_ident = match chars.next() {
        Some(c) if c.is_alphabetic() || c == '_' || c == '$' => {
            chars.all(|c| c.is_alphanumeric() || c == '_' || c == '$')
        }
        _ => false,
    };
    let all_digits = !name.is_empty() && name.chars().all(|c| c.is_ascii_digit());
    if valid_ident || all_digits {
        name.to_string()
    } else {
        format!("\"{}\"", name)
    }
}

fn object_literal_contextual_completions(
    source: &str,
    offset: u32,
    sym_table: &SymbolTable,
    check_out: &TypeCheckOutput,
    query_engine: &QueryEngine,
    in_string_name: bool,
) -> Option<Vec<Value>> {
    let bytes = source.as_bytes();
    let off = offset as usize;

    // Spread position `{ ...| }` completes VALUES (identifiers in scope), not
    // member names — leave it to the general identifier path.
    {
        let mut t = off;
        while t > 0 && is_ident_byte(bytes[t - 1]) {
            t -= 1;
        }
        if t >= 3 && bytes[t - 3..t] == [b'.', b'.', b'.'] {
            return None;
        }
    }

    // Walk backward to find the opening `{` at depth 0
    let mut brace_depth: i32 = 0;
    let mut i = off;
    let mut in_string: Option<u8> = None;
    while i > 0 {
        i -= 1;
        let b = bytes[i];
        if let Some(q) = in_string {
            if b == q {
                let mut esc = 0;
                let mut j = i;
                while j > 0 && bytes[j - 1] == b'\\' {
                    esc += 1;
                    j -= 1;
                }
                if esc % 2 == 0 {
                    in_string = None;
                }
            }
            continue;
        }
        match b {
            b'"' | b'\'' | b'`' => in_string = Some(b),
            b'}' => brace_depth += 1,
            b'{' => {
                if brace_depth == 0 {
                    break; // found enclosing `{`
                }
                brace_depth -= 1;
            }
            b';' if brace_depth == 0 => return None, // hit statement boundary
            _ => {}
        }
    }
    if i == 0 || bytes[i] != b'{' {
        return None;
    }
    let open_brace = i;

    // Check this is an object literal `{`, NOT a block statement or destructuring.
    // Look at what precedes the `{`:
    let mut p = open_brace;
    while p > 0 && bytes[p - 1].is_ascii_whitespace() {
        p -= 1;
    }
    if p == 0 {
        return None; // start of file — block
    }

    // If preceded by a destructuring keyword, skip (handled by binding_pattern_completions)
    if is_destructuring_open_brace(source, open_brace) {
        return None;
    }

    let prev = bytes[p - 1];
    // Object literal contexts:
    //   `= {`  (assignment / initialization)
    //   `( {`  or `, {` (function argument)
    //   `: {`  after `return` in some cases
    //   `[ {`  (array element)
    if !matches!(prev, b'=' | b'(' | b',' | b'[' | b':') {
        // Check for `=> {` (arrow body) or statement contexts — these are blocks, not object literals
        if prev == b'>' && p >= 2 && bytes[p - 2] == b'=' {
            return None; // `=> {` arrow body
        }
        return None;
    }

    // For `= {`, find the variable name and its type annotation
    if prev == b'=' {
        // Make sure it's not `==` or `=>`
        if p >= 2 && (bytes[p - 2] == b'=' || bytes[p - 2] == b'!') {
            return None;
        }

        // Scan backward from `=` to find the variable declaration
        let mut scan = p - 1;
        while scan > 0 && bytes[scan - 1].is_ascii_whitespace() {
            scan -= 1;
        }

        // Check for type annotation: `var x: Type = {`
        // We need to find the variable name, then its type
        // First, try to find the identifier before `=`
        let mut ident_end = scan;
        // Skip past any type annotation (scan backward past `: Type`)
        // Simple heuristic: find the last ident before `=`
        while ident_end > 0 && !is_ident_byte(bytes[ident_end - 1]) {
            ident_end -= 1;
        }
        let mut ident_start = ident_end;
        while ident_start > 0 && is_ident_byte(bytes[ident_start - 1]) {
            ident_start -= 1;
        }

        // This might be the end of a type annotation, not the variable name.
        // Check if this ident is preceded by `:` (type annotation) — if so, scan further back.
        let var_name = find_variable_name_before_init(source, p - 1);
        if let Some(ref name) = var_name {
            // Find the type annotation for this variable
            if let Some(props) = find_type_properties_for_var(
                name,
                source,
                open_brace,
                sym_table,
                check_out,
                query_engine,
            ) {
                let already_present = collect_existing_properties(source, open_brace, off);
                let items: Vec<Value> = props
                    .into_iter()
                    .filter(|(n, _)| in_string_name || !already_present.contains(n.as_str()))
                    .map(|(name, kind)| {
                        let label = if in_string_name {
                            name
                        } else {
                            quote_prop_label(&name)
                        };
                        json!({"label": label, "kind": kind})
                    })
                    .collect();
                if !items.is_empty() {
                    return Some(items);
                }
            }
        }
    }

    // For `( {` or `, {` — function argument position
    // Find the function being called and the parameter type at this position
    if matches!(prev, b'(' | b',') {
        // Count which argument position we're at
        let arg_index = if prev == b'(' {
            0usize
        } else {
            // Count commas at the same depth back to `(`
            let mut commas = 1usize;
            let mut depth = 0i32;
            let mut s = p - 1;
            while s > 0 {
                s -= 1;
                match bytes[s] {
                    b')' | b'}' | b']' => depth += 1,
                    b'[' | b'{' => depth -= 1,
                    b'(' => {
                        if depth == 0 {
                            break;
                        }
                        depth -= 1;
                    }
                    b',' if depth == 0 => commas += 1,
                    _ => {}
                }
            }
            commas
        };

        // Find the function name before `(`
        let paren_pos = if prev == b'(' {
            p - 1
        } else {
            // Scan back to find the `(`
            let mut s = p - 1;
            let mut depth = 0i32;
            while s > 0 {
                s -= 1;
                match bytes[s] {
                    b')' | b'}' | b']' => depth += 1,
                    b'[' | b'{' => depth -= 1,
                    b'(' => {
                        if depth == 0 {
                            break;
                        }
                        depth -= 1;
                    }
                    _ => {}
                }
            }
            s
        };
        let fn_name = extract_token_at(source, paren_pos.saturating_sub(1) as u32);
        if !fn_name.is_empty() {
            // Look up the function's parameter type at arg_index
            if let Some(props) =
                find_param_type_properties(&fn_name, arg_index, sym_table, check_out, query_engine)
            {
                let already_present = collect_existing_properties(source, open_brace, off);
                let items: Vec<Value> = props
                    .into_iter()
                    .filter(|(n, _)| in_string_name || !already_present.contains(n.as_str()))
                    .map(|(name, kind)| {
                        let label = if in_string_name {
                            name
                        } else {
                            quote_prop_label(&name)
                        };
                        json!({"label": label, "kind": kind})
                    })
                    .collect();
                if !items.is_empty() {
                    return Some(items);
                }
            }
        }
    }

    // Nested member position: `outer = { files: { | } }` — resolve the outer
    // object's contextual type, then this member's declared type.
    if prev == b':' {
        if let Some(member_ty) = enclosing_object_type_str(source, off, sym_table, check_out, 8) {
            if let Some(props) =
                extract_properties_from_type_str(&member_ty, sym_table, query_engine)
            {
                let already_present = collect_existing_properties(source, open_brace, off);
                let items: Vec<Value> = props
                    .into_iter()
                    .filter(|(n, _)| in_string_name || !already_present.contains(n.as_str()))
                    .map(|(name, kind)| {
                        let label = if in_string_name {
                            name
                        } else {
                            quote_prop_label(&name)
                        };
                        json!({"label": label, "kind": kind})
                    })
                    .collect();
                if !items.is_empty() {
                    return Some(items);
                }
            }
        }
    }

    None
}

/// Find the variable name in `var/let/const NAME: Type = ...` (the annotation
/// may be a multi-line type literal, union, intersection, or generic) or a bare
/// assignment `NAME = ...` before the `=` position. Walks type constituents
/// backward until it reaches the annotation `:` or a statement boundary.
fn find_variable_name_before_init(source: &str, eq_pos: usize) -> Option<String> {
    let bytes = source.as_bytes();
    let mut p = eq_pos; // points at '='
    let mut candidate: Option<(usize, usize)> = None; // (start, end) of last bare ident
    let mut budget = 4000usize; // backward-scan cap
    let skip_balanced = |p: &mut usize, open: u8, close: u8| -> bool {
        let mut depth = 0i32;
        while *p > 0 {
            *p -= 1;
            let b = bytes[*p];
            if b == close {
                depth += 1;
            } else if b == open {
                depth -= 1;
                if depth == 0 {
                    return true;
                }
            }
        }
        false
    };
    loop {
        while p > 0 && bytes[p - 1].is_ascii_whitespace() {
            p -= 1;
        }
        if p == 0 || budget == 0 {
            break;
        }
        budget = budget.saturating_sub(1);
        let c = bytes[p - 1];
        if is_ident_byte(c) {
            let end = p;
            let mut start = p;
            while start > 0 && is_ident_byte(bytes[start - 1]) {
                start -= 1;
            }
            if candidate.is_some() {
                // Two idents in a row (backward) — e.g. `let NAME =`: the
                // earlier one is a keyword/modifier; the later is the name.
                break;
            }
            candidate = Some((start, end));
            p = start;
            continue;
        }
        match c {
            b':' => {
                // Annotation colon — the variable name precedes it.
                p -= 1;
                while p > 0 && bytes[p - 1].is_ascii_whitespace() {
                    p -= 1;
                }
                let end = p;
                let mut start = p;
                while start > 0 && is_ident_byte(bytes[start - 1]) {
                    start -= 1;
                }
                if start == end || (start > 0 && bytes[start - 1] == b'.') {
                    return None;
                }
                return Some(source[start..end].to_string());
            }
            b'|' | b'&' => {
                // Union/intersection separator — keep walking constituents.
                candidate = None;
                p -= 1;
            }
            b'.' => {
                // Qualified type name `A.B` — continue the constituent.
                candidate = None;
                p -= 1;
            }
            b'}' if candidate.is_none() => {
                // Inline type-literal constituent: `NAME: { ... } = {`.
                if !skip_balanced(&mut p, b'{', b'}') {
                    return None;
                }
            }
            b']' if candidate.is_none() => {
                // Array suffix `T[]` or tuple — skip and continue.
                if !skip_balanced(&mut p, b'[', b']') {
                    return None;
                }
            }
            b'>' if candidate.is_none() => {
                // Generic args `Type<...>` — but `=> {` was excluded upstream.
                if p >= 2 && bytes[p - 2] == b'=' {
                    return None;
                }
                if !skip_balanced(&mut p, b'<', b'>') {
                    return None;
                }
            }
            b'"' | b'\'' => {
                // String-literal type constituent — skip it.
                candidate = None;
                let q = c;
                let mut i = p - 1;
                let mut found = false;
                while i > 0 {
                    i -= 1;
                    if bytes[i] == q {
                        found = true;
                        break;
                    }
                }
                if !found {
                    return None;
                }
                p = i;
            }
            _ => break, // statement boundary (`;`, `}` after ident, `(`, `,`, newline handled as ws)
        }
    }
    // No annotation colon found: the last ident consumed is the assignment
    // target (declaration keyword optional). Reject member assignments.
    let (start, end) = candidate?;
    if start > 0 && bytes[start - 1] == b'.' {
        return None;
    }
    Some(source[start..end].to_string())
}

/// Find properties of the type annotation for a variable declaration.
fn find_type_properties_for_var(
    var_name: &str,
    source: &str,
    _brace_pos: usize,
    sym_table: &SymbolTable,
    check_out: &TypeCheckOutput,
    query_engine: &QueryEngine,
) -> Option<Vec<(String, u64)>> {
    // 1. Check expression_types for the variable's declared type
    for sym in &sym_table.symbols {
        if sym.name == var_name {
            for decl in &sym.declarations {
                if let Some(ty_str) = check_out.expression_types.get(&decl.span.start) {
                    return extract_properties_from_type_str(ty_str, sym_table, query_engine);
                }
            }
        }
    }
    None
}

/// Find properties of the parameter type at a given argument index for a function call.
fn find_param_type_properties(
    fn_name: &str,
    arg_index: usize,
    sym_table: &SymbolTable,
    check_out: &TypeCheckOutput,
    query_engine: &QueryEngine,
) -> Option<Vec<(String, u64)>> {
    // Look up the function's type to find the parameter type
    for sym in &sym_table.symbols {
        if sym.name == fn_name {
            for decl in &sym.declarations {
                if let Some(ty_str) = check_out.expression_types.get(&decl.span.start) {
                    // Parse function type: (p1: T1, p2: T2) => R
                    // Extract the arg_index-th parameter's type
                    if let Some(param_type) = extract_param_type_from_fn_type(ty_str, arg_index) {
                        return extract_properties_from_type_str(
                            &param_type,
                            sym_table,
                            query_engine,
                        );
                    }
                }
            }
            // Also try direct symbol members for interface/class types used as params
        }
    }
    None
}

/// Extract the type string of the nth parameter from a function type string.
fn extract_param_type_from_fn_type(fn_type: &str, param_index: usize) -> Option<String> {
    // Pattern: (name1: Type1, name2: Type2) => ReturnType
    let paren_start = fn_type.find('(')?;
    let mut depth = 0i32;
    let mut paren_end = paren_start;
    for (i, b) in fn_type[paren_start..].bytes().enumerate() {
        match b {
            b'(' | b'<' | b'{' | b'[' => depth += 1,
            b')' | b'>' | b'}' | b']' => {
                depth -= 1;
                if depth == 0 {
                    paren_end = paren_start + i;
                    break;
                }
            }
            _ => {}
        }
    }
    let params_str = &fn_type[paren_start + 1..paren_end];

    // Split params by comma (respecting nested brackets)
    let mut params = Vec::new();
    let mut start = 0;
    let mut depth = 0i32;
    for (i, b) in params_str.bytes().enumerate() {
        match b {
            b'(' | b'<' | b'{' | b'[' => depth += 1,
            b')' | b'>' | b'}' | b']' => depth -= 1,
            b',' if depth == 0 => {
                params.push(&params_str[start..i]);
                start = i + 1;
            }
            _ => {}
        }
    }
    params.push(&params_str[start..]);

    // Get the param at the desired index
    let param = params.get(param_index)?.trim();
    // Extract type after `: `
    let colon_pos = param.find(':')?;
    Some(param[colon_pos + 1..].trim().to_string())
}

/// Extract property names from a type string by looking up interface/class members.
fn extract_properties_from_type_str(
    ty_str: &str,
    sym_table: &SymbolTable,
    query_engine: &QueryEngine,
) -> Option<Vec<(String, u64)>> {
    let ty_name = ty_str.trim();

    // Handle union types: `T1 | T2 | T3`
    // Split into constituents and collect all properties from object-type
    // members. Only a TOP-LEVEL `|` counts — a union inside a member
    // annotation (`{ prop_e: string | undefined }`) is not a union type.
    let has_top_level_pipe = {
        let b = ty_name.as_bytes();
        let mut d = 0i32;
        let mut found = false;
        for (i, &c) in b.iter().enumerate() {
            match c {
                b'(' | b'[' | b'{' | b'<' => d += 1,
                b'>' if i > 0 && b[i - 1] == b'=' => {}
                b')' | b']' | b'}' | b'>' => d -= 1,
                b'|' if d == 0 => {
                    found = true;
                    break;
                }
                _ => {}
            }
        }
        found
    };
    if has_top_level_pipe {
        let constituents = split_union_type(ty_name);
        if constituents.len() > 1 {
            let mut all_props: Vec<(String, u64)> = Vec::new();
            let mut seen: HashSet<String> = HashSet::new();
            for part in &constituents {
                let part = part.trim();
                // Skip non-object constituents (number, string, null, undefined, etc.)
                if part.is_empty()
                    || part == "null"
                    || part == "undefined"
                    || part == "number"
                    || part == "string"
                    || part == "boolean"
                    || part == "any"
                    || part == "never"
                    || part == "void"
                    || part == "unknown"
                    || part == "bigint"
                    || part == "symbol"
                {
                    continue;
                }
                if let Some(props) = extract_properties_from_type_str(part, sym_table, query_engine)
                {
                    for (name, kind) in props {
                        if seen.insert(name.clone()) {
                            all_props.push((name, kind));
                        }
                    }
                }
            }
            if !all_props.is_empty() {
                return Some(all_props);
            }
        }
    }

    // Check if it's a structural type: `{ prop1: T1; prop2: T2 }`
    if ty_name.starts_with('{') && ty_name.ends_with('}') {
        let inner = &ty_name[1..ty_name.len() - 1].trim();
        if inner.is_empty() {
            return None;
        }
        let mut props = Vec::new();
        // Parse one member's name; quoted names (`'jspm:browser': string`) must
        // not split on the colon inside the quotes.
        let parse_member_name = |member: &str| -> Option<String> {
            let member = member.trim();
            let first = *member.as_bytes().first()?;
            if first == b'\'' || first == b'"' {
                let rest = &member[1..];
                let close = rest.find(first as char)?;
                let name = &rest[..close];
                let after = rest[close + 1..].trim_start();
                let after = after.strip_prefix('?').unwrap_or(after).trim_start();
                if after.starts_with(':') && !name.is_empty() {
                    return Some(name.to_string());
                }
                return None;
            }
            // Depth-aware: the name ends at the first `:` or `(` at depth 0
            // (`M(x: string): number` is a method named `M`).
            let mb = member.as_bytes();
            let mut d = 0i32;
            let mut name_end = None;
            for (i, &b) in mb.iter().enumerate() {
                match b {
                    b'(' | b'<' | b'{' | b'[' => {
                        if b == b'(' && d == 0 {
                            name_end = Some(i);
                            break;
                        }
                        d += 1;
                    }
                    b')' | b'>' | b'}' | b']' => d -= 1,
                    b':' if d == 0 => {
                        name_end = Some(i);
                        break;
                    }
                    _ => {}
                }
            }
            let name = member[..name_end?].trim().trim_end_matches('?');
            if name.is_empty() {
                None
            } else {
                Some(name.to_string())
            }
        };
        // Split by `;` or `,` (respecting nested brackets)
        let mut depth = 0i32;
        let mut start = 0;
        let bytes = inner.as_bytes();
        // Mapped-type members `[_ in "a" | "b"]: T` expand to their literal keys;
        // index signatures `[key: string]: T` contribute nothing.
        let expand_member = |seg: &str, props: &mut Vec<(String, u64)>| {
            let seg_t = seg.trim();
            if seg_t.starts_with('[') {
                if let Some(close) = seg_t.find(']') {
                    let inside = &seg_t[1..close];
                    if let Some(in_pos) = inside.find(" in ") {
                        for part in inside[in_pos + 4..].split('|') {
                            let part = part.trim();
                            let unq = part
                                .strip_prefix('"')
                                .and_then(|r| r.strip_suffix('"'))
                                .or_else(|| {
                                    part.strip_prefix('\'').and_then(|r| r.strip_suffix('\''))
                                });
                            if let Some(name) = unq {
                                if !name.is_empty() {
                                    props.push((name.to_string(), 10u64));
                                }
                            }
                        }
                    }
                }
                return;
            }
            if let Some(name) = parse_member_name(seg_t) {
                props.push((name, 10u64)); // kind 10 = property
            }
        };
        for i in 0..bytes.len() {
            match bytes[i] {
                b'(' | b'<' | b'{' | b'[' => depth += 1,
                b'>' if i > 0 && bytes[i - 1] == b'=' => {}
                b')' | b'>' | b'}' | b']' => depth -= 1,
                // Type-literal members can be newline-separated with no `;`
                // (`prop_d: { p1: string; }\n prop_e: ...`).
                b';' | b',' | b'\n' if depth == 0 => {
                    expand_member(&inner[start..i], &mut props);
                    start = i + 1;
                }
                _ => {}
            }
        }
        // Last member
        expand_member(&inner[start..], &mut props);
        if !props.is_empty() {
            return Some(props);
        }
    }

    // Check symbol table for named type
    for sym in &sym_table.symbols {
        if sym.name == ty_name && !sym.members.is_empty() {
            let mut props = Vec::new();
            for (member_name, &member_id) in &sym.members {
                if let Some(member_sym) = sym_table.get_symbol(member_id) {
                    let kind = completion_kind_for_flags(member_sym.flags) as u64;
                    props.push((member_name.clone(), kind));
                }
            }
            if !props.is_empty() {
                return Some(props);
            }
        }
    }

    // Try QE
    let qe_members = query_engine.get_type_member_completions(ty_name);
    if !qe_members.is_empty() {
        let props: Vec<(String, u64)> = qe_members
            .into_iter()
            .map(|(name, flags, _)| (name, completion_kind_for_flags(flags) as u64))
            .collect();
        return Some(props);
    }

    None
}

/// Collect property names already present in an object literal.
/// Scans the entire body (including after cursor) so properties below the
/// cursor are also excluded. Recognises both comma- and newline-separated
/// property assignments.
fn collect_existing_properties(source: &str, open_brace: usize, cursor: usize) -> HashSet<String> {
    let bytes = source.as_bytes();
    // Find the closing `}` matching open_brace
    let mut depth = 1i32;
    let mut close_brace = open_brace + 1;
    while close_brace < bytes.len() && depth > 0 {
        match bytes[close_brace] {
            b'{' => depth += 1,
            b'}' => depth -= 1,
            _ => {}
        }
        if depth > 0 {
            close_brace += 1;
        }
    }
    let content = &source[open_brace + 1..close_brace];
    let mut props = HashSet::new();
    // Scan for `identifier:` or `identifier,` patterns — these are property keys.
    // Skip the region around the cursor.
    let cbytes = content.as_bytes();
    let mut i = 0;
    let mut nest = 0i32;
    while i < cbytes.len() {
        match cbytes[i] {
            b'(' | b'{' | b'[' | b'<' => {
                nest += 1;
                i += 1;
                continue;
            }
            b')' | b'}' | b']' | b'>' => {
                nest -= 1;
                i += 1;
                continue;
            }
            b'\'' | b'"' | b'`' => {
                // Skip string
                let q = cbytes[i];
                i += 1;
                while i < cbytes.len() && cbytes[i] != q {
                    if cbytes[i] == b'\\' {
                        i += 1;
                    }
                    i += 1;
                }
                i += 1;
                continue;
            }
            _ => {}
        }
        if nest > 0 {
            i += 1;
            continue;
        }

        // Look for `ident:` or `ident ,` patterns at depth 0
        if is_ident_byte(cbytes[i]) {
            let ident_start = i;
            while i < cbytes.len() && is_ident_byte(cbytes[i]) {
                i += 1;
            }
            let ident = &content[ident_start..i];
            // Check for `:` (property assignment) after optional whitespace
            let mut j = i;
            while j < cbytes.len() && cbytes[j].is_ascii_whitespace() {
                j += 1;
            }
            if j < cbytes.len() && cbytes[j] == b':' {
                // This is a property key — exclude if NOT at cursor position
                let abs_pos = open_brace + 1 + ident_start;
                if !(abs_pos <= cursor && cursor <= abs_pos + ident.len()) {
                    props.insert(ident.to_string());
                }
            }
            continue;
        }
        i += 1;
    }
    props
}

fn extract_property_key(part: &str) -> Option<String> {
    let trimmed = part.trim();
    if trimmed.is_empty() {
        return None;
    }
    // `key: value` or `key` (shorthand)
    let key = trimmed.split(':').next()?.trim();
    // Skip spread `...x`
    if key.starts_with("...") {
        return None;
    }
    let key: String = key
        .chars()
        .take_while(|c| c.is_alphanumeric() || *c == '_' || *c == '$')
        .collect();
    if key.is_empty() {
        None
    } else {
        Some(key)
    }
}

/// Provide completions for object binding patterns: `let { | } = expr`
/// Returns property names from the source expression's type.
fn binding_pattern_completions(
    source: &str,
    offset: u32,
    sym_table: &SymbolTable,
    check_out: &TypeCheckOutput,
    query_engine: &QueryEngine,
) -> Vec<Value> {
    let bytes = source.as_bytes();
    let off = offset as usize;

    // Find the closing `}` of the binding pattern
    let mut brace_depth = 1i32;
    let mut close_brace = off;
    while close_brace < bytes.len() {
        match bytes[close_brace] {
            b'{' => brace_depth += 1,
            b'}' => {
                brace_depth -= 1;
                if brace_depth == 0 {
                    break;
                }
            }
            _ => {}
        }
        close_brace += 1;
    }
    if close_brace >= bytes.len() {
        return Vec::new();
    }

    // Skip whitespace after `}`
    let mut scan = close_brace + 1;
    while scan < bytes.len() && bytes[scan].is_ascii_whitespace() {
        scan += 1;
    }

    // Check for `=` (assignment) or `:` followed by type then `=`
    if scan >= bytes.len() {
        return Vec::new();
    }

    // For `let { } : Type = expr` or `let { } = expr`
    let rhs_start = if bytes[scan] == b'=' && scan + 1 < bytes.len() && bytes[scan + 1] != b'>' {
        // `{ } = expr`
        scan + 1
    } else if bytes[scan] == b':' {
        // `{ } : Type = expr` or `({ } : Type)` (function param)
        // Extract the type name and try to resolve properties directly.
        let type_start = scan + 1;
        let mut s = type_start;
        while s < bytes.len() && bytes[s].is_ascii_whitespace() {
            s += 1;
        }
        let type_ident_start = s;
        while s < bytes.len() && is_ident_byte(bytes[s]) {
            s += 1;
        }
        if s > type_ident_start {
            let type_name = &source[type_ident_start..s];
            // Union annotation (`I | J`): tsc offers only the properties
            // COMMON to every constituent — intersect the per-constituent
            // property sets (completionListInObjectBindingPattern13).
            let mut union_props: Option<Vec<(String, u64)>> = None;
            {
                let mut u = s;
                let mut all: Vec<Vec<(String, u64)>> =
                    match extract_properties_from_type_str(type_name, sym_table, query_engine) {
                        Some(p) => vec![p],
                        None => Vec::new(),
                    };
                let mut saw_union = false;
                loop {
                    while u < bytes.len() && bytes[u].is_ascii_whitespace() {
                        u += 1;
                    }
                    if u >= bytes.len() || bytes[u] != b'|' {
                        break;
                    }
                    saw_union = true;
                    u += 1;
                    while u < bytes.len() && bytes[u].is_ascii_whitespace() {
                        u += 1;
                    }
                    let cs = u;
                    while u < bytes.len() && is_ident_byte(bytes[u]) {
                        u += 1;
                    }
                    if u == cs {
                        break;
                    }
                    match extract_properties_from_type_str(&source[cs..u], sym_table, query_engine)
                    {
                        Some(p) => all.push(p),
                        None => {
                            all.clear();
                            break;
                        }
                    }
                }
                if saw_union && !all.is_empty() {
                    let mut common = all[0].clone();
                    for other in &all[1..] {
                        common.retain(|(n, _)| other.iter().any(|(on, _)| on == n));
                    }
                    union_props = Some(common);
                }
            }
            if let Some(props) = union_props
                .or_else(|| extract_properties_from_type_str(type_name, sym_table, query_engine))
            {
                let open_brace_pos = {
                    let mut bi = off;
                    let mut bd = 0i32;
                    loop {
                        if bi == 0 {
                            break 0;
                        }
                        bi -= 1;
                        match bytes[bi] {
                            b'}' => bd += 1,
                            b'{' if bd == 0 => {
                                break bi;
                            }
                            b'{' => {
                                bd -= 1;
                            }
                            _ => {}
                        }
                    }
                };
                let cursor_token = extract_token_at(source, offset);
                let already_bound: HashSet<&str> = {
                    let pattern_text = &source[open_brace_pos + 1..off];
                    pattern_text
                        .split(',')
                        .map(|s| s.trim())
                        .filter(|s| !s.is_empty())
                        .map(|s| s.split(':').next().unwrap_or(s).trim())
                        .filter(|s| cursor_token.is_empty() || *s != cursor_token)
                        .collect()
                };
                let items: Vec<Value> = props
                    .into_iter()
                    .filter(|(n, _)| !already_bound.contains(n.as_str()))
                    .map(|(name, kind)| json!({"label": name, "kind": kind}))
                    .collect();
                return items;
            }
        }
        // Fall through: skip past type annotation to `=`
        s = type_start;
        let mut depth = 0i32;
        while s < bytes.len() {
            match bytes[s] {
                b'<' | b'{' | b'(' | b'[' => depth += 1,
                b'>' | b'}' | b')' | b']' => depth -= 1,
                b'=' if depth == 0 && (s + 1 >= bytes.len() || bytes[s + 1] != b'>') => {
                    break;
                }
                b';' | b'\n' if depth == 0 => return Vec::new(),
                _ => {}
            }
            s += 1;
        }
        if s >= bytes.len() || bytes[s] != b'=' {
            return Vec::new();
        }
        s + 1
    } else {
        return Vec::new();
    };

    // Extract the RHS expression identifier
    let mut e = rhs_start;
    while e < bytes.len() && bytes[e].is_ascii_whitespace() {
        e += 1;
    }
    let ident_start = e;
    while e < bytes.len() && is_ident_byte(bytes[e]) {
        e += 1;
    }
    if e == ident_start {
        return Vec::new();
    }
    let rhs_ident = &source[ident_start..e];

    // Collect already-destructured property names to exclude them.
    // The token the cursor is currently on is NOT excluded (user may be
    // editing an existing binding name).
    let open_brace = {
        let mut i = off;
        let mut depth = 0i32;
        loop {
            if i == 0 {
                break 0;
            }
            i -= 1;
            match bytes[i] {
                b'}' => depth += 1,
                b'{' => {
                    if depth == 0 {
                        break i;
                    }
                    depth -= 1;
                }
                _ => {}
            }
        }
    };
    // Find the token at cursor position (if any)
    let cursor_token = extract_token_at(source, offset);
    let already_bound: HashSet<&str> = {
        let pattern_text = &source[open_brace + 1..off];
        pattern_text
            .split(',')
            .map(|s| s.trim())
            .filter(|s| !s.is_empty())
            .map(|s| {
                // Handle `key: alias` — take just the key part
                s.split(':').next().unwrap_or(s).trim()
            })
            .filter(|s| {
                // Don't exclude the token the cursor is currently on
                cursor_token.is_empty() || *s != cursor_token
            })
            .collect()
    };

    // Look up the RHS symbol's type and offer its properties
    let mut items = Vec::new();

    // 1. Try symbol table members (for interfaces, classes, enums)
    for sym in &sym_table.symbols {
        if sym.name == rhs_ident {
            // Look up expression type at declaration position
            for decl in &sym.declarations {
                if let Some(ty_str) = check_out.expression_types.get(&decl.span.start) {
                    let members = member_completions_for_type(ty_str, sym_table, query_engine);
                    for item in members {
                        let label = item.get("label").and_then(|l| l.as_str()).unwrap_or("");
                        if !already_bound.contains(label) {
                            items.push(item);
                        }
                    }
                    if !items.is_empty() {
                        return items;
                    }
                }
            }
            // Try direct members on the symbol (for classes/interfaces)
            if !sym.members.is_empty() {
                for (member_name, &member_id) in &sym.members {
                    if already_bound.contains(member_name.as_str()) {
                        continue;
                    }
                    if let Some(member_sym) = sym_table.get_symbol(member_id) {
                        let kind = completion_kind_for_flags(member_sym.flags);
                        items.push(json!({"label": member_name, "kind": kind}));
                    }
                }
                if !items.is_empty() {
                    return items;
                }
            }
        }
    }

    // 2. Try looking up the variable's type reference and find the type's members
    for sym in &sym_table.symbols {
        if sym.name == rhs_ident {
            for decl in &sym.declarations {
                if let Some(ty_str) = check_out.expression_types.get(&decl.span.start) {
                    // If the type is a reference to an interface/class, look up that symbol's members
                    let type_name = ty_str.trim();
                    for type_sym in &sym_table.symbols {
                        if type_sym.name == type_name && !type_sym.members.is_empty() {
                            for (member_name, &member_id) in &type_sym.members {
                                if already_bound.contains(member_name.as_str()) {
                                    continue;
                                }
                                if let Some(member_sym) = sym_table.get_symbol(member_id) {
                                    let kind = completion_kind_for_flags(member_sym.flags);
                                    items.push(json!({"label": member_name, "kind": kind}));
                                }
                            }
                            if !items.is_empty() {
                                return items;
                            }
                        }
                    }
                }
            }
        }
    }

    // 3. Try QueryEngine member completions
    let qe_members = query_engine.get_type_member_completions(rhs_ident);
    for (name, flags, _detail) in qe_members {
        if already_bound.contains(name.as_str()) {
            continue;
        }
        let kind = completion_kind_for_flags(flags);
        items.push(json!({"label": name, "kind": kind}));
    }

    items
}

/// Helper: check if `{` at `brace_pos` opens a destructuring binding pattern.
/// Patterns: `let {`, `var {`, `const {`, `({` in function params, `, {` in params
fn is_destructuring_open_brace(source: &str, brace_pos: usize) -> bool {
    let bytes = source.as_bytes();
    let mut p = brace_pos;

    // Skip whitespace before `{`
    while p > 0 && bytes[p - 1].is_ascii_whitespace() {
        p -= 1;
    }

    if p == 0 {
        return false;
    }

    let prev_byte = bytes[p - 1];

    // Case 1: `let {`, `var {`, `const {`
    if is_ident_byte(prev_byte) {
        let ident_end = p;
        while p > 0 && is_ident_byte(bytes[p - 1]) {
            p -= 1;
        }
        let kw = &source[p..ident_end];
        if kw == "let" || kw == "var" || kw == "const" {
            let word_boundary = p == 0 || !is_ident_byte(bytes[p - 1]);
            return word_boundary;
        }
    }

    // Case 2: `({` in function parameter DECLARATION — `function f({` or `(a, {`
    // But NOT in a function CALL argument: `f({` is an object literal, not destructuring.
    if prev_byte == b'(' || prev_byte == b',' {
        // Check if this paren is part of a function/method/arrow parameter declaration.
        // Heuristic: look for `function`, `)` followed by `{` or `=>`, or class method patterns.
        let paren_or_comma_pos = p - 1;
        if is_function_parameter_context(source, paren_or_comma_pos) {
            return true;
        }
        return false;
    }

    // Case 3: `: {` in a nested destructuring `let { a: { | } }` or
    // function param `function f({ a: { } })`
    if prev_byte == b':' {
        // Check if this colon is inside an already-established destructuring context
        // by looking for another `{` further back that is a destructuring
        let mut bp = p - 1;
        let mut bd: i32 = 0;
        while bp > 0 {
            bp -= 1;
            match bytes[bp] {
                b'}' => bd += 1,
                b'{' => {
                    if bd == 0 {
                        return is_destructuring_open_brace(source, bp);
                    }
                    bd -= 1;
                }
                b';' if bd == 0 => return false,
                _ => {}
            }
        }
    }

    false
}

/// Check if a `(` or `,` position is inside a function parameter declaration context.
/// Distinguishes `function f(` (parameter declaration) from `f(` (function call).
fn is_function_parameter_context(source: &str, pos: usize) -> bool {
    let bytes = source.as_bytes();

    // If it's a comma, walk backward to find the opening `(`
    let paren_pos = if bytes[pos] == b',' {
        // Find the matching `(`
        let mut depth = 0i32;
        let mut p = pos;
        while p > 0 {
            p -= 1;
            match bytes[p] {
                b')' => depth += 1,
                b'(' => {
                    if depth == 0 {
                        break;
                    }
                    depth -= 1;
                }
                _ => {}
            }
        }
        if p == 0 && bytes[0] != b'(' {
            return false;
        }
        p
    } else {
        pos
    };

    // Now check what's before the `(`
    let mut p = paren_pos;
    while p > 0 && bytes[p - 1].is_ascii_whitespace() {
        p -= 1;
    }

    if p == 0 {
        return false;
    }

    // Read the identifier before `(`
    let ident_end = p;
    while p > 0 && is_ident_byte(bytes[p - 1]) {
        p -= 1;
    }
    let ident = &source[p..ident_end];

    // Check for function declaration keywords
    if ident == "function" {
        return true;
    }

    // Check what's before the identifier (could be `function name(`)
    let mut bp = p;
    while bp > 0 && bytes[bp - 1].is_ascii_whitespace() {
        bp -= 1;
    }
    // Could have `*` for generator: `function* name(`
    if bp > 0 && bytes[bp - 1] == b'*' {
        bp -= 1;
        while bp > 0 && bytes[bp - 1].is_ascii_whitespace() {
            bp -= 1;
        }
    }
    // Check for `function` keyword
    if bp >= 8 {
        let kw_start = bp - 8;
        if &source[kw_start..bp] == "function"
            && (kw_start == 0 || !is_ident_byte(bytes[kw_start - 1]))
        {
            return true;
        }
    }

    // Check for arrow function: `({...}) =>` — look FORWARD from the closing `)` for `=>`
    // Find the matching `)` for this `(`
    let mut depth = 0i32;
    let mut fp = paren_pos + 1;
    while fp < bytes.len() {
        match bytes[fp] {
            b'(' => depth += 1,
            b')' => {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            }
            _ => {}
        }
        fp += 1;
    }
    if fp < bytes.len() && bytes[fp] == b')' {
        // Check what follows `)`
        let mut after = fp + 1;
        // Skip whitespace and optional return type annotation
        while after < bytes.len() && bytes[after].is_ascii_whitespace() {
            after += 1;
        }
        // Could have type annotation `: Type` before `=>`
        if after < bytes.len() && bytes[after] == b':' {
            // Skip the type annotation — scan until `=>` or `{`
            after += 1;
            let mut td = 0i32;
            while after < bytes.len() {
                match bytes[after] {
                    b'=' if after + 1 < bytes.len() && bytes[after + 1] == b'>' && td == 0 => {
                        return true;
                    }
                    b'{' if td == 0 => break,
                    b'<' | b'(' | b'[' => td += 1,
                    b'>' | b')' | b']' => td -= 1,
                    _ => {}
                }
                after += 1;
            }
        }
        if after + 1 < bytes.len() && bytes[after] == b'=' && bytes[after + 1] == b'>' {
            return true;
        }
        // Check if followed by `{` (method body in a class or object)
        if after < bytes.len() && bytes[after] == b'{' {
            // This could be a method: `name(params) {`
            // Only count as function params if the identifier before `(` is NOT a control keyword
            let control_keywords = ["if", "for", "while", "switch", "catch", "with"];
            if !ident.is_empty() && !control_keywords.contains(&ident) {
                return true;
            }
        }
    }

    false
}

fn is_inside_class_body(source: &str, offset: u32) -> bool {
    let bytes = source.as_bytes();
    let off = offset as usize;

    let mut class_brace_depth_stack: Vec<i32> = Vec::new();
    let mut brace_depth: i32 = 0;
    let mut pending_class = false;
    let mut i = 0;
    let mut in_string: Option<u8> = None;
    let mut in_comment = false;
    let mut in_block_comment = false;

    while i < off {
        let b = bytes[i];
        let next = if i + 1 < bytes.len() { bytes[i + 1] } else { 0 };

        if in_comment {
            if b == b'\n' {
                in_comment = false;
            }
            i += 1;
            continue;
        }
        if in_block_comment {
            if b == b'*' && next == b'/' {
                in_block_comment = false;
                i += 2;
                continue;
            }
            i += 1;
            continue;
        }
        if let Some(q) = in_string {
            if b == b'\\' {
                i += 2;
                continue;
            }
            if b == q {
                in_string = None;
            }
            i += 1;
            continue;
        }

        match b {
            b'/' if next == b'/' => {
                in_comment = true;
                i += 2;
                continue;
            }
            b'/' if next == b'*' => {
                in_block_comment = true;
                i += 2;
                continue;
            }
            b'"' | b'\'' | b'`' => {
                in_string = Some(b);
            }
            b'{' => {
                brace_depth += 1;
                if pending_class {
                    class_brace_depth_stack.push(brace_depth);
                    pending_class = false;
                }
            }
            b'}' => {
                if let Some(&class_depth) = class_brace_depth_stack.last() {
                    if class_depth == brace_depth {
                        class_brace_depth_stack.pop();
                    }
                }
                brace_depth -= 1;
            }
            b'c' if i + 5 <= bytes.len() && &bytes[i..i + 5] == b"class" => {
                let before_ok = i == 0 || !is_ident_byte(bytes[i - 1]);
                let after_ok = i + 5 >= bytes.len() || !is_ident_byte(bytes[i + 5]);
                if before_ok && after_ok {
                    pending_class = true;
                }
            }
            _ => {}
        }
        i += 1;
    }

    !class_brace_depth_stack.is_empty()
}

/// Check if offset is directly in a class body (NOT inside a method/function body within the class).
/// Returns true only when the cursor is at the class member level, not nested deeper.
fn is_inside_class_body_direct(source: &str, offset: u32) -> bool {
    let bytes = source.as_bytes();
    let off = offset as usize;

    // Track class opening brace depths and function/method brace depths
    let mut class_brace_depths: Vec<i32> = Vec::new();
    let mut function_brace_depths: Vec<i32> = Vec::new();
    let mut brace_depth: i32 = 0;
    let mut pending_class = false;
    let mut pending_function = false;
    let mut i = 0;
    let mut in_string: Option<u8> = None;
    let mut in_comment = false;
    let mut in_block_comment = false;

    while i < off {
        let b = bytes[i];
        let next = if i + 1 < bytes.len() { bytes[i + 1] } else { 0 };

        if in_comment {
            if b == b'\n' {
                in_comment = false;
            }
            i += 1;
            continue;
        }
        if in_block_comment {
            if b == b'*' && next == b'/' {
                in_block_comment = false;
                i += 2;
                continue;
            }
            i += 1;
            continue;
        }
        if let Some(q) = in_string {
            if b == b'\\' {
                i += 2;
                continue;
            }
            if b == q {
                in_string = None;
            }
            i += 1;
            continue;
        }

        match b {
            b'/' if next == b'/' => {
                in_comment = true;
                i += 2;
                continue;
            }
            b'/' if next == b'*' => {
                in_block_comment = true;
                i += 2;
                continue;
            }
            b'"' | b'\'' | b'`' => {
                in_string = Some(b);
            }
            b'{' => {
                brace_depth += 1;
                if pending_class {
                    class_brace_depths.push(brace_depth);
                    pending_class = false;
                    pending_function = false;
                } else if pending_function {
                    function_brace_depths.push(brace_depth);
                    pending_function = false;
                }
            }
            b'}' => {
                // Check class close
                if let Some(&cd) = class_brace_depths.last() {
                    if cd == brace_depth {
                        class_brace_depths.pop();
                    }
                }
                // Check function close
                if let Some(&fd) = function_brace_depths.last() {
                    if fd == brace_depth {
                        function_brace_depths.pop();
                    }
                }
                brace_depth -= 1;
            }
            b'c' if i + 5 <= bytes.len() && &bytes[i..i + 5] == b"class" => {
                let before_ok = i == 0 || !is_ident_byte(bytes[i - 1]);
                let after_ok = i + 5 >= bytes.len() || !is_ident_byte(bytes[i + 5]);
                if before_ok && after_ok {
                    pending_class = true;
                    pending_function = false;
                }
            }
            b'f' if i + 8 <= bytes.len() && &bytes[i..i + 8] == b"function" => {
                let before_ok = i == 0 || !is_ident_byte(bytes[i - 1]);
                let after_ok = i + 8 >= bytes.len() || !is_ident_byte(bytes[i + 8]);
                if before_ok && after_ok {
                    pending_function = true;
                }
            }
            b'(' => {
                // A `(` after a non-class context often marks a method. If we're in
                // a class body and see `identifier(`, mark it as pending function
                // so its `{` is tracked.
                if !class_brace_depths.is_empty() && !pending_class {
                    pending_function = true;
                }
            }
            b')' => {
                // After `)` the next `{` should be the function body
                // pending_function stays true if it was set
            }
            b'=' if next == b'>' => {
                // Arrow function — next `{` (if any) is a function body
                pending_function = true;
                i += 2;
                continue;
            }
            _ => {}
        }
        i += 1;
    }

    // We're directly in a class body if we're inside a class AND NOT inside any function
    if class_brace_depths.is_empty() {
        return false;
    }
    let innermost_class = *class_brace_depths.last().unwrap();
    // Check if any function opens at a deeper level than the class
    for &fd in &function_brace_depths {
        if fd > innermost_class {
            return false; // we're inside a function within the class
        }
    }
    true
}

/// Check if cursor is at a position where completions should be blocked.
///
/// Positions where no completions should appear include:
/// - After `let`/`var`/`const` followed by an identifier (declaration name position)
/// - Inside function/method parameter names (but NOT in default values)
/// - After class property names before initializer
/// - In other "new identifier" positions
fn is_completion_list_blocker(source: &str, offset: u32) -> bool {
    let bytes = source.as_bytes();
    let off = offset as usize;

    // Find the text on the current line before the offset
    let line_start = source[..off].rfind('\n').map(|p| p + 1).unwrap_or(0);
    let before_on_line = &source[line_start..off];
    let trimmed = before_on_line.trim();

    // Check if we're right after a variable declaration name (before `=` or on same line as `let/var/const name`)
    // Pattern: `let foo |` or `var foo |` (cursor after the name, still on declaration line)
    if is_in_var_declaration_name(source, off) {
        return true;
    }

    // Check if we're in a function/method parameter name position
    if is_in_parameter_name_position(source, off) {
        return true;
    }

    // After a class property name (e.g., `public some |` where no completion makes sense)
    if is_after_class_property_name(source, off) {
        return true;
    }

    // Inside type parameter declarations: `class D<|`, `type T<|`, `function f<|`
    if is_in_type_parameter_declaration(source, off) {
        return true;
    }

    // After class/interface/enum/namespace declaration name: `class C |`, `interface I |`
    if is_after_declaration_keyword_name(source, off) {
        return true;
    }

    // After `as const` or `as Type` on the same line — no completions after type assertion
    if is_after_as_expression(source, off) {
        return true;
    }

    // After a regex literal on the same line (before newline)
    if is_after_regex_literal(source, off) {
        return true;
    }

    // In an object destructuring rename position: `var { x:name| }` — the `name` after `:` is a new binding
    if is_in_binding_element_rename(source, off) {
        return true;
    }

    // In a type annotation parameter name position: `var y : (s:string, name|`
    if is_in_type_annotation_param_name(source, off) {
        return true;
    }

    // After a BigInt literal on the same line: `const foo = 0n;|`
    if is_after_bigint_literal(source, off) {
        return true;
    }

    // In import namespace name position: `import * as |` — new name position
    if is_in_import_namespace_name(source, off) {
        return true;
    }

    // After a numeric literal with trailing content on same line: `0./** comment */|`
    if is_after_numeric_literal_same_line(source, off) {
        return true;
    }

    false
}

/// Check if cursor is right after a BigInt literal (`0n`, `123n`, etc.) on the same line.
fn is_after_bigint_literal(source: &str, off: usize) -> bool {
    let bytes = source.as_bytes();
    if off == 0 {
        return false;
    }

    // Walk backward, skipping optional `;`
    let mut p = off;
    while p > 0 && (bytes[p - 1] == b' ' || bytes[p - 1] == b'\t') {
        p -= 1;
    }
    if p > 0 && bytes[p - 1] == b';' {
        p -= 1;
        while p > 0 && (bytes[p - 1] == b' ' || bytes[p - 1] == b'\t') {
            p -= 1;
        }
    }
    // Check for `n` (BigInt suffix)
    if p > 0 && bytes[p - 1] == b'n' {
        p -= 1;
        // Should be preceded by digits
        if p > 0 && bytes[p - 1].is_ascii_digit() {
            // Verify we're on the same line
            let line_start = source[..off].rfind('\n').map(|pos| pos + 1).unwrap_or(0);
            return p >= line_start;
        }
    }
    false
}

/// Check if cursor is after a numeric literal followed by non-code content on same line.
/// E.g., `0./** comment */|` — after the comment on the same line as a numeric literal.
fn is_after_numeric_literal_same_line(source: &str, off: usize) -> bool {
    let bytes = source.as_bytes();
    let line_start = source[..off].rfind('\n').map(|p| p + 1).unwrap_or(0);
    let line = &source[line_start..off];
    let trimmed = line.trim();

    // Check if the line is just a numeric literal possibly followed by a block comment
    // Pattern: `0./** comment */`
    if trimmed.starts_with(|c: char| c.is_ascii_digit()) {
        // Check if there's a `/**` or `/*` on this line after the numeric part
        if let Some(comment_pos) = trimmed.find("/*") {
            // Check that everything between the number and comment is dots/digits/whitespace
            let before_comment = &trimmed[..comment_pos];
            let is_numeric_prefix = before_comment
                .chars()
                .all(|c| c.is_ascii_digit() || c == '.' || c.is_whitespace());
            if is_numeric_prefix && trimmed.ends_with("*/") {
                return true;
            }
        }
    }
    false
}

/// Check if cursor is in a namespace import name position: `import * as |`
fn is_in_import_namespace_name(source: &str, off: usize) -> bool {
    let bytes = source.as_bytes();

    // Walk backward from cursor
    let mut p = off;
    // Skip current identifier (if partially typed)
    while p > 0 && is_ident_byte(bytes[p - 1]) {
        p -= 1;
    }
    // Skip whitespace
    while p > 0 && (bytes[p - 1] == b' ' || bytes[p - 1] == b'\t') {
        p -= 1;
    }
    // Check for `as`
    if p >= 2 && &bytes[p - 2..p] == b"as" {
        let before_as = p - 2;
        let as_word_boundary = before_as == 0 || !is_ident_byte(bytes[before_as - 1]);
        if !as_word_boundary {
            return false;
        }
        // Check for `*` before `as`
        let mut bp = before_as;
        while bp > 0 && (bytes[bp - 1] == b' ' || bytes[bp - 1] == b'\t') {
            bp -= 1;
        }
        if bp > 0 && bytes[bp - 1] == b'*' {
            bp -= 1;
            while bp > 0 && (bytes[bp - 1] == b' ' || bytes[bp - 1] == b'\t') {
                bp -= 1;
            }
            // Check for `import` before `*`
            if bp >= 6 && &bytes[bp - 6..bp] == b"import" {
                let import_boundary = bp == 6 || !is_ident_byte(bytes[bp - 7]);
                if import_boundary {
                    return true;
                }
            }
        }
    }
    false
}

/// Check if cursor is after `as const`, `as Type`, `as any`, etc. on the same line.
/// In TypeScript, after `expr as Type` there should be no completions on the same line.
fn is_after_as_expression(source: &str, off: usize) -> bool {
    let bytes = source.as_bytes();

    // Walk backward from cursor, skipping whitespace (but stop at newline)
    let mut p = off;
    while p > 0 && bytes[p - 1] == b' ' || (p > 0 && bytes[p - 1] == b'\t') {
        p -= 1;
    }

    // Check if we just finished an identifier or keyword (the type after `as`)
    let ident_end = p;
    while p > 0 && is_ident_byte(bytes[p - 1]) {
        p -= 1;
    }
    let ident = &source[p..ident_end];
    if ident.is_empty() {
        return false;
    }

    // Check if `as` precedes this identifier
    let mut ap = p;
    while ap > 0 && (bytes[ap - 1] == b' ' || bytes[ap - 1] == b'\t') {
        ap -= 1;
    }
    // Check for `as`
    if ap >= 2 {
        let potential_as = &source[ap - 2..ap];
        if potential_as == "as" {
            let before_as_ok = ap == 2 || !is_ident_byte(bytes[ap - 3]);
            if before_as_ok {
                // Verify we're still on the same line
                let line_start = source[..off].rfind('\n').map(|p| p + 1).unwrap_or(0);
                if ap - 2 >= line_start {
                    return true;
                }
            }
        }
    }

    false
}

/// Check if cursor is right after a regex literal on the same line.
/// E.g., `let x = /absidey/|` or `let x = /absidey/g|`
fn is_after_regex_literal(source: &str, off: usize) -> bool {
    let bytes = source.as_bytes();
    if off == 0 {
        return false;
    }

    let line_start = source[..off].rfind('\n').map(|p| p + 1).unwrap_or(0);
    let line = &source[line_start..off];
    let trimmed = line.trim_end();

    // Check if line ends with /regex/ or /regex/flags
    // Walk backward from the cursor looking for the closing `/`
    let mut p = off;
    // Skip regex flags (g, i, m, s, u, y, d)
    while p > 0 && matches!(bytes[p - 1], b'g' | b'i' | b'm' | b's' | b'u' | b'y' | b'd') {
        p -= 1;
    }
    // Check for closing `/`
    if p > 0 && bytes[p - 1] == b'/' {
        p -= 1;
        // Walk backward to find opening `/`, making sure we don't cross a newline
        let slash_pos = p;
        while p > line_start as usize && bytes[p - 1] != b'/' && bytes[p - 1] != b'\n' {
            p -= 1;
        }
        if p > 0 && p > line_start as usize && bytes[p - 1] == b'/' {
            // Found opening `/`. This looks like a regex.
            // Verify: what's before the opening `/`? Should be an operator, `=`, `(`, etc.
            let before_regex = p - 1;
            if before_regex == 0 {
                return true;
            }
            let mut bp = before_regex;
            while bp > 0 && (bytes[bp - 1] == b' ' || bytes[bp - 1] == b'\t') {
                bp -= 1;
            }
            if bp == 0 {
                return true;
            }
            let prev = bytes[bp - 1];
            // Regex follows operators, keywords, `(`, `[`, `{`, `=`, `,`, `;`, `!`, etc.
            if matches!(
                prev,
                b'=' | b'('
                    | b'['
                    | b'{'
                    | b','
                    | b';'
                    | b'!'
                    | b'&'
                    | b'|'
                    | b'^'
                    | b'~'
                    | b'+'
                    | b'-'
                    | b'*'
                    | b'%'
                    | b'<'
                    | b'>'
                    | b'?'
                    | b':'
                    | b'\n'
            ) {
                return true;
            }
        }
    }

    false
}

/// Check if cursor is in an object destructuring binding rename position.
/// E.g., `var { x:name| }` — `name` after `:` in destructuring is a new binding.
fn is_in_binding_element_rename(source: &str, off: usize) -> bool {
    let bytes = source.as_bytes();

    // Walk backward from cursor, looking for `property:` pattern in destructuring
    let mut p = off;
    // Skip whitespace
    while p > 0 && bytes[p - 1] == b' ' {
        p -= 1;
    }
    // Optionally read identifier (might not be typed yet: `{ x: | }`)
    while p > 0 && is_ident_byte(bytes[p - 1]) {
        p -= 1;
    }
    // Skip whitespace
    while p > 0 && bytes[p - 1] == b' ' {
        p -= 1;
    }
    // Check for `:`
    if p == 0 || bytes[p - 1] != b':' {
        return false;
    }
    p -= 1;
    // Skip whitespace
    while p > 0 && bytes[p - 1] == b' ' {
        p -= 1;
    }
    // Read the property name before `:`
    let prop_end = p;
    while p > 0 && is_ident_byte(bytes[p - 1]) {
        p -= 1;
    }
    if p == prop_end {
        return false;
    }

    // Now check if this is inside a destructuring pattern: look for `{` at some depth
    // and `let`/`var`/`const` before it
    let mut pp = p;
    let mut brace_depth = 0i32;
    let mut bracket_depth = 0i32;
    while pp > 0 {
        pp -= 1;
        match bytes[pp] {
            b'}' => brace_depth += 1,
            b'{' => {
                if brace_depth == 0 {
                    // Found opening `{`. Check what's before it.
                    let mut kp = pp;
                    while kp > 0 && bytes[kp - 1] == b' ' {
                        kp -= 1;
                    }
                    // Check for let/var/const before `{` (destructuring declaration)
                    // Note: do NOT match `= {` as that could be a regular object literal
                    let kp_end = kp;
                    while kp > 0 && is_ident_byte(bytes[kp - 1]) {
                        kp -= 1;
                    }
                    let kw = &source[kp..kp_end];
                    if matches!(kw, "let" | "var" | "const" | "using") {
                        return true;
                    }
                    return false;
                }
                brace_depth -= 1;
            }
            b']' => bracket_depth += 1,
            b'[' => {
                if bracket_depth == 0 {
                    return false; // Array destructuring, not object
                }
                bracket_depth -= 1;
            }
            b';' | b'\n' => return false, // Went too far
            _ => {}
        }
    }

    false
}

/// Check if cursor is in a type annotation's parameter name position.
/// E.g., `var y : (s:string, name|` — `name` is a parameter name in a function type.
fn is_in_type_annotation_param_name(source: &str, off: usize) -> bool {
    let bytes = source.as_bytes();

    // Walk backward from cursor
    let mut p = off;
    // Skip current identifier
    while p > 0 && is_ident_byte(bytes[p - 1]) {
        p -= 1;
    }
    // Skip whitespace
    while p > 0 && (bytes[p - 1] == b' ' || bytes[p - 1] == b'\t') {
        p -= 1;
    }
    // Check for `,` (separating params) or `(` (start of param list)
    if p == 0 || !matches!(bytes[p - 1], b',' | b'(') {
        return false;
    }

    // Now check: is this `(` part of a type annotation?
    // Walk backward past the `(` to find `:` from a type annotation
    let sep_pos = p - 1;
    if bytes[sep_pos] == b'(' {
        // Find what's before `(` — should be `:` for a type annotation
        let mut tp = sep_pos;
        while tp > 0 && (bytes[tp - 1] == b' ' || bytes[tp - 1] == b'\t') {
            tp -= 1;
        }
        if tp > 0 && bytes[tp - 1] == b':' {
            // Check if this `:` is a type annotation (not an object property `:`)
            // Look for let/var/const before
            tp -= 1;
            while tp > 0 && (bytes[tp - 1] == b' ' || bytes[tp - 1] == b'\t') {
                tp -= 1;
            }
            // Read identifier
            let ie = tp;
            while tp > 0 && is_ident_byte(bytes[tp - 1]) {
                tp -= 1;
            }
            // Read what's before it
            while tp > 0 && (bytes[tp - 1] == b' ' || bytes[tp - 1] == b'\t') {
                tp -= 1;
            }
            let ke = tp;
            while tp > 0 && is_ident_byte(bytes[tp - 1]) {
                tp -= 1;
            }
            let kw = &source[tp..ke];
            if matches!(kw, "let" | "var" | "const") {
                return true;
            }
        }
    } else if bytes[sep_pos] == b',' {
        // After a `,` in a param list within a type annotation
        // Walk backward to find the `(` that starts this parameter list
        let mut pd = 0i32;
        let mut tp = sep_pos;
        while tp > 0 {
            tp -= 1;
            match bytes[tp] {
                b')' => pd += 1,
                b'(' => {
                    if pd == 0 {
                        // Found the opening `(`
                        // Check if it's a type annotation context
                        let mut kp = tp;
                        while kp > 0 && (bytes[kp - 1] == b' ' || bytes[kp - 1] == b'\t') {
                            kp -= 1;
                        }
                        if kp > 0 && bytes[kp - 1] == b':' {
                            return true;
                        }
                        break;
                    }
                    pd -= 1;
                }
                _ => {}
            }
        }
    }

    false
}

/// Check if cursor is right AT a class/interface/enum/namespace declaration name.
/// E.g., `class C|` — cursor at end of name, block completions.
/// But NOT `class C |` — after the name with space, allow completions (for `extends` etc.).
fn is_after_declaration_keyword_name(source: &str, off: usize) -> bool {
    let bytes = source.as_bytes();

    // Only block when cursor is RIGHT at the end of the name (no whitespace gap)
    // `class C|` → block, `class C |` → don't block (allow extends/implements keywords)
    let mut pos = off;

    // Check: is cursor right at end of an identifier (no whitespace before)?
    if pos == 0 || !is_ident_byte(bytes[pos - 1]) {
        return false; // Not at end of identifier — might be after whitespace
    }

    // Read identifier
    let ident_end = pos;
    while pos > 0 && is_ident_byte(bytes[pos - 1]) {
        pos -= 1;
    }
    if pos == ident_end {
        return false;
    }
    let ident = &source[pos..ident_end];

    // Skip type parameters (e.g., `class C<T> |`)
    if pos > 0 && bytes[pos - 1] == b'>' {
        // Walk past `<...>`
        let mut ad: i32 = 1;
        let mut ap = pos - 1;
        while ap > 0 && ad > 0 {
            ap -= 1;
            match bytes[ap] {
                b'>' => ad += 1,
                b'<' => ad -= 1,
                _ => {}
            }
        }
        if ad == 0 {
            pos = ap; // Now pos is at `<`
                      // Walk back to find the class name
            while pos > 0 && bytes[pos - 1].is_ascii_whitespace() {
                pos -= 1;
            }
            let n_end = pos;
            while pos > 0 && is_ident_byte(bytes[pos - 1]) {
                pos -= 1;
            }
            // Continue to check what's before this identifier
        }
    }

    // Check if there's a declaration keyword before the identifier
    let mut kp = pos;
    while kp > 0 && bytes[kp - 1].is_ascii_whitespace() {
        kp -= 1;
    }
    let kp_end = kp;
    while kp > 0 && is_ident_byte(bytes[kp - 1]) {
        kp -= 1;
    }
    // A keyword from a PREVIOUS line's trailing comment must not count
    // (a trailing "// ... module" comment above a fresh identifier).
    if source[kp..pos].contains('\n') {
        let kw_line_start = source[..kp].rfind('\n').map(|i| i + 1).unwrap_or(0);
        if source[kw_line_start..kp].contains("//") {
            return false;
        }
    }
    let keyword = &source[kp..kp_end];

    // Also check for `export` before the keyword
    if matches!(
        keyword,
        "class" | "interface" | "enum" | "namespace" | "module"
    ) {
        return true;
    }

    // Check for `export class`, `abstract class`, `declare class`, etc.
    if matches!(keyword, "export" | "abstract" | "declare" | "default") {
        // Check if the identifier itself is a declaration keyword
        if matches!(
            ident,
            "class" | "interface" | "enum" | "namespace" | "module"
        ) {
            // `export class |` — cursor after `class` where name is expected
            // But we actually need the name to be typed already
            return false;
        }
    }

    false
}

/// Check if cursor is in a variable declaration name position.
/// E.g., `let foo |` or `var bar |` — the name has been typed but no `=` yet.
fn is_in_var_declaration_name(source: &str, off: usize) -> bool {
    let bytes = source.as_bytes();

    // Walk back from cursor position, skip whitespace
    let mut pos = off;
    while pos > 0 && bytes[pos - 1].is_ascii_whitespace() && bytes[pos - 1] != b'\n' {
        pos -= 1;
    }

    // Check if there's an identifier before the whitespace
    let ident_end = pos;
    while pos > 0 && is_ident_byte(bytes[pos - 1]) {
        pos -= 1;
    }
    let ident_start = pos;
    if ident_start == ident_end {
        return false;
    }

    let ident = &source[ident_start..ident_end];

    // Don't block if the identifier is a keyword that starts a new statement
    // (e.g. the cursor is right after a keyword like `let |` which should NOT block)
    // But `let foo |` SHOULD block.

    // Now check: is there a `let`/`var`/`const` before this identifier (with only whitespace between)?
    let mut p2 = ident_start;
    while p2 > 0 && bytes[p2 - 1].is_ascii_whitespace() {
        p2 -= 1;
    }

    // Check for let/var/const/using
    for kw in &["let", "var", "const", "using"] {
        let kw_bytes = kw.as_bytes();
        let kw_len = kw_bytes.len();
        if p2 >= kw_len {
            let kw_start = p2 - kw_len;
            if &bytes[kw_start..p2] == kw_bytes {
                let before_kw_ok = kw_start == 0 || !is_ident_byte(bytes[kw_start - 1]);
                if before_kw_ok {
                    // We found `<keyword> <ident> |cursor` — this is a declaration name
                    // But check if the cursor-to-right has `=` or `:` — if so, completions
                    // might be wanted. If it's just whitespace/newline/`;`, block.
                    // Actually, the test `completionAfterNewline` expects blocking on same line.
                    return true;
                }
            }
        }
    }

    false
}

/// Check if cursor is in a function/method parameter name position.
/// E.g., `function foo(|`, `function foo(a |`, `method(a, |`
/// These are positions inside the parenthesized parameter list where a new name is expected.
fn is_in_parameter_name_position(source: &str, off: usize) -> bool {
    let bytes = source.as_bytes();

    // Walk backwards to find the matching `(`, tracking parens and braces
    let mut paren_depth: i32 = 0;
    let mut brace_depth: i32 = 0;
    let mut bracket_depth: i32 = 0;
    let mut found_open_paren = false;
    let mut i = off;

    // Check if we're in the default value part (after `=` inside params)
    // Walk back to see if we hit `=` before `(` or `,` at the same paren level
    let mut saw_equals = false;
    let mut j = off;
    while j > 0 {
        j -= 1;
        let b = bytes[j];
        match b {
            b'=' if paren_depth == 0 && brace_depth == 0 && bracket_depth == 0 => {
                // Check it's not ==, !=, <=, >=, =>
                let prev = if j > 0 { bytes[j - 1] } else { 0 };
                let next = if j + 1 < bytes.len() { bytes[j + 1] } else { 0 };
                if prev != b'!'
                    && prev != b'<'
                    && prev != b'>'
                    && prev != b'='
                    && next != b'='
                    && next != b'>'
                {
                    saw_equals = true;
                    break;
                }
            }
            b',' if paren_depth == 0 && brace_depth == 0 && bracket_depth == 0 => break,
            b'(' if paren_depth == 0 => break,
            b')' => paren_depth += 1,
            b'(' => paren_depth -= 1,
            b'}' => brace_depth += 1,
            b'{' => brace_depth -= 1,
            b']' => bracket_depth += 1,
            b'[' => bracket_depth -= 1,
            _ => {}
        }
    }

    if saw_equals {
        return false; // We're in a default value expression — don't block
    }

    // Now do the real check: find the enclosing `(` at paren depth 0
    paren_depth = 0;
    brace_depth = 0;
    i = off;
    while i > 0 {
        i -= 1;
        let b = bytes[i];
        match b {
            b')' => paren_depth += 1,
            b'(' => {
                if paren_depth == 0 {
                    found_open_paren = true;
                    break;
                }
                paren_depth -= 1;
            }
            b'}' => brace_depth += 1,
            b'{' => {
                if brace_depth == 0 {
                    return false; // Hit a `{` before finding `(` — not in params
                }
                brace_depth -= 1;
            }
            _ => {}
        }
    }

    if !found_open_paren {
        return false;
    }

    // Check what comes before the `(` — should be a function/method name or keyword
    let paren_pos = i;
    let mut p = paren_pos;
    while p > 0 && bytes[p - 1].is_ascii_whitespace() {
        p -= 1;
    }

    // Extract identifier before `(`
    let ident_end = p;
    while p > 0 && is_ident_byte(bytes[p - 1]) {
        p -= 1;
    }
    let before_paren = &source[p..ident_end];

    // Check what's before that identifier (for `function foo(`, `class C { method(`, etc.)
    let mut kp = p;
    while kp > 0 && bytes[kp - 1].is_ascii_whitespace() {
        kp -= 1;
    }

    // If the identifier IS `function`, block completions in parameter name positions
    // But NOT for `constructor` — constructor params can have access modifiers
    if before_paren == "function" {
        return is_at_param_name_in_list(source, off, paren_pos);
    }
    // Constructor: allow completions at start-of-param positions (for modifiers)
    // but still block after a parameter name has been typed
    if before_paren == "constructor" {
        return is_after_param_name_in_constructor(source, off, paren_pos);
    }

    // Check if `function` precedes the identifier: `function foo(`
    let kp_end = kp;
    let mut kp2 = kp;
    while kp2 > 0 && is_ident_byte(bytes[kp2 - 1]) {
        kp2 -= 1;
    }
    let preceding_keyword = &source[kp2..kp_end];
    if preceding_keyword == "function" {
        return is_at_param_name_in_list(source, off, paren_pos);
    }

    // Also check for methods: inside a class body, the paren could be a method parameter list
    // Heuristic: if we're inside a class body and before `(` there's an identifier, it's a method
    if is_inside_class_body(source, paren_pos as u32) && !before_paren.is_empty() {
        if before_paren == "constructor" {
            return is_after_param_name_in_constructor(source, off, paren_pos);
        }
        return is_at_param_name_in_list(source, off, paren_pos);
    }

    // Arrow functions: `(a, b) =>` — check if after the matching `)` there's `=>`
    // Find the matching `)`
    let mut pd = 1i32;
    let mut ap = paren_pos + 1;
    while ap < bytes.len() && pd > 0 {
        match bytes[ap] {
            b'(' => pd += 1,
            b')' => pd -= 1,
            _ => {}
        }
        ap += 1;
    }
    // Now check what follows `)`
    while ap < bytes.len() && bytes[ap].is_ascii_whitespace() {
        ap += 1;
    }
    if ap + 1 < bytes.len() && bytes[ap] == b'=' && bytes[ap + 1] == b'>' {
        return is_at_param_name_in_list(source, off, paren_pos);
    }

    false
}

/// Check if cursor is inside a type parameter declaration (the angle brackets in
/// `class Foo<|`, `type T<|`, `function f<|`, `interface I<|`).
/// Type parameter names are new identifiers, so completions should be blocked.
fn is_in_type_parameter_declaration(source: &str, off: usize) -> bool {
    let bytes = source.as_bytes();

    // Walk backwards to find `<` at angle bracket depth 0
    let mut angle_depth: i32 = 0;
    let mut paren_depth: i32 = 0;
    let mut brace_depth: i32 = 0;
    let mut i = off;
    let mut found_open_angle = false;

    while i > 0 {
        i -= 1;
        let b = bytes[i];
        match b {
            b'>' if paren_depth == 0 && brace_depth == 0 => angle_depth += 1,
            b'<' if paren_depth == 0 && brace_depth == 0 => {
                if angle_depth == 0 {
                    found_open_angle = true;
                    break;
                }
                angle_depth -= 1;
            }
            b')' => paren_depth += 1,
            b'(' => {
                if paren_depth == 0 {
                    return false; // Hit `(` before finding `<` — not in type params
                }
                paren_depth -= 1;
            }
            b'}' => brace_depth += 1,
            b'{' => {
                if brace_depth == 0 {
                    return false; // Hit `{` before finding `<` — not in type params
                }
                brace_depth -= 1;
            }
            b';' | b'\n' if angle_depth == 0 && paren_depth == 0 && brace_depth == 0 => {
                // Statement boundary before finding `<`
                return false;
            }
            _ => {}
        }
    }

    if !found_open_angle {
        return false;
    }

    let angle_pos = i;

    // Check what comes before the `<` — should be a type parameter context
    let mut p = angle_pos;
    while p > 0 && bytes[p - 1].is_ascii_whitespace() {
        p -= 1;
    }

    // Extract identifier before `<`
    let ident_end = p;
    while p > 0 && is_ident_byte(bytes[p - 1]) {
        p -= 1;
    }
    let before_angle = &source[p..ident_end];

    // If directly `class<`, `interface<`, `type<`, `function<` — it's a type param declaration
    if matches!(before_angle, "class" | "interface" | "type" | "function") {
        // Check: if `extends` is between `<` and cursor, this might be a constraint
        // `<T extends |` — at constraints, completions SHOULD appear
        return is_at_type_param_name_position(source, off, angle_pos);
    }

    // Check what's before the identifier (for `class Foo<`, `function bar<`, `type X<`)
    let mut kp = p;
    while kp > 0 && bytes[kp - 1].is_ascii_whitespace() {
        kp -= 1;
    }
    let kp_end = kp;
    let mut kp2 = kp;
    while kp2 > 0 && is_ident_byte(bytes[kp2 - 1]) {
        kp2 -= 1;
    }
    let preceding = &source[kp2..kp_end];

    if matches!(preceding, "class" | "interface" | "type" | "function") {
        return is_at_type_param_name_position(source, off, angle_pos);
    }

    // Could also be a method: `name<` inside a class body
    // or a var: `var x = class<` or `var x = class Name<`
    // For simplicity, check if the `<` follows an identifier and there's no `=` between
    if !before_angle.is_empty() && !before_angle.contains('=') {
        // Check if there's a class/function/type context further back
        // For method type params in class: `method<T>(`
        if is_inside_class_body(source, angle_pos as u32) {
            return is_at_type_param_name_position(source, off, angle_pos);
        }
    }

    false
}

/// Check if within a type parameter declaration, the cursor is at a name position
/// (as opposed to a constraint or default type).
fn is_at_type_param_name_position(source: &str, off: usize, open_angle: usize) -> bool {
    let bytes = source.as_bytes();

    // Walk back from cursor
    let mut pos = off;
    while pos > 0 && bytes[pos - 1].is_ascii_whitespace() {
        pos -= 1;
    }

    // Check what's right before the cursor
    if pos > 0 {
        match bytes[pos - 1] {
            b'<' | b',' => return true, // Right after `<` or `,` — name position
            _ => {}
        }
    }

    // Check if we just typed an identifier after `<` or `,`
    let ident_end = pos;
    while pos > 0 && is_ident_byte(bytes[pos - 1]) {
        pos -= 1;
    }
    if pos < ident_end {
        let ident = &source[pos..ident_end];
        // Check what's before the identifier
        let mut bp = pos;
        while bp > 0 && bytes[bp - 1].is_ascii_whitespace() {
            bp -= 1;
        }
        if bp > 0 {
            match bytes[bp - 1] {
                b'<' | b',' => {
                    // `< name |` or `, name |` — after type param name, block
                    // But check: is cursor right at the end of the ident (no whitespace)?
                    // If so, user is still typing the name — could be blocked or allowed
                    // For simplicity, block in both cases (since these are declaration names)
                    return true;
                }
                _ => {}
            }
            // Check for `extends` keyword before the identifier — it's a constraint
            let ep_end = bp;
            let mut ep = bp;
            while ep > 0 && is_ident_byte(bytes[ep - 1]) {
                ep -= 1;
            }
            let prev_kw = &source[ep..ep_end];
            if prev_kw == "extends" {
                return false; // After `extends` — constraint position, allow completions
            }
        }
    }

    false
}

/// Check if within a parenthesized parameter list, the cursor is at a position
/// where a parameter NAME is expected (as opposed to a type annotation or default value).
fn is_at_param_name_in_list(source: &str, off: usize, _open_paren: usize) -> bool {
    let bytes = source.as_bytes();

    // Walk back from cursor to find what precedes it
    let mut pos = off;
    while pos > 0 && bytes[pos - 1].is_ascii_whitespace() {
        pos -= 1;
    }

    // If we just saw `:`, we're in a type annotation — don't block
    if pos > 0 && bytes[pos - 1] == b':' {
        return false;
    }

    // If we just saw `=`, we're in a default value — don't block
    if pos > 0 && bytes[pos - 1] == b'=' {
        let prev2 = if pos > 1 { bytes[pos - 2] } else { 0 };
        if prev2 != b'!' && prev2 != b'<' && prev2 != b'>' && prev2 != b'=' {
            return false;
        }
    }

    // Walk back past identifier at cursor
    let ident_end = pos;
    while pos > 0 && is_ident_byte(bytes[pos - 1]) {
        pos -= 1;
    }
    let ident_start = pos;

    // If there's an identifier, check what's before it
    if ident_start < ident_end {
        // Skip whitespace before the identifier
        let mut bp = ident_start;
        while bp > 0 && bytes[bp - 1].is_ascii_whitespace() {
            bp -= 1;
        }
        if bp > 0 {
            let prev_char = bytes[bp - 1];
            match prev_char {
                b':' => return false,       // After `:` — type position
                b'=' => return false,       // After `=` — default value
                b'(' | b',' => return true, // After `(` or `,` — name position
                _ => {}
            }
            // Could be after a modifier like `public`, `private`, etc.
            let mut mp = bp;
            while mp > 0 && is_ident_byte(bytes[mp - 1]) {
                mp -= 1;
            }
            let modifier = &source[mp..bp];
            if matches!(
                modifier,
                "public" | "private" | "protected" | "readonly" | "override" | "abstract"
            ) {
                return true; // After modifier — still name position
            }
        }
    } else {
        // No identifier at cursor — check the char right before (after whitespace skip)
        if pos > 0 {
            match bytes[pos - 1] {
                b'(' | b',' => return true, // Right after `(` or `,` — name position
                b':' => return false,       // Type position
                _ => {}
            }
        }
    }

    false
}

/// For constructor parameters: check if cursor is after a parameter name
/// (where completions should be blocked), versus at the start of a new
/// parameter (where modifier completions should be allowed).
///
/// Returns true (block) for: `constructor(a |`, `constructor(public a |`
/// Returns false (allow) for: `constructor(|`, `constructor(a, |`, `constructor(public |`
fn is_after_param_name_in_constructor(source: &str, off: usize, open_paren: usize) -> bool {
    let bytes = source.as_bytes();

    // Walk back from cursor, skip whitespace
    let mut pos = off;
    while pos > 0 && bytes[pos - 1].is_ascii_whitespace() {
        pos -= 1;
    }

    // If we hit `:`, we're in a type annotation — don't block
    if pos > 0 && bytes[pos - 1] == b':' {
        return false;
    }
    // If we hit `=`, we're in a default value — don't block
    if pos > 0 && bytes[pos - 1] == b'=' {
        return false;
    }
    // If we hit `(` or `,`, we're at start of new param — don't block (allow modifiers)
    if pos > 0 && (bytes[pos - 1] == b'(' || bytes[pos - 1] == b',') {
        return false;
    }

    // Walk back past identifier
    let ident_end = pos;
    while pos > 0 && is_ident_byte(bytes[pos - 1]) {
        pos -= 1;
    }
    if pos == ident_end {
        return false; // No identifier — allow
    }
    let ident = &source[pos..ident_end];

    // If the ident is a modifier keyword, don't block (we're after `public |` etc.)
    if matches!(
        ident,
        "public" | "private" | "protected" | "readonly" | "override" | "abstract"
    ) {
        return false;
    }

    // Check what's before the identifier
    let mut bp = pos;
    while bp > 0 && bytes[bp - 1].is_ascii_whitespace() {
        bp -= 1;
    }

    if bp > 0 {
        match bytes[bp - 1] {
            b'(' | b',' => {
                // `( name |` or `, name |` — we've typed a param name, block
                return true;
            }
            _ => {
                // Check if preceded by a modifier
                let mp_end = bp;
                let mut mp = bp;
                while mp > 0 && is_ident_byte(bytes[mp - 1]) {
                    mp -= 1;
                }
                let prev_word = &source[mp..mp_end];
                if matches!(
                    prev_word,
                    "public" | "private" | "protected" | "readonly" | "override"
                ) {
                    // `modifier name |` — name already typed, block
                    return true;
                }
            }
        }
    }

    false
}

/// Check if cursor is after a class property name (e.g., `public some |`)
fn is_after_class_property_name(source: &str, off: usize) -> bool {
    if !is_inside_class_body(source, off as u32) {
        return false;
    }
    // Also need to ensure we're directly in the class body, not in a method
    if !is_inside_class_body_direct(source, off as u32) {
        return false;
    }

    let bytes = source.as_bytes();

    // Walk back from cursor, skip whitespace
    let mut pos = off;
    let had_whitespace_before_cursor =
        pos > 0 && (bytes[pos - 1] == b' ' || bytes[pos - 1] == b'\t');
    while pos > 0 && (bytes[pos - 1] == b' ' || bytes[pos - 1] == b'\t') {
        pos -= 1;
    }

    // Read the identifier
    let ident_end = pos;
    while pos > 0 && is_ident_byte(bytes[pos - 1]) {
        pos -= 1;
    }
    if pos == ident_end {
        return false;
    }
    let ident = &source[pos..ident_end];

    // If the cursor is right at the end of the identifier (no whitespace gap),
    // the user is still typing — don't block (allow completions for the partial name)
    if !had_whitespace_before_cursor {
        return false;
    }

    // If ident is a class keyword/modifier, this is the start of a member declaration, not after a name
    if matches!(
        ident,
        "public"
            | "private"
            | "protected"
            | "readonly"
            | "static"
            | "abstract"
            | "async"
            | "get"
            | "set"
            | "override"
            | "accessor"
            | "declare"
            | "constructor"
    ) {
        return false;
    }

    // Check what's before the identifier — should be a modifier or newline (start of member)
    let mut bp = pos;
    while bp > 0 && (bytes[bp - 1] == b' ' || bytes[bp - 1] == b'\t') {
        bp -= 1;
    }

    if bp == 0
        || bytes[bp - 1] == b'\n'
        || bytes[bp - 1] == b'\r'
        || bytes[bp - 1] == b'{'
        || bytes[bp - 1] == b';'
        || bytes[bp - 1] == b'}'
    {
        // Identifier at start of line in class body — this is a property name
        // Check forward from cursor: if `(` follows, it's actually a method start — don't block
        let mut fp = off;
        while fp < bytes.len() && bytes[fp].is_ascii_whitespace() {
            fp += 1;
        }
        if fp < bytes.len() && bytes[fp] == b'(' {
            return false; // Method call — completions ok
        }
        return true;
    }

    // Check if before the ident there's a modifier
    let bp_end = bp;
    let mut mp = bp;
    while mp > 0 && is_ident_byte(bytes[mp - 1]) {
        mp -= 1;
    }
    let modifier = &source[mp..bp_end];
    if matches!(
        modifier,
        "public"
            | "private"
            | "protected"
            | "readonly"
            | "static"
            | "abstract"
            | "async"
            | "get"
            | "set"
            | "override"
            | "accessor"
            | "declare"
    ) {
        // `modifier name |` — cursor after property name
        let mut fp = off;
        while fp < bytes.len() && bytes[fp].is_ascii_whitespace() {
            fp += 1;
        }
        if fp < bytes.len() && bytes[fp] == b'(' {
            return false; // Method
        }
        return true;
    }

    false
}

/// Check if cursor is at a position after `as` in an import/export rename.
/// E.g., `export { bar as | }` or `import { x as | }`
/// Find the name of the innermost enclosing class at the given offset, if any.
fn find_enclosing_class_name(source: &str, offset: u32) -> Option<String> {
    let bytes = source.as_bytes();
    let off = offset as usize;

    let mut class_stack: Vec<(String, i32)> = Vec::new(); // (name, brace_depth)
    let mut brace_depth: i32 = 0;
    let mut pending_class_name: Option<String> = None;
    let mut i = 0;
    let mut in_string: Option<u8> = None;
    let mut in_comment = false;
    let mut in_block_comment = false;

    while i < off {
        let b = bytes[i];
        let next = if i + 1 < bytes.len() { bytes[i + 1] } else { 0 };

        if in_comment {
            if b == b'\n' {
                in_comment = false;
            }
            i += 1;
            continue;
        }
        if in_block_comment {
            if b == b'*' && next == b'/' {
                in_block_comment = false;
                i += 2;
                continue;
            }
            i += 1;
            continue;
        }
        if let Some(q) = in_string {
            if b == b'\\' {
                i += 2;
                continue;
            }
            if b == q {
                in_string = None;
            }
            i += 1;
            continue;
        }

        match b {
            b'/' if next == b'/' => {
                in_comment = true;
                i += 2;
                continue;
            }
            b'/' if next == b'*' => {
                in_block_comment = true;
                i += 2;
                continue;
            }
            b'"' | b'\'' | b'`' => {
                in_string = Some(b);
            }
            b'{' => {
                brace_depth += 1;
                if let Some(name) = pending_class_name.take() {
                    class_stack.push((name, brace_depth));
                }
            }
            b'}' => {
                if let Some(last) = class_stack.last() {
                    if last.1 == brace_depth {
                        class_stack.pop();
                    }
                }
                brace_depth -= 1;
            }
            b'c' if i + 5 <= bytes.len() && &bytes[i..i + 5] == b"class" => {
                let before_ok = i == 0 || !is_ident_byte(bytes[i - 1]);
                let after_ok = i + 5 >= bytes.len() || !is_ident_byte(bytes[i + 5]);
                if before_ok && after_ok {
                    let mut j = i + 5;
                    while j < bytes.len() && bytes[j].is_ascii_whitespace() {
                        j += 1;
                    }
                    let name_start = j;
                    while j < bytes.len() && is_ident_byte(bytes[j]) {
                        j += 1;
                    }
                    if j > name_start {
                        pending_class_name =
                            Some(String::from_utf8_lossy(&bytes[name_start..j]).to_string());
                    }
                }
            }
            _ => {}
        }
        i += 1;
    }

    class_stack.last().map(|(n, _)| n.clone())
}

/// Filter out private members (#-prefixed) from completion results unless
/// the cursor is inside the class that declares them.
fn filter_private_members(
    items: Vec<Value>,
    enclosing_class: &Option<String>,
    source: &str,
    offset: u32,
    sym_table: &SymbolTable,
) -> Vec<Value> {
    // Check if we're accessing `this.` — private members of own class are visible
    let bytes = source.as_bytes();
    let dot_pos = (offset - 1) as usize;

    // Check for optional chaining `?.` — walk back from dot to find `?`
    // Handle both `this?.` and `expr?.`
    let is_optional_chain = dot_pos > 0 && bytes.get(dot_pos - 1) == Some(&b'?');

    // Find the identifier before the dot (or before `?.`)
    let search_pos = if is_optional_chain {
        dot_pos.saturating_sub(2)
    } else {
        dot_pos.saturating_sub(1)
    };
    let ident_before_dot = extract_token_at(source, search_pos as u32);
    let is_this_access = ident_before_dot == "this";

    // Build a set of private/protected member names from ALL classes in the
    // extends chain. Items may come from different classes (via inheritance),
    // so check each class referenced in item "detail" fields.
    let mut private_names = std::collections::HashSet::new();
    let mut protected_names = std::collections::HashSet::new();
    {
        let mut checked_classes = std::collections::HashSet::new();
        for item in &items {
            if let Some(class_name) = item.get("detail").and_then(|d| d.as_str()) {
                if !checked_classes.insert(class_name.to_string()) {
                    continue;
                }
                for sym in &sym_table.symbols {
                    if sym.name == class_name
                        && sym.flags & (tsc_rs_symbols::SYM_CLASS | tsc_rs_symbols::SYM_INTERFACE)
                            != 0
                    {
                        for (member_name, &member_id) in &sym.members {
                            if let Some(member_sym) = sym_table.get_symbol(member_id) {
                                if let Some(decl) = member_sym.declarations.first() {
                                    let start = decl.span.start as usize;
                                    if start < source.len() {
                                        let line_start =
                                            source[..start].rfind('\n').map(|p| p + 1).unwrap_or(0);
                                        let prefix = source[line_start..start].trim();
                                        let words: Vec<&str> = prefix.split_whitespace().collect();
                                        if words.iter().any(|w| *w == "private") {
                                            private_names.insert(member_name.clone());
                                        } else if words.iter().any(|w| *w == "protected") {
                                            protected_names.insert(member_name.clone());
                                        }
                                    }
                                }
                            }
                        }
                        break;
                    }
                }
            }
        }
    }

    let needs_filtering = !private_names.is_empty()
        || !protected_names.is_empty()
        || items.iter().any(|item| {
            item.get("label")
                .and_then(|l| l.as_str())
                .map(|s| s.starts_with('#'))
                .unwrap_or(false)
        });

    if !needs_filtering {
        return items;
    }

    let target_class = items
        .first()
        .and_then(|i| i.get("detail"))
        .and_then(|d| d.as_str())
        .map(|s| s.to_string());

    items
        .into_iter()
        .filter(|item| {
            let label = item.get("label").and_then(|l| l.as_str()).unwrap_or("");
            if label.starts_with('#') {
                // ECMA private field: only show if accessing `this.` inside the declaring class
                if is_this_access && !is_optional_chain {
                    return true;
                }
                return false;
            }
            // TypeScript `private` keyword: only visible inside the declaring class via `this.`
            if private_names.contains(label) {
                return is_this_access
                    && enclosing_class
                        .as_ref()
                        .map(|c| target_class.as_ref().map(|d| d == c).unwrap_or(false))
                        .unwrap_or(false);
            }
            // TypeScript `protected` keyword: visible inside declaring class and subclasses via `this.`
            if protected_names.contains(label) && !is_this_access {
                return false;
            }
            true
        })
        .collect()
}

/// Check if the cursor is inside an import or export specifier list
/// and return appropriate completions. Returns None if not in such a context.
fn import_export_specifier_completions(
    source: &str,
    offset: u32,
    sym_table: &SymbolTable,
    query_engine: &QueryEngine,
) -> Option<Vec<Value>> {
    let bytes = source.as_bytes();
    let off = offset as usize;

    // Walk backwards looking for `{` at paren depth 0, while checking
    // if we're inside an import/export specifier list
    let mut brace_depth: i32 = 0;
    let mut i = off;
    let mut open_brace_pos: Option<usize> = None;

    while i > 0 {
        i -= 1;
        match bytes[i] {
            b'}' => brace_depth += 1,
            b'{' => {
                if brace_depth == 0 {
                    open_brace_pos = Some(i);
                    break;
                }
                brace_depth -= 1;
            }
            // If we hit a semicolon or another statement boundary, stop
            b';' if brace_depth == 0 => return None,
            _ => {}
        }
    }

    let open_brace = open_brace_pos?;

    // Check what's before the `{` — look for `import` or `export`
    let mut p = open_brace;
    while p > 0 && bytes[p - 1].is_ascii_whitespace() {
        p -= 1;
    }

    // Check for `export` before `{`
    let is_export = if p >= 6 {
        let start = p - 6;
        &source[start..p] == "export" && (start == 0 || !is_ident_byte(bytes[start - 1]))
    } else {
        false
    };

    // Check for `import` before `{`, possibly with `type`
    // Patterns: `import {`, `import type {`
    let is_import = if !is_export {
        // Could be `import {` or `import type {`
        let mut ip = p;
        // Check for `type` keyword
        if ip >= 4 && &source[ip - 4..ip] == "type" && (ip < 5 || !is_ident_byte(bytes[ip - 5])) {
            ip -= 4;
            while ip > 0 && bytes[ip - 1].is_ascii_whitespace() {
                ip -= 1;
            }
        }
        if ip >= 6 {
            let start = ip - 6;
            &source[start..ip] == "import" && (start == 0 || !is_ident_byte(bytes[start - 1]))
        } else {
            false
        }
    } else {
        false
    };

    if !is_import && !is_export {
        return None;
    }

    // Find the `from "module"` part to know which module we're importing from
    // Look for `}` after the opening `{`, then `from`, then the module specifier
    let mut close_brace = off;
    let mut bd: i32 = 1;
    while close_brace < bytes.len() {
        match bytes[close_brace] {
            b'{' => bd += 1,
            b'}' => {
                bd -= 1;
                if bd == 0 {
                    break;
                }
            }
            _ => {}
        }
        close_brace += 1;
    }

    // Look for `from` after `}`
    let after_close = if close_brace < bytes.len() {
        close_brace + 1
    } else {
        bytes.len()
    };
    let rest = &source[after_close..];
    let rest_trimmed = rest.trim_start();

    if rest_trimmed.starts_with("from")
        && (rest_trimmed.len() <= 4 || !is_ident_byte(rest_trimmed.as_bytes()[4]))
    {
        // Found `from` — extract module specifier
        let after_from = rest_trimmed[4..].trim_start();
        let module_path = if after_from.starts_with('"') || after_from.starts_with('\'') {
            let quote = after_from.as_bytes()[0];
            let end = after_from[1..]
                .find(|c: char| c as u8 == quote)
                .map(|p| p + 1);
            end.map(|e| &after_from[1..e])
        } else {
            None
        };

        if let Some(_module) = module_path {
            // For export { ... } from "module", we need the exports of the source module
            // For import { ... } from "module", we need the exports of the module
            // Currently we can't resolve cross-file modules, so return a simplified response
            // that at least doesn't pollute with keywords and local scope variables

            // Collect what's already imported/exported in the specifier list
            let specifier_text = &source[open_brace + 1..off.min(close_brace)];
            let already_used: HashSet<&str> = specifier_text
                .split(',')
                .filter_map(|s| {
                    let s = s.trim();
                    if s.is_empty() {
                        return None;
                    }
                    // Handle `x as y` — the source name is `x`
                    let name = s.split_whitespace().next()?;
                    if name == "type" {
                        // `type X` — skip `type` keyword, get the actual name
                        s.split_whitespace().nth(1)
                    } else {
                        Some(name)
                    }
                })
                .collect();

            // For re-exports (`export { ... } from "mod"`), try to find symbols from the source
            // For now, return empty to avoid polluting with wrong items
            // This is better than returning all scope variables + keywords
            return Some(Vec::new());
        }
    }

    // For `export { ... }` WITHOUT `from` — should show local module exports
    if is_export {
        // Collect already-used names
        let specifier_text = &source[open_brace + 1..off.min(close_brace)];
        let already_used: HashSet<&str> = specifier_text
            .split(',')
            .filter_map(|s| {
                let s = s.trim();
                if s.is_empty() {
                    return None;
                }
                let name = s.split_whitespace().next()?;
                Some(name)
            })
            .collect();

        // Return local symbols that haven't been used yet
        let mut items = Vec::new();
        for sym in &sym_table.symbols {
            if sym.name.is_empty() || sym.name.starts_with("__") {
                continue;
            }
            if already_used.contains(sym.name.as_str()) {
                continue;
            }
            let kind = completion_kind_for_flags(sym.flags);
            items.push(json!({
                "label": &sym.name,
                "kind": kind,
            }));
        }
        return Some(items);
    }

    None
}

