    fn test_did_close_clears_diagnostics() {
        let msgs = vec![
            json!({
                "jsonrpc": "2.0",
                "id": 1,
                "method": "initialize",
                "params": { "capabilities": {} }
            }),
            json!({
                "jsonrpc": "2.0",
                "method": "textDocument/didOpen",
                "params": {
                    "textDocument": {
                        "uri": "file:///test.ts",
                        "languageId": "typescript",
                        "version": 1,
                        "text": "let x = 1;"
                    }
                }
            }),
            json!({
                "jsonrpc": "2.0",
                "method": "textDocument/didClose",
                "params": {
                    "textDocument": {
                        "uri": "file:///test.ts"
                    }
                }
            }),
            json!({
                "jsonrpc": "2.0",
                "id": 99,
                "method": "shutdown",
                "params": null
            }),
            json!({
                "jsonrpc": "2.0",
                "method": "exit",
                "params": null
            }),
        ];

        let responses = run_session(&msgs);

        // The last publishDiagnostics should have empty diagnostics array
        let diag_notifs: Vec<_> = responses
            .iter()
            .filter(|r| {
                r.get("method").and_then(|m| m.as_str()) == Some("textDocument/publishDiagnostics")
            })
            .collect();
        assert!(!diag_notifs.is_empty());
        let last = diag_notifs.last().unwrap();
        let diags = last["params"]["diagnostics"].as_array().unwrap();
        assert!(diags.is_empty(), "expected empty diagnostics after close");
    }

