    #[test]
    fn test_document_symbol_request() {
        let msgs = vec![
            json!({
                "jsonrpc": "2.0",
                "id": 1,
                "method": "initialize",
                "params": { "capabilities": {} }
            }),
            json!({
                "jsonrpc": "2.0",
                "method": "textDocument/didOpen",
                "params": {
                    "textDocument": {
                        "uri": "file:///test.ts",
                        "languageId": "typescript",
                        "version": 1,
                        "text": "function greet(name: string) { return name; }\nclass Foo { bar: number; }"
                    }
                }
            }),
            json!({
                "jsonrpc": "2.0",
                "id": 7,
                "method": "textDocument/documentSymbol",
                "params": {
                    "textDocument": { "uri": "file:///test.ts" }
                }
            }),
            json!({
                "jsonrpc": "2.0",
                "id": 99,
                "method": "shutdown",
                "params": null
            }),
            json!({
                "jsonrpc": "2.0",
                "method": "exit",
                "params": null
            }),
        ];

        let responses = run_session(&msgs);

        let sym_resp = responses.iter().find(|r| r.get("id") == Some(&json!(7)));
        assert!(sym_resp.is_some(), "expected documentSymbol response");
        let resp = sym_resp.unwrap();
        assert!(resp.get("result").is_some());
        if let Some(symbols) = resp["result"].as_array() {
            let names: Vec<&str> = symbols.iter().filter_map(|s| s["name"].as_str()).collect();
            assert!(
                names.contains(&"greet"),
                "expected 'greet' in document symbols, got {:?}",
                names
            );
            assert!(
                names.contains(&"Foo"),
                "expected 'Foo' in document symbols, got {:?}",
                names
            );

            // Foo should have children (bar property)
            let foo = symbols
                .iter()
                .find(|s| s["name"].as_str() == Some("Foo"))
                .unwrap();
            if let Some(children) = foo["children"].as_array() {
                let child_names: Vec<&str> =
                    children.iter().filter_map(|c| c["name"].as_str()).collect();
                assert!(
                    child_names.contains(&"bar"),
                    "expected 'bar' in Foo children, got {:?}",
                    child_names
                );
            }
        }
    }

