    #[test]
    fn test_signature_help_for_stdlib_member_rest_overload() {
        let file_name = "/test.ts";
        let source = "const layers = Object.assign({}, ...[]);";
        let offset = source.find("...").expect("spread arg") as u32;

        let mut options = CompilerOptions::default();
        options.target = Some(tsc_rs_ast::ScriptTarget::ESNext);

        let mut query_engine = QueryEngine::with_options(options.clone());
        query_engine
            .add_source(file_name.to_string(), source.to_string())
            .expect("source added");
        query_engine.check_all().expect("check_all succeeded");

        let fallback_sf = tsc_rs_parser::parse("__fallback__.d.ts", lib_stubs::LIB_STUBS);
        let fallback_symbols = tsc_rs_symbols::bind(&fallback_sf);
        assert!(
            fallback_symbols
                .symbols
                .iter()
                .any(|sym| sym.name == "ObjectConstructor"),
            "server fallback stubs did not bind ObjectConstructor"
        );
        assert!(
            query_engine
                .get_type_member_info("ObjectConstructor", "assign")
                .is_some(),
            "fallback stdlib member metadata missing"
        );

        let sf = tsc_rs_parser::parse(file_name, source);
        let sym_table = tsc_rs_symbols::bind(&sf);
        let check_out = query_engine
            .get_file_check_output(file_name)
            .expect("check output");

        let sig_help = signature_help_at(
            &query_engine,
            file_name,
            &sf,
            &sym_table,
            &check_out,
            source,
            offset,
        )
        .expect("signature help");

        let signatures = sig_help["signatures"].as_array().expect("signatures array");
        assert!(
            signatures.len() >= 4,
            "expected stdlib overloads, got {signatures:?}"
        );
        assert_eq!(sig_help["activeParameter"].as_u64(), Some(1));
        assert_eq!(sig_help["activeSignature"].as_u64(), Some(3));
        assert_eq!(
            signatures[3]["label"].as_str(),
            Some("assign(target: object, ...sources: any[]): any")
        );
    }

    #[test]
    fn test_signature_help_includes_jsdoc_docs() {
        let file_name = "/test.ts";
        let source = r#"
/**
 * Adds a label
 * @param value the numeric value
 * @param label the label text
 */
function foo(value: number, label: string): void {}
foo(1, "x");
"#;
        let offset = source.find("\"x\"").expect("second arg") as u32;

        let mut query_engine = QueryEngine::with_options(CompilerOptions::default());
        query_engine
            .add_source(file_name.to_string(), source.to_string())
            .expect("source added");
        query_engine.check_all().expect("check_all succeeded");

        let sf = tsc_rs_parser::parse(file_name, source);
        let sym_table = tsc_rs_symbols::bind(&sf);
        let check_out = query_engine
            .get_file_check_output(file_name)
            .expect("check output");

        let sig_help = signature_help_at(
            &query_engine,
            file_name,
            &sf,
            &sym_table,
            &check_out,
            source,
            offset,
        )
        .expect("signature help");

        let signature = &sig_help["signatures"][0];
        assert_eq!(
            signature["label"].as_str(),
            Some("foo(value: number, label: string): void")
        );
        assert_eq!(signature["documentation"].as_str(), Some("Adds a label"));
        assert_eq!(
            signature["parameters"][0]["documentation"].as_str(),
            Some("the numeric value")
        );
        assert_eq!(
            signature["parameters"][1]["documentation"].as_str(),
            Some("the label text")
        );
    }

