    #[test]
    fn test_file_cache_returns_cached_on_same_version() {
        let mut cache = FileCache::new();
        let uri = "file:///test.ts";
        let file_name = "/test.ts";
        let text = "let x = 42;";

        // First call should parse and cache
        let cached1 =
            cache.get_or_update(uri, 1, file_name, text, CompilerOptions::default(), None);
        assert_eq!(cached1.version, 1);
        let diag_count_1 = cached1.diagnostics.len();

        // Second call with same version should return cached data (no re-parse)
        let cached2 =
            cache.get_or_update(uri, 1, file_name, text, CompilerOptions::default(), None);
        assert_eq!(cached2.version, 1);
        assert_eq!(cached2.diagnostics.len(), diag_count_1);

        // Call with new version should re-parse
        let new_text = "let x: string = 42;";
        let cached3 = cache.get_or_update(
            uri,
            2,
            file_name,
            new_text,
            CompilerOptions::default(),
            None,
        );
        assert_eq!(cached3.version, 2);
    }

    #[test]
    fn test_file_cache_respects_no_lib() {
        let mut cache = FileCache::new();
        let uri = "file:///test.ts";
        let file_name = "/test.ts";
        let text = "Promise.resolve(1);";
        let mut options = CompilerOptions::default();
        options.no_lib = Some(true);

        let cached = cache.get_or_update(uri, 1, file_name, text, options, None);
        assert!(
            cached
                .query_engine
                .get_source_file("__lib__.d.ts")
                .is_none(),
            "noLib file should not load fallback libs into the query engine"
        );
        assert!(
            cached.query_engine.find_symbol("Promise").is_empty(),
            "noLib file should not expose Promise from injected stubs"
        );
    }

