    #[test]
    fn test_incremental_sync_capability() {
        let msgs = vec![
            json!({
                "jsonrpc": "2.0",
                "id": 1,
                "method": "initialize",
                "params": { "capabilities": {} }
            }),
            json!({
                "jsonrpc": "2.0",
                "id": 99,
                "method": "shutdown",
                "params": null
            }),
            json!({
                "jsonrpc": "2.0",
                "method": "exit",
                "params": null
            }),
        ];

        let responses = run_session(&msgs);
        let init_resp = &responses[0];
        let sync = &init_resp["result"]["capabilities"]["textDocumentSync"];
        assert_eq!(sync["change"], 2, "expected incremental sync (2)");
    }

    #[test]
    fn test_incremental_did_change() {
        let msgs = vec![
            json!({
                "jsonrpc": "2.0",
                "id": 1,
                "method": "initialize",
                "params": { "capabilities": {} }
            }),
            json!({
                "jsonrpc": "2.0",
                "method": "textDocument/didOpen",
                "params": {
                    "textDocument": {
                        "uri": "file:///test.ts",
                        "languageId": "typescript",
                        "version": 1,
                        "text": "let x = 1;"
                    }
                }
            }),
            // Send an incremental change: replace "1" with "42"
            // "1" is at line 0, chars 8..9
            json!({
                "jsonrpc": "2.0",
                "method": "textDocument/didChange",
                "params": {
                    "textDocument": {
                        "uri": "file:///test.ts",
                        "version": 2
                    },
                    "contentChanges": [
                        {
                            "range": {
                                "start": { "line": 0, "character": 8 },
                                "end": { "line": 0, "character": 9 }
                            },
                            "text": "42"
                        }
                    ]
                }
            }),
            // Hover to verify the document was updated correctly
            json!({
                "jsonrpc": "2.0",
                "id": 2,
                "method": "textDocument/hover",
                "params": {
                    "textDocument": { "uri": "file:///test.ts" },
                    "position": { "line": 0, "character": 4 }
                }
            }),
            json!({
                "jsonrpc": "2.0",
                "id": 99,
                "method": "shutdown",
                "params": null
            }),
            json!({
                "jsonrpc": "2.0",
                "method": "exit",
                "params": null
            }),
        ];

        let responses = run_session(&msgs);

        // Should have at least 2 publishDiagnostics (open + change)
        let diag_notifs: Vec<_> = responses
            .iter()
            .filter(|r| {
                r.get("method").and_then(|m| m.as_str()) == Some("textDocument/publishDiagnostics")
            })
            .collect();
        assert!(
            diag_notifs.len() >= 2,
            "expected at least 2 publishDiagnostics, got {}",
            diag_notifs.len()
        );

        // Hover response should exist
        let hover_resp = responses.iter().find(|r| r.get("id") == Some(&json!(2)));
        assert!(
            hover_resp.is_some(),
            "expected hover response after incremental change"
        );
    }

    #[test]
    fn test_document_store_incremental() {
        let mut store = DocumentStore::default();
        store.open("file:///a.ts".into(), 1, "hello world".into());

        // Apply an incremental change: replace "world" with "rust"
        let changes = vec![json!({
            "range": {
                "start": { "line": 0, "character": 6 },
                "end": { "line": 0, "character": 11 }
            },
            "text": "rust"
        })];
        store.change_incremental("file:///a.ts", 2, &changes);

        assert_eq!(store.get("file:///a.ts").unwrap().text, "hello rust");
        assert_eq!(store.get("file:///a.ts").unwrap().version, 2);
    }

