    #[test]
    fn test_workspace_projects_reload_root_after_tsconfig_change() {
        let temp = TestDir::new("watched-tsconfig");
        let root = temp.path();
        let root_str = root.to_str().expect("utf8 temp path");
        fs::write(root.join("tsconfig.json"), "{ \"files\": [\"a.ts\"] }\n")
            .expect("failed to write tsconfig");
        fs::write(root.join("a.ts"), "export const alpha = 1;\n").expect("failed to write a.ts");
        fs::write(root.join("b.ts"), "export function greet() { return 1; }\n")
            .expect("failed to write b.ts");

        let mut projects = WorkspaceProjects::from_roots(vec![root_str.to_string()]);
        let b_file = root.join("b.ts").to_string_lossy().into_owned();
        let initial_project = projects
            .project_for_file(&b_file)
            .expect("expected project root association for b.ts");
        assert!(
            !initial_project.files.contains_key(&b_file),
            "b.ts should not be loaded from the initial tsconfig"
        );

        fs::write(
            root.join("tsconfig.json"),
            "{ \"files\": [\"a.ts\", \"b.ts\"] }\n",
        )
        .expect("failed to update tsconfig");
        projects.handle_watched_file_change(
            root.join("tsconfig.json").to_str().expect("utf8 temp path"),
        );

        let project = projects
            .project_for_file(&b_file)
            .expect("expected b.ts after tsconfig reload");
        assert!(
            project.files.contains_key(&b_file),
            "expected reloaded project to include b.ts"
        );
    }

