    #[test]
    fn test_did_close_restores_project_file_from_disk() {
        let temp = TestDir::new("close-restores-project");
        let root = temp.path();
        fs::write(root.join("tsconfig.json"), "{ \"files\": [\"a.ts\"] }\n")
            .expect("failed to write tsconfig");
        fs::write(
            root.join("a.ts"),
            "export function greet(name: string) { return name; }\n",
        )
        .expect("failed to write source");

        let root_uri = filename_to_uri(root.to_str().expect("utf8 temp path"));
        let a_uri = filename_to_uri(root.join("a.ts").to_str().expect("utf8 temp path"));
        let msgs = vec![
            json!({"jsonrpc":"2.0","id":1,"method":"initialize","params":{
                "rootUri": root_uri,
                "capabilities":{}
            }}),
            json!({"jsonrpc":"2.0","method":"textDocument/didOpen","params":{
                "textDocument":{
                    "uri": a_uri,
                    "languageId":"typescript",
                    "version":1,
                    "text":"export function renamed(name: string) { return name; }\n"
                }
            }}),
            json!({"jsonrpc":"2.0","method":"textDocument/didClose","params":{
                "textDocument":{"uri": a_uri}
            }}),
            json!({"jsonrpc":"2.0","id":12,"method":"workspace/symbol","params":{
                "query":"greet"
            }}),
            json!({"jsonrpc":"2.0","id":13,"method":"workspace/symbol","params":{
                "query":"renamed"
            }}),
            json!({"jsonrpc":"2.0","id":99,"method":"shutdown","params":null}),
            json!({"jsonrpc":"2.0","method":"exit","params":null}),
        ];

        let responses = run_session(&msgs);

        let greet_resp = responses.iter().find(|r| r.get("id") == Some(&json!(12)));
        assert!(
            greet_resp.is_some(),
            "expected workspace/symbol greet response"
        );
        let greet_symbols = greet_resp.unwrap()["result"]
            .as_array()
            .expect("workspace/symbol should return an array");
        let greet_names: Vec<&str> = greet_symbols
            .iter()
            .filter_map(|s| s["name"].as_str())
            .collect();
        assert!(
            greet_names.contains(&"greet"),
            "expected disk symbol 'greet' after close, got {:?}",
            greet_names
        );

        let renamed_resp = responses.iter().find(|r| r.get("id") == Some(&json!(13)));
        assert!(
            renamed_resp.is_some(),
            "expected workspace/symbol renamed response"
        );
        let renamed_symbols = renamed_resp.unwrap()["result"]
            .as_array()
            .expect("workspace/symbol should return an array");
        let renamed_names: Vec<&str> = renamed_symbols
            .iter()
            .filter_map(|s| s["name"].as_str())
            .collect();
        assert!(
            !renamed_names.contains(&"renamed"),
            "expected unsaved symbol to be removed after close, got {:?}",
            renamed_names
        );
    }

    #[test]
    fn test_did_close_drops_non_project_file_from_workspace_symbols() {
        let temp = TestDir::new("close-drops-non-project-file");
        let root = temp.path();
        fs::write(root.join("tsconfig.json"), "{ \"files\": [\"a.ts\"] }\n")
            .expect("failed to write tsconfig");
        fs::write(root.join("a.ts"), "export const alpha = 1;\n").expect("failed to write a.ts");
        fs::write(root.join("b.ts"), "export function stray() { return 1; }\n")
            .expect("failed to write b.ts");

        let root_uri = filename_to_uri(root.to_str().expect("utf8 temp path"));
        let b_uri = filename_to_uri(root.join("b.ts").to_str().expect("utf8 temp path"));
        let msgs = vec![
            json!({"jsonrpc":"2.0","id":1,"method":"initialize","params":{
                "rootUri": root_uri,
                "capabilities":{}
            }}),
            json!({"jsonrpc":"2.0","method":"textDocument/didOpen","params":{
                "textDocument":{
                    "uri": b_uri,
                    "languageId":"typescript",
                    "version":1,
                    "text":"export function stray() { return 1; }\n"
                }
            }}),
            json!({"jsonrpc":"2.0","id":12,"method":"workspace/symbol","params":{
                "query":"stray"
            }}),
            json!({"jsonrpc":"2.0","method":"textDocument/didClose","params":{
                "textDocument":{"uri": b_uri}
            }}),
            json!({"jsonrpc":"2.0","id":13,"method":"workspace/symbol","params":{
                "query":"stray"
            }}),
            json!({"jsonrpc":"2.0","id":99,"method":"shutdown","params":null}),
            json!({"jsonrpc":"2.0","method":"exit","params":null}),
        ];

        let responses = run_session(&msgs);
        let open_resp = responses.iter().find(|r| r.get("id") == Some(&json!(12)));
        assert!(
            open_resp.is_some(),
            "expected workspace/symbol response while open"
        );
        let open_symbols = open_resp.unwrap()["result"]
            .as_array()
            .expect("workspace/symbol should return an array");
        let open_names: Vec<&str> = open_symbols
            .iter()
            .filter_map(|symbol| symbol["name"].as_str())
            .collect();
        assert!(
            open_names.contains(&"stray"),
            "expected open non-project file symbol, got {:?}",
            open_names
        );

        let closed_resp = responses.iter().find(|r| r.get("id") == Some(&json!(13)));
        assert!(
            closed_resp.is_some(),
            "expected workspace/symbol response after close"
        );
        let closed_symbols = closed_resp.unwrap()["result"]
            .as_array()
            .expect("workspace/symbol should return an array");
        let closed_names: Vec<&str> = closed_symbols
            .iter()
            .filter_map(|symbol| symbol["name"].as_str())
            .collect();
        assert!(
            !closed_names.contains(&"stray"),
            "expected closed non-project file to drop from workspace symbols, got {:?}",
            closed_names
        );
    }

